GR_SC.g01_01=[{w:null,t:"まっ暗な石の通路。"},{w:null,t:"つきあたりの壁のあたりから、大きな生き物の寝息のような、低い音。"},{w:null,t:"世界のどこかの地面の下では、大昔の生き物が、まだ眠っている。",v:"01_0032"},{w:null,t:"2100年の地球。"},{w:null,t:"研究所で生まれた生き物「テリオン」は、世界じゅうの町で、人と暮らしている。",v:"01_0035"},{w:null,t:"大きな街のビルの壁に、テリオンどうしの勝負の配信。"},{w:null,t:"少年は、客席のいちばん上の一つの席だけを見上げている。"},{w:null,t:"日本の地図。"},{w:null,t:"日本を、のぞいて。",v:"01_0040"}];
GR_SC.g01_02=[{w:null,t:"ギリシャ。オリーブの村、オリーヴァ。",v:"01_0043"},{w:null,t:"青い海。白い家の坂道に、屋台が並ぶ。"},{w:null,t:"坂の上から、スーツケースを引いた男の子が下りてくる。"},{w:null,t:"オリーブの屋台のおばさん（日差しで色が変わるうすい上着の、2100年の普段着）が、ヤマトに声をかける。"},{w:"x",n:"屋台のおばさん",t:"あんた、ひとりかい？　そんな大きな荷物引いて、どこから来たの。",v:"01_0047"},{w:"hero",t:"日本から！",v:"01_0048"},{w:"hero",t:"ねえおばちゃん、この村、テリオンいっぱいいる？",v:"01_0049"},{w:null,t:"おばさん、坂の上を指さす。"},{w:"hero",f:"smile",t:"すっげー……本物だ。",v:"01_0051"},{w:"x",n:"屋台のおばさん",t:"ほら、オリーブお食べ。腰をぬかすのは、まだ早いよ。",v:"01_0052"},{w:null,t:"ヤマト、オリーブを一つつまむ。"},{w:"x",n:"屋台のおばさん",t:"あっ、また、あの泥棒！　こらー！　今日はいくつ持ってった！",v:"01_0054"},{w:"hero",f:"surprised",t:"なにあれ！？　しっぽ、燃えてんじゃん！",v:"01_0055"},{w:null,t:"坂の下で、急ブレーキの音。"},{w:null,t:"車から、二人組が降りてくる。"},{w:null,t:"市場の人たちが、さっと道をあける。"},{w:"x",n:"八百屋のおじさん",t:"ヴィクター一味だ……。",v:"01_0059"},{w:"x",n:"屋台のおばさん",t:"あんた、こっちに下がってな。",v:"01_0060"},{w:"x",n:"屋台のおばさん",t:"先週は、パン屋の猫の子が連れていかれた。",v:"01_0061"},{w:null,t:"マルコ、鳥の子の店番がいる屋台の前を通りかかる。"},{w:"marco",t:"これも、もらっとくぜ。",v:"01_0063"},{w:"x",n:"八百屋のおじさん",t:"おい、それはうちの——！",v:"01_0064"},{w:"nina",t:"なんか言った？　おじさん。",v:"01_0065"},{w:null,t:"ニーナ、おじさんの屋台のトマトの山を、足でけとばす。"},{w:"hero",t:"（小声で）なんで、だれも止めねーの？",v:"01_0067"},{w:"x",n:"屋台のおばさん",t:"（小声で）逆らったら、次はうちの子が連れてかれるのさ。",v:"01_0068"},{w:"nina",t:"あたしたちの用は、あの狐よ。",v:"01_0069"},{w:"marco",t:"今日こそ、つかまえてやるぜ。",v:"01_0070"},{w:null,t:"ニーナ、手首の画面を動かす。"},{w:"nina",t:"右！　右から回りなさいよ！",v:"01_0072"},{w:null,t:"ドローン三機が、狐を追って坂を下りる。"},{w:null,t:"狐、マルコの頭を踏み台にして、まっすぐ坂の上へ。"},{w:null,t:"狐が、ヤマトの顔に正面からぶつかる。"},{w:null,t:"狐、ヤマトのおなかの上に着地する。目と目が合う。"},{w:"hero",f:"hurt",t:"うわっ、熱っ……！",v:"01_0078"},{w:null,t:"狐、ヤマトの顔を踏んで、跳んでいく。"},{w:null,t:"ヤマト、起き上がる。目が、さっきの倍、きらきらしている。"},{w:"hero",t:"あいつ、追っかける！　おばちゃん、荷物見てて！",v:"01_0081"},{w:"x",n:"屋台のおばさん",t:"ちょっと、あんた！　ヴィクターの前に出ちゃだめだって！",v:"01_0082"},{w:null,t:"ヤマト、服を散らかしたまま、走りだす。"},{w:null,t:"第1話　狐と焦げたオリーブ",v:"01_0085"}];
GR_SC.g01_03=[{w:null,t:"狐。そのうしろにドローン三機。"},{w:"marco",t:"ニーナ、なんか子どもがついてくるぜ。",v:"01_0092"},{w:"nina",t:"子どもなんか、ほっときなさいよ。狐が先でしょ！",v:"01_0093"},{w:"hero",t:"おーい、待てよー！　ちょっとさわるだけだって！",v:"01_0094"},{w:"x",n:"子ども1",t:"あの子、ヴィクター一味より速いよ！",v:"01_0095"},{w:null,t:"ドローンが網を落とす。狐、ふり向きざまに、しっぽから小さな火をとばす。"},{w:"marco",t:"あー！　また網、燃やされた！",v:"01_0097"},{w:"nina",t:"うるさい！　次は上からよ！",v:"01_0098"},{w:null,t:"狐のしっぽが、今度はヤマトに向く。"},{w:null,t:"前髪の右はしの一房が、ちりっと焦げる。"},{w:"hero",f:"hurt",t:"あちっ！　……今の見た！？　火、とばした！",v:"01_0101"},{w:"x",n:"子ども2",t:"前髪、焦げてるよ！",v:"01_0102"},{w:"hero",t:"いいって、前髪なんか！　火だぞ、火！",v:"01_0103"},{w:null,t:"狐の口から、半分焦げたオリーブが一つ落ちる。"}];
GR_SC.g01_04=[{w:null,t:"村の上の、古い神殿のあと。",v:"01_0107"},{w:null,t:"坂のてっぺん。"},{w:null,t:"狐、その木の根もとに逃げこむ。くわえてきたオリーブを、しっぽの火の上に乗せる。"},{w:null,t:"根もとに入ったとたん、しっぽの火が、ぼっと一回りふくらむ。"},{w:null,t:"ヤマト、息を切らして追いつく。"},{w:null,t:"狐が、根もとから一歩だけ枯れ草の上へ出る。"},{w:null,t:"ヤマト、目をまるくして、それを見ている。……が、すぐ顔がゆるむ。"},{w:"hero",t:"おまえ、ここが好きなのか？",v:"01_0114"},{w:"hero",t:"大丈夫、おれ、あいつらの仲間じゃないから。",v:"01_0115"},{w:"hero",t:"ほら、なんにもしないって。",v:"01_0116"},{w:"hero",t:"よーし、いい子だ。そのまま、そのまま……。",v:"01_0118"},{w:"hero",f:"hurt",t:"いってえ！",v:"01_0120"}];
GR_SC.g01_05=[{w:null,t:"石段の下から、ごろごろと音。"},{w:null,t:"エリー、白い上着に、水色のブラウスとプリーツスカート。"},{w:null,t:"金の長いウェーブの髪に、白いリボン一つ。"},{w:"elly",t:"あ、いたいた！　ねえ、これ、きみのでしょ？",v:"01_0128"},{w:"elly",t:"オリーブのおばさんから預かってきたよ。",v:"01_0129"},{w:"hero",t:"あ……サンキュ。わざわざ持ってきてくれたのか？",v:"01_0130"},{w:"elly",t:"おばさん、大さわぎしてたんだもん。",v:"01_0131"},{w:"elly",t:"「男の子が荷物置いて、狐を追っかけてった」って。",v:"01_0132"},{w:"elly",t:"……って、ちょっと、その右手！　赤くなってる！",v:"01_0133"},{w:"hero",t:"ああ、これ？　なでようとしたら、狐にガブッとやられた。",v:"01_0134"},{w:"elly",t:"やられたのに、なんでそんな、うれしそうなの！　ほら、すわって！",v:"01_0135"},{w:null,t:"ヤマト、木の根もとに座らされる。エリー、ヤマトの右手を取って、カバンを開ける。"},{w:"elly",t:"しみるよ。がまんしてね。",v:"01_0137"},{w:"hero",t:"いっ……！　しみる、しみる！",v:"01_0138"},{w:"elly",t:"あの子、フォルン。だれにもさわらせないの。",v:"01_0139"},{w:"elly",t:"わたしなんか、三年、毎日クッキー持ってきてるんだよ。",v:"01_0140"},{w:null,t:"根もとの石のくぼみに、クッキーが一枚。"},{w:"hero",t:"フォルンか。かっこいい名前だな！",v:"01_0142"},{w:null,t:"木の上で、フォルンの耳が、ぴくっとこっちを向く。"},{w:null,t:"【プロフィール】フォルン／炎／●○○／しっぽの火で気持ちが分かる"},{w:"elly",t:"本気で怒ると、フレイガっていう火、吹くんだって。",v:"01_0145"},{w:"elly",t:"見たことないけど。",v:"01_0146"},{w:null,t:"木の上のフォルン、ふんと鼻を鳴らす。しっぽの火が、ぼっ。"},{w:null,t:"ヤマト、木の上を見上げる。口が、「フレイガ」の形に動く。"},{w:"elly",t:"フォルン、何回もねらわれてるんだよ。",v:"01_0149"},{w:"hero",t:"だれも守ってやんねーの？",v:"01_0150"},{w:"elly",t:"みんな、自分の子を守るだけで手いっぱいなんだよ。",v:"01_0151"},{w:"elly",t:"で、きみは？　観光？",v:"01_0153"},{w:"hero",t:"観光っていうか、テリオン見に来たんだよ。日本にはいねーし。",v:"01_0154"},{w:null,t:"エリーの手が止まる。"},{w:"elly",t:"ちょっと待って。日本から来た男の子って……。",v:"01_0156"},{w:"elly",t:"きみ、もしかして、ヤマト？",v:"01_0157"},{w:"hero",t:"え、なんでおれの名前知ってんの。",v:"01_0158"},{w:"elly",t:"わたし、エリー！　うち、ホテルやってるの！",v:"01_0159"},{w:"elly",t:"きみのおじいちゃんに頼まれて、空港でずっと待ってたんだよ！",v:"01_0160"},{w:"hero",f:"serious",t:"……迎え？　聞いてねえ。",v:"01_0161"},{w:"elly",t:"どこから出たの！",v:"01_0162"},{w:"hero",t:"ふつうに出たよ。",v:"01_0163"},{w:null,t:"ヤマト、手首の画面をつける。"},{w:"elly",t:"名前のとこで切れてるけど、このホテル、うちのことだよ。",v:"01_0165"},{w:"hero",t:"なんで、そこで切れるんだよ……。",v:"01_0166"},{w:"elly",t:"で、おじいちゃんは？",v:"01_0167"},{w:"hero",t:"知らねえ。",v:"01_0168"},{w:"hero",t:"たぶん、またどっかで飛行機いじってる。",v:"01_0169"},{w:null,t:"ヤマトは、話しながらも、木の上のフォルンばかり見ている。"},{w:null,t:"エリー、ヤマトの目の先を追って、ため息。"}];
GR_SC.g01_06=[{w:null,t:"エリー、倒れた柱の古い字を、指でなぞっている。"},{w:"hero",t:"なにそれ。",v:"01_0178"},{w:"elly",t:"昔の字。いつか、ぜんぶ読むの。",v:"01_0179"},{w:"hero",t:"ふーん。",v:"01_0180"},{w:null,t:"手首の画面に、なぞった字が一つずつ写る。"},{w:null,t:"ヤマト、ポケットをさぐる。"},{w:"hero",t:"これ、さっきあいつが落としたやつ。",v:"01_0183"},{w:"elly",t:"それで、どうするの？",v:"01_0184"},{w:"hero",f:"serious",t:"……見てろって。",v:"01_0185"},{w:null,t:"ヤマト、オリーブを手のひらに乗せて、ひざの上に置く。"},{w:null,t:"フォルン、木から下りてくる。"},{w:"elly",t:"（小声で）ほら、やっぱり食べない。",v:"01_0188"},{w:"hero",t:"（小声で）しっ。",v:"01_0189"},{w:null,t:"フォルン、オリーブをくわえて、自分のしっぽの火の上に落とす。"},{w:null,t:"くわえ直して、ヤマトの手のひらの上で、かりっと食べる。"},{w:"hero",t:"食った。おれの手の上で、食った！",v:"01_0192"},{w:"elly",f:"surprised",t:"うそでしょ……。焦がしたのが好きだったの？",v:"01_0193"}];
GR_SC.g01_07=[{w:null,t:"ブーンと、羽の音。"},{w:"marco",t:"はあ、はあ……坂、長すぎだろ……。",v:"01_0197"},{w:"nina",t:"いた。……なんで子どもが、狐にエサやってんのよ。",v:"01_0198"},{w:null,t:"フォルン、身がまえる。耳がうしろに倒れる。"},{w:"nina",t:"ちょっと、そこのチビ。その狐、よこしなさい！",v:"01_0200"},{w:"hero",t:"やだね！",v:"01_0201"},{w:"nina",t:"へえ。痛い目、見たいわけ？",v:"01_0202"},{w:"elly",t:"ヤマト、その子を連れて逃げて！",v:"01_0203"},{w:null,t:"ニーナ、手首の画面を、指で大きくはじく。"},{w:"nina",t:"マルコ、どいて！　囲むわよ！",v:"01_0205"},{w:null,t:"三機のドローンが、フォルンを三方から囲む。"},{w:null,t:"二機目のドローンが、ヤマトとフォルンの真上へ回る。"},{w:"elly",t:"ヤマト、上！",v:"01_0208"},{w:null,t:"エリー、肩かけカバンをふり回して、ドローンの網の口に引っかける。"},{w:null,t:"ドローン、カバンの重さでかたむいて、網を横にこぼす。"},{w:null,t:"カバンが枯れ草に落ちる。"},{w:null,t:"ヤマトの肩ごしに、フォルンの目が、網と二人組を見る。"},{w:null,t:"ヤマト、立ち上がる。"},{w:"hero",t:"やだって言ってんだろ！　こいつは、ぜってー渡さねー！",v:"01_0214"},{w:"nina",t:"えらそうに。その手、ばんそうこうだらけじゃない。",v:"01_0215"},{w:"nina",t:"しょうがないわね。",v:"01_0216"},{w:"nina",t:"じゃあ、力ずくでもらうわよ。",v:"01_0217"},{w:null,t:"オリーブの林の中から、がさがさと音。"},{w:"nina",t:"出番よ、クマッパ！",v:"01_0219"},{w:null,t:"【プロフィール】クマッパ／森／●○○／力じまんの小さなクマ"},{w:null,t:"フォルン、ヤマトの足もとから、すっと前に出る。二本のしっぽを立てて、クマッパをにらむ。"},{w:"hero",f:"serious",t:"……やってくれんのか！　よっしゃ！",v:"01_0222"},{w:"hero",t:"いっけー、フォルン！",v:"01_0223"},{w:null,t:"ヤマトとエリー、神殿の石の床まで下がる。"},{w:null,t:"神殿の柱のかげに、市場の子どもたちが三人、しゃがんで並ぶ。"}];
GR_SC.g01_09=[{w:null,t:"柱のかげから、市場の子どもたちが走ってくる。"},{w:"x",n:"子ども1",t:"ヴィクター一味に、勝っちゃった！",v:"01_0280"},{w:"x",n:"子ども2",t:"林から出たら、つる、届いてなかった！",v:"01_0281"},{w:"x",n:"子ども3",t:"泥棒狐、すげー！",v:"01_0282"},{w:null,t:"ニーナ、ひっくり返ったクマッパを抱き上げる。目を回したまま。"},{w:"nina",t:"よくやったわ。休んでなさい。",v:"01_0284"},{w:null,t:"ニーナ、目を回したクマッパを、両腕でかかえ直す。"},{w:"nina",t:"覚えてなさいよ、チビ。",v:"01_0286"},{w:"nina",t:"ヴィクター一味に逆らって、ただで済むと思わないことね。",v:"01_0287"},{w:"hero",t:"何回来たって、同じだ！　なあ、フォルン！",v:"01_0288"},{w:null,t:"ヤマト、フォルンの方へ、得意げに親指を立てて見せる。"},{w:null,t:"胸を張るヤマト。フォルン、その顔を一回だけ見上げる。"},{w:null,t:"ヤマト、胸を張ったまま、口から黒い煙をぽふっと吐く。"},{w:null,t:"フォルン、ヤマトの前を素通りして、マルコの前へ。しっぽを、ぴんと立てる。"},{w:"marco",t:"あ。",v:"01_0293"},{w:null,t:"ぽっ。マルコのお尻に、小さな火。"},{w:"marco",t:"あちちちちっ！　ニーナーっ！",v:"01_0295"},{w:"nina",t:"マルコ、置いてくわよ！",v:"01_0296"},{w:null,t:"二人組、石段を転げるように逃げていく。子どもたちが、声をそろえて笑う。"},{w:null,t:"ヤマト、にやにやしながら、フォルンに手をのばす。"},{w:"hero",f:"smile",t:"やったな、フォルン！　ほら、ちょっとだけ——",v:"01_0299"},{w:null,t:"フォルン、喉の奥で、ぐるる。"},{w:null,t:"ヤマト、手を引っこめる。"},{w:"elly",t:"フォルン、かまなかったね。さっきより進歩だよ。",v:"01_0303"},{w:"hero",t:"だろ？　そのうち、なでさせてくれるって。",v:"01_0304"},{w:null,t:"エリー、枯れ草の上のカバンとクッキーの箱を拾う。"},{w:"elly",t:"さ、ホテル行こ。お姉ちゃん、ずっと待ってるから。",v:"01_0306"},{w:null,t:"二人、坂を下りはじめる。"}];
GR_SC.g01_10=[{w:null,t:"坂の下に止めた黒塗りのロボタクシー。"},{w:"marco",t:"ボスに、なんて言うんだよ？",v:"01_0313"},{w:"marco",t:"狐はとれませんでした、って言うのか？",v:"01_0314"},{w:null,t:"ニーナ、手首の画面に、ドローンが撮った写真を出す。少年の前に立って、しっぽを立てる狐。"},{w:"nina",t:"だれにもなつかない野良が、あのチビの前に出たのよ。",v:"01_0316"},{w:"marco",t:"それって、まずいのか？",v:"01_0317"},{w:"nina",t:"まずいどころじゃないわよ。ボスが一番ほしがる話じゃないの。",v:"01_0318"},{w:"nina",t:"これなら、手ぶらでも怒られないわ。",v:"01_0319"},{w:null,t:"ニーナ、送り先を選ぶ。"}];
GR_SC.g01_11=[{w:null,t:"その夜。坂の上の、小さなホテル。",v:"01_0323"},{w:null,t:"ホテルの一階のはしの、小さな部屋。"},{w:null,t:"ヤマト、戸を開ける。"},{w:"elly",t:"その図鑑、お姉ちゃんが置いといてくれたの。",v:"01_0326"},{w:"elly",t:"「日本の子なら、きっと読むから」って。",v:"01_0327"},{w:"hero",t:"お姉ちゃんって、さっき受付にいた人？",v:"01_0328"},{w:"elly",t:"そう、アナ。このホテル、お姉ちゃんが一人でやってるの。",v:"01_0329"},{w:null,t:"ヤマト、図鑑をひらく。"},{w:null,t:"ヤマト、色のぬってある国を、指で一つずつ、なぞっていく。ギリシャで、指が一度止まる。"},{w:null,t:"ヤマト、地図の上の色のぬってある国ぜんぶを、手のひらでばんっとたたく。"},{w:"hero",t:"おれ、世界一のテリオンマスターになるんだ。",v:"01_0333"},{w:"elly",f:"serious",t:"……本物見たの、今日が初めてなのに？",v:"01_0334"},{w:"hero",t:"だから、なるんだよ。",v:"01_0335"},{w:null,t:"ヤマト、図鑑を一枚めくる。"},{w:null,t:"手首の画面のすみに、大会の配信の切り抜きが一つ、ぽんと出る。"},{w:null,t:"黒いコートの少年と、岩の鱗の大きな蛇。"},{w:null,t:"ヤマト、図鑑を閉じかけた手を止める。"},{w:null,t:"窓の外。ぶどう畑の柵の上に、フォルンが丸くなっている。"},{w:"elly",t:"見て。あの子、ここまでついてきてる。",v:"01_0342"},{w:"hero",t:"友達だからな。",v:"01_0343"},{w:null,t:"柵の上のフォルン、大きく口をあけて、あくび。"},{w:"elly",f:"serious",t:"……友達、あくびしてるよ。",v:"01_0345"},{w:"hero",f:"angry",t:"うっせ。",v:"01_0346"},{w:null,t:"エリー、笑って戸を閉める。"},{w:null,t:"スーツケースの中身を、ベッドにあける。"},{w:null,t:"ヤマト、戸を開けて、ろうかのエリーを呼びとめる。"},{w:"hero",t:"エリー、ちょっと見て。",v:"01_0350"},{w:"hero",t:"おれの画面に、知らないアプリが入ってる。",v:"01_0351"},{w:"elly",t:"え、どれ？　どこから来たの？",v:"01_0352"},{w:"hero",t:"知らねえ。こんなの、見たこともない。",v:"01_0353"},{w:"hero",t:"……じいちゃんだな。空港で、おれの画面いじってたし。",v:"01_0354"},{w:null,t:"アイコンを押しても、何も開かない。"},{w:null,t:"柵の上のフォルンの耳が、ヤマトではなく、手首の画面の方へ、ぴんと向く。"}];
GR_SC.g01_12=[{w:null,t:"窓のない暗い部屋。"},{w:null,t:"並びの中に、パンの棚の前で丸くなった、猫の子の写真。"},{w:null,t:"そのとなりが、一つだけ、空いている。"},{w:null,t:"空いたすき間に、写真が一枚、すっと入る。少年の前に立って、しっぽを立てる狐。"},{w:null,t:"写真から細い線がのびて、画面のすみの、名前の並びの「アレク」の横で止まる。"}];
GR_BT[1]={mid:[[{w:"nina",t:"クマッパ、つる！",v:"01_0229"},{w:"hero",t:"もっと近くだ、フォルン！",v:"01_0233"},{w:"elly",t:"フォルンの足、紫になってる！",v:"01_0236"},{w:"nina",t:"ふふん。",v:"01_0237"}],[{w:"hero",t:"負けんな、フォルン！　行け！　行けって！",v:"01_0238"},{w:"x",n:"子ども2",t:"当たった！",v:"01_0240"},{w:"hero",t:"逃げたぞ！　追え、フォルン！",v:"01_0242"},{w:"hero",t:"なにやってんだよ、行けって！",v:"01_0244"},{w:"elly",t:"ヤマト、だめ！　林の中、つるだらけだよ！",v:"01_0245"},{w:null,t:"ヤマトの口が、「行け」の形のまま止まる。"},{w:null,t:"ヤマト、自分のひざを、こぶしで一回たたく。"},{w:null,t:"ヤマト、口を閉じる。"},{w:null,t:"ヤマト、身を乗り出しかける。……やめる。"}],[{w:"hero",t:"まだだ、フォルン。そこにいろ。",v:"01_0255"},{w:"nina",t:"ちっ……。",v:"01_0257"},{w:null,t:"ニーナの目が、それを見る。"},{w:"nina",t:"クマッパ、行きなさい！",v:"01_0262"},{w:null,t:"ヤマトの目が、クマッパの手もとに行く。"},{w:null,t:"ヤマト、クマッパの手もとを指さす。"},{w:"hero",t:"フォルン、フレイガ！",v:"01_0267"},{w:"nina",t:"なにしてんのよ、立ちなさい、クマッパ！",v:"01_0271"}]],post:[{w:null,t:"クマッパ、枯れ草の上で、あおむけにひっくり返る。目がぐるぐる。"},{w:null,t:"枯れ草に火が走りかける。フォルンがしっぽをひと振りする。"},{w:"elly",f:"smile",t:"勝った……。",v:"01_0275"},{w:"hero",f:"smile",t:"勝った！！　フォルン、勝ったぞ！",v:"01_0276"}]};
GR_EP[1]={"t": "狐と焦げたオリーブ", "sc": [["g01_01", "語り", 0], ["g01_02", "オリーヴァ村・市場の坂（昼）", 0], ["g01_03", "坂道の追いかけっこ", 0], ["g01_04", "神殿のあとの丘", 0], ["g01_05", "同じ場所・女の子", 0], ["g01_06", "同じ場所・手のひらのオリーブ", 0], ["g01_07", "丘・ヴィクター一味", 0], ["g01_08", "勝負", 1], ["g01_09", "勝負のあと", 0], ["g01_10", "黒塗りのロボタクシーの中（夕方）", 0], ["g01_11", "坂の上のホテル・一階のはしの部屋（夜）", 0], ["g01_12", "窓のない部屋（夜）", 0]]};
GR_SC.g02_01=[{w:null,t:"その向こうで、二本のしっぽの火が、じゅっと細くなる。"}];
GR_SC.g02_02=[{w:null,t:"オリーヴァ村。坂の上のホテルの朝。",v:"02_0053"},{w:null,t:"裏のぶどう畑。"},{w:null,t:"エリーが、パンとオリーブの皿を持ってのぞきこむ。"},{w:"elly",t:"ヤマト？　まさか、ひと晩じゅうここにいたの？",v:"02_0056"},{w:"hero",t:"見張ってたんだよ。",v:"02_0057"},{w:"hero",t:"ヴィクター一味が、また来るかもしれないだろ。",v:"02_0058"},{w:null,t:"フォルン、起き上がる。"},{w:"hero",t:"かっけえ……。",v:"02_0060"},{w:"elly",f:"serious",t:"……ほんとに、焦がしたのが好きなんだね。",v:"02_0061"},{w:null,t:"二階の窓が、ばんと開く。"},{w:"ana",t:"エリー！　お客さんの朝ごはん！　日本の子の分も！",v:"02_0063"},{w:"elly",t:"はーい、お姉ちゃん！",v:"02_0064"},{w:null,t:"第2話　競技場の地下",v:"02_0066"}];
GR_SC.g02_03=[{w:null,t:"白い壁の小さな食堂。"},{w:null,t:"エリーの長い髪のかげから、うす茶色の、まんまるの毛玉が、そっと顔を出す。"},{w:"hero",f:"surprised",t:"うわっ！　なんだそれ、いつからいたんだよ！？",v:"02_0074"},{w:"elly",t:"ずっといたよ。ピリポン。こわがりなの。",v:"02_0075"},{w:null,t:"【プロフィール】ピリポン／雷／●○○／こわがりで、すぐビリリ"},{w:"elly",t:"寝てる時は、さわっちゃだめ。びりってするから。",v:"02_0077"}];
GR_SC.g02_04=[{w:null,t:"古いソファと、壁の大きな画面。"},{w:null,t:"ヤマト、エリーを見る。"},{w:null,t:"指先が、毛にふれる。ピリポンの目が、ぱちっと開く。"},{w:null,t:"ヤマトの前髪が、まっすぐ上に立つ。"},{w:null,t:"画面のお知らせが切りかわる。"},{w:"ana",t:"ヴィクター一味よ。パン屋の猫の子も、あいつら。",v:"02_0085"},{w:"hero",t:"じゃあ、おれがフォルンの相棒になる！　そしたら守れる！",v:"02_0086"},{w:null,t:"カウンターの横の窓口の板に、光る字。"},{w:"ana",t:"相棒は、テリオンの方が選ぶのよ。",v:"02_0088"},{w:"ana",t:"大会で優勝した子だけは、年に関係なく登録できるけどね。",v:"02_0096"},{w:"hero",t:"それ出る！　おれ、それ出る！",v:"02_0098"},{w:"elly",t:"その前に、おばあちゃんち！　呼ばれてるの。",v:"02_0099"}];
GR_SC.g02_05=[{w:null,t:"村のいちばん上の丘。",v:"02_0102"},{w:null,t:"段々のオリーブ畑。"},{w:null,t:"ヤマトの手のちらしは、もう、くしゃくしゃ。"},{w:null,t:"畑のまん中に、石でかこんだ小さなため池。"},{w:null,t:"フォルン、池のふちへ。水に顔を近づける。"},{w:null,t:"池の向こう、丘の頂上に、白い大きな建物のあと。"},{w:"elly",t:"昔の研究所。おばあちゃん、前にあそこで働いてたの。",v:"02_0108"},{w:null,t:"フォルンの耳が、建物の方へ、ぴくっと動く。"}];
GR_SC.g02_06=[{w:null,t:"丘の向こうの、小さな石の家。"},{w:"elly",t:"おばあちゃーん！　つれてきたよ！",v:"02_0113"},{w:null,t:"おばあさん、ヤマトの顔をじっと見る。"},{w:"oba",t:"……両方、焦げてるね。",v:"02_0115"},{w:"hero",t:"こっちは狐で、こっちはピリポン。",v:"02_0116"},{w:null,t:"家の中。研究の記録の板と、データの箱が、どこにでも積んである。棚の写真の画面に、白い建物の前で笑う白衣の若い人が三人。"},{w:null,t:"ヤマト、くしゃくしゃのちらしをテーブルに置く。"},{w:"hero",f:"serious",t:"……白い都、行きたいんだ。",v:"02_0119"},{w:null,t:"おばあさん、ちらしの「年れい不問」の字を見る。それから、ヤマトの手を見る。"},{w:"oba",t:"……エリー。一緒に行っておいで。",v:"02_0121"},{w:"elly",t:"うん！",v:"02_0122"},{w:null,t:"窓の外。庭の洗濯物の上を、黒いドローンが一台、ゆっくり横切る。"},{w:"oba",t:"……あの黒いの、今朝からうちの上を回ってる。",v:"02_0124"},{w:"oba",t:"あしたの夜、森の道から出な。",v:"02_0125"},{w:null,t:"ヤマトの手首の画面が、ひとりでに光る。"},{w:null,t:"いすから立ち上がりかけていたおばあさんが、そのまま止まる。"},{w:null,t:"アイコンの中で、針が一本だけ、かちりと動く。"},{w:"hero",t:"じいちゃんのアプリ。押しても開かねえ。",v:"02_0130"},{w:"oba",t:"……古い形の時計だね。消さずに、大事にしな。",v:"02_0131"},{w:null,t:"窓の外。庭のオリーブの根もとで、フォルンが、しっぽの火で実を焼いている。"}];
GR_SC.g02_07=[{w:null,t:"同じころ、遠くの丘。",v:"02_0135"},{w:null,t:"丘の上。若い男が一人、古い小さな望遠鏡で星を見ている。顔は半分しか見えない。"},{w:null,t:"男の手首の画面が鳴る。マークも顔も名前も出ない。"},{w:"x",n:"画面の声",t:"アレク、急ぎの仕事だ。",v:"02_0138"},{w:"x",n:"画面の声",t:"オリーヴァ村の丘に、狐が一匹いる。",v:"02_0140"},{w:"x",n:"画面の声",t:"昔、逃げた子だ。運べ。",v:"02_0142"},{w:null,t:"画面のすみに、少年の前に立って、しっぽを立てる狐の写真。"},{w:"alek",t:"運ぶのは、狐だけっすか。",v:"02_0144"},{w:"x",n:"画面の声",t:"狐だけだ。払いは、いつもの研究費に上乗せしておく。",v:"02_0145"},{w:"alek",t:"急ぎなら、二割増しっす。",v:"02_0146"},{w:"x",n:"画面の声",t:"……一割だ。",v:"02_0147"},{w:"alek",t:"……うす。",v:"02_0148"},{w:null,t:"アレク、望遠鏡をのぞいたまま、写真を開かずに、画面を指で消す。"},{w:null,t:"丘のすその古い水路。"},{w:null,t:"水の柱が、はるか向こうの石垣まで届いて、ぴしゃっ。"}];
GR_SC.g02_08=[{w:null,t:"次の日。村の外れの、三千年前の競技場。",v:"02_0157"},{w:null,t:"石の入口のアーチ。"},{w:null,t:"土手の日かげで、案内のロボットと観光客の一団が休んでいる。"},{w:null,t:"エリーは、案内のロボットのとなりで、観光客に水を配る手伝い。"},{w:"hero",t:"エリー、かけっこしようぜ。向こうの端まで。",v:"02_0161"},{w:"elly",f:"serious",t:"……いいよ。よーい……ドン！",v:"02_0162"},{w:null,t:"ヤマト、エリーの前に出る。前だけ見て、にっと笑う。"},{w:null,t:"その横を、フォルンが追いぬく。しっぽの火が、ヤマトの鼻先をかすめる。"},{w:null,t:"ヤマトの前髪から、煙がひとすじ。にやけた顔のまま走っている。"},{w:null,t:"土手の一団から拍手。"}];
GR_SC.g02_09=[{w:null,t:"正午。",v:"02_0169"},{w:null,t:"エリーの手首の画面が、ぴこんと鳴る。"},{w:null,t:"ヤマト、土手の下のフォルンをふり返る。"},{w:"hero",f:"serious",t:"……フォルンはここだ。だいじょぶ。",v:"02_0172"},{w:"elly",f:"surprised",t:"……お姉ちゃん、うそうまいから。だいじょぶ。",v:"02_0173"},{w:null,t:"ヤマト、手首の画面を見る。"},{w:"elly",t:"今度は、開くんじゃない？",v:"02_0175"},{w:null,t:"ヤマト、アイコンを、指でとんと押す。"},{w:null,t:"手首の画面から光が広がって、宙に地図になる。"},{w:null,t:"地図の上に、小さな光の印が、ぽつ、ぽつと浮かぶ。"},{w:"hero",t:"この真下って……下に何かあんの？",v:"02_0181"},{w:"hero",f:"serious",t:"……ちょっと、中を見てくるだけ。",v:"02_0184"}];
GR_SC.g02_10=[{w:null,t:"競技場の、真下。",v:"02_0188"},{w:null,t:"ひんやりした石の通路。フォルンのしっぽの火が明かりになる。"},{w:null,t:"つきあたりに、大きな石の扉。"},{w:null,t:"扉のふちに、細かい文字がびっしり。"},{w:"hero",f:"serious",t:"……でっか。",v:"02_0192"},{w:"elly",f:"serious",t:"……これ、古いギリシャの字だ。",v:"02_0193"},{w:null,t:"エリー、文字を指でなぞって、声に出して読む。"},{w:"elly",f:"surprised",t:"えっとね……ここで寝てる子、起こさないでね、だって。",v:"02_0195"},{w:null,t:"エリーの声が、通路にひびいて、消える。"},{w:null,t:"……足の下の、ずっと深い所から、低い音が一つだけ返ってくる。"},{w:"elly",t:"フォルンが怒ってる。……今日は帰ろ。",v:"02_0203"},{w:"hero",f:"serious",t:"……今日だけだからな。また来る。",v:"02_0204"}];
GR_BT[2]={mid:[[{w:"alek",t:"立ち入り禁止って、入口の看板に書いてあったやろ。",v:"02_0210"},{w:"hero",f:"serious",t:"……読んでない。",v:"02_0211"},{w:"alek",t:"×の絵ぐらい見いや。",v:"02_0212"},{w:"elly",t:"わたし、ぜんぶ読めたよ。奥の扉のも。",v:"02_0213"},{w:null,t:"アレク、口をあけたまま止まる。"},{w:null,t:"アレクの目が、ヤマトの足もとのフォルンに止まる。"},{w:"alek",t:"その狐、置いていき。仕事なんや。",v:"02_0216"}],[{w:"hero",t:"やだね。",v:"02_0217"},{w:null,t:"ヤマト、フォルンの前に立つ。"},{w:"alek",t:"ほな、力ずくで運ぶで。",v:"02_0219"},{w:null,t:"アレク、手首の画面を指で一回たたく。"},{w:"elly",t:"そのドローン、ヴィクター一味のだよ！",v:"02_0221"},{w:null,t:"アレク、ドローンの胴の輪を見上げる。ほんの一瞬、目が止まる。"},{w:null,t:"アレク、目をもどす。"},{w:"hero",t:"お前、あの赤い髪の女の仲間か！",v:"02_0224"},{w:"alek",t:"そこにいたら、ぬれるで。",v:"02_0225"},{w:null,t:"ヤマトとエリー、通路の出口の石の壁ぎわまで下がる。"},{w:"elly",t:"ピリポン！　もどって！",v:"02_0228"},{w:null,t:"エリー、一歩出かけて、止まる。ピリポンから目をはなせない。"}],[{w:"alek",t:"3か。……ちっこいな。",v:"02_0236"},{w:"hero",f:"surprised",t:"ちっこくねえ！",v:"02_0237"},{w:"hero",t:"フォルン、水路に近よるな！",v:"02_0239"},{w:"hero",t:"右のはしからだ！",v:"02_0240"},{w:null,t:"アレク、画面を指ではじく。"},{w:"hero",t:"なんで、あんな遠くまで……！",v:"02_0245"},{w:"hero",t:"近くだ！　近くで吹け！",v:"02_0248"},{w:null,t:"ヤマト、何か言いかけて、口を閉じる。"},{w:null,t:"アレク、画面に指をのせる。"}],[{w:"elly",t:"ピリポン！",v:"02_0257"},{w:null,t:"エリーが飛び出しかける。"},{w:"hero",t:"出るな！　水が来る！",v:"02_0260"},{w:null,t:"アレク、画面から指をはなす。"},{w:"alek",t:"……撃つな。",v:"02_0262"},{w:null,t:"ヤマト、エリーの腕をつかんだまま、フォルンを見る。"},{w:"hero",t:"フォルン、たのむ！　ピリポンを！",v:"02_0264"},{w:null,t:"アレク、それを見ている。"},{w:"alek",t:"……終わらせるで。",v:"02_0272"},{w:null,t:"アレク、画面をはじく。"},{w:"hero",t:"フォルン！",v:"02_0276"}]],post:[{w:null,t:"ヤマト、走る。"},{w:null,t:"アレクの手首の画面が、ぶるっとふるえる。"},{w:"alek",t:"はい。狐は、網の中です。",v:"02_0280"},{w:"alek",t:"それと、女の子が、地下の古い字を読みました。",v:"02_0281"},{w:null,t:"返事が来ない。"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……狐は、まだ運ぶな。",v:"02_0284"},{w:"x",n:"画面の声（アレクの耳の中）",t:"今夜、その娘と一緒にだ。",v:"02_0285"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……放しておけ。",v:"02_0286"},{w:null,t:"アレクの、画面にのせていた指が止まる。"},{w:null,t:"通話が切れる。"},{w:null,t:"アレク、画面を一回たたく。"},{w:"elly",f:"serious",t:"……今の、わたしのこと？",v:"02_0290"},{w:"alek",t:"気のせいや。",v:"02_0291"},{w:"hero",f:"serious",t:"……なんで、やめんだよ。",v:"02_0292"},{w:"alek",t:"今日は、ここまでや。",v:"02_0293"},{w:null,t:"アレク、ヤマトの顔を見て、あごで水路をさす。"},{w:"alek",t:"水路があったら、負けへんねん。",v:"02_0295"},{w:null,t:"アレク、水路のふちを軽くたたく。"},{w:null,t:"エリー、ピリポンを抱いて走ってくる。"},{w:null,t:"フォルンの目が、ぐるぐるから、ゆっくりもどる。"},{w:null,t:"エリーの腕の中で、ピリポンが首をのばす。"},{w:"elly",f:"serious",t:"……ありがとう、フォルン。",v:"02_0300"},{w:null,t:"ヤマト、林の方へ遠ざかるワニの子のあごを、だまって見ている。"},{w:"hero",t:"次は勝つ。",v:"02_0302"},{w:"elly",t:"次って……。またあの人とやる気？",v:"02_0303"},{w:"hero",t:"あいつだけじゃねえ。もっと強えやつとも、全部だ。",v:"02_0304"},{w:"elly",f:"serious",t:"……おととい言ってた、世界一ってやつ？",v:"02_0305"},{w:null,t:"ヤマト、ひざの泥もはらわずに、胸を張る。"},{w:"hero",t:"ああ。白い都で、まず一番だ！",v:"02_0307"},{w:"elly",f:"serious",t:"……ひざ、泥だらけで言われても。",v:"02_0308"},{w:null,t:"ヤマト、ひざの泥を、ばんばんとはらう。"},{w:null,t:"はらった泥が、少しはなれたフォルンの鼻先まで飛ぶ。"},{w:null,t:"火の粉が一つ、ヤマトのひざに、ぽっ。ヤマト、だまって、またはらう。"},{w:null,t:"ヤマト、背中のリュックの横ポケットから、くしゃくしゃのちらしを引きぬく。"}]};
GR_EP[2]={"t": "競技場の地下", "sc": [["g02_01", "先に一瞬（5秒）", 0], ["g02_02", "ホテルの裏・ぶどう畑のはし（朝）", 0], ["g02_03", "ホテルの食堂（朝）", 0], ["g02_04", "ロビー（朝）", 0], ["g02_05", "丘の上・ため池と研究所あと（昼）", 0], ["g02_06", "おばあさんの家（昼）", 0], ["g02_07", "どこかの丘（夜）", 0], ["g02_08", "古代の競技場（次の日・昼前）", 0], ["g02_09", "土手の上（正午）", 0], ["g02_10", "地下の扉", 0], ["g02_11", "通路の出口・土手のすその空き地", 1]]};
GR_SC.g03_01=[{w:null,t:"同じ日の夕方。村の裏の森。",v:"03_0039"},{w:null,t:"小川べりの平たい岩に、背の高い若い男が一人、ひざを立てて座っている。"},{w:null,t:"小川の中を、頭に卵のからをかぶった緑のワニの子が、ぐるぐる回って泳いでいる。"},{w:null,t:"ワニの子が、岸の白っぽい乾いた石の上へ上がる。"},{w:null,t:"男、かばんから、やわらかく煮た魚の包みを出す。"},{w:null,t:"手首の画面が、ぶるっとふるえる。"},{w:"x",n:"受付の女の声",t:"お待ちください。おつなぎします。",v:"03_0045"},{w:"x",n:"画面の声",t:"アレク。日が落ちたら、狐と娘を連れてこい。",v:"03_0047"},{w:"x",n:"画面の声",t:"狐がなついている男の子も、一緒にな。",v:"03_0048"},{w:"alek",t:"……男の子も、ですか。",v:"03_0049"},{w:"alek",t:"受けたのは、狐一匹の運びだけっす。",v:"03_0050"},{w:"alek",t:"子どもまで、なんでです？",v:"03_0051"},{w:"x",n:"画面の声",t:"理由は、お前の仕事じゃない。",v:"03_0052"},{w:"alek",t:"子ども運んだら、運びの仕事やなくなります。",v:"03_0053"},{w:"x",n:"画面の声",t:"……アレク。",v:"03_0054"},{w:"x",n:"画面の声",t:"そのワニ、こちらで、いつでも止められる。",v:"03_0055"},{w:"x",n:"画面の声",t:"……運べ。",v:"03_0057"},{w:null,t:"通話が切れる。"},{w:null,t:"ワニの子が、男のひざに、ぬれた頭をのせる。"},{w:null,t:"男、ワニの子の頭に手を置く。"},{w:null,t:"第3話　夜の森",v:"03_0063"}];
GR_SC.g03_02=[{w:null,t:"その夜。",v:"03_0069"},{w:null,t:"ホテルの裏口の戸が、そっと開く。"},{w:null,t:"エリー、黒のチェックのフリルのブラウスに、うすい色の細身のデニム。"},{w:null,t:"髪は高いポニーテール。"},{w:"hero",t:"……エリー、その手に持ってる、でっかいの、なに？",v:"03_0073"},{w:"elly",t:"虫よけ。",v:"03_0074"},{w:null,t:"エリー、スプレーを自分の腕に、ぷしゅっ。"},{w:null,t:"エリー、戸のすきまに、うすい電子メモをはさむ。"},{w:"hero",t:"アナさんに言わなくていいのか？",v:"03_0077"},{w:"elly",t:"言ったら、ぜったい止められるもん。",v:"03_0078"},{w:"elly",t:"お姉ちゃんには、あした電話する。",v:"03_0079"},{w:null,t:"塀の上から、フォルンが、とん、と下りてくる。"}];
GR_SC.g03_03=[{w:null,t:"ぶどう畑を抜けた先の、暗い森。"},{w:null,t:"かえるの声。"},{w:"elly",t:"わあ……きれい。",v:"03_0085"},{w:null,t:"ヤマトは、光る板を見たまま。"},{w:null,t:"光る板のまわりに、羽虫がわっと集まる。"},{w:"hero",t:"うわ、来んな！",v:"03_0088"},{w:null,t:"エリー、スプレーをかまえて、明かりのまわりに、ぷしゅー。"},{w:null,t:"フォルンだけは、森の奥をじっと見ている。耳が前を向いている。"},{w:null,t:"小川べりの平たい岩。"},{w:null,t:"ヤマト、顔を上げて、止まる。"},{w:"hero",f:"serious",t:"……また、お前かよ。",v:"03_0093"},{w:"hero",t:"いつから、ここにいたんだよ。",v:"03_0094"},{w:"alek",t:"夕方から、ずっとここで待っててん。",v:"03_0095"},{w:"alek",t:"村から出る道、ここしかないやろ。",v:"03_0096"},{w:null,t:"男、望遠鏡から目をはなさない。"},{w:null,t:"低い空に、赤い星が一つ。"},{w:"hero",f:"serious",t:"……望遠鏡で、何見てんだよ。",v:"03_0099"},{w:"alek",t:"星や。今夜はよう晴れてるしな。",v:"03_0100"},{w:"hero",t:"星って、どの星だよ。いっぱいあるだろ。",v:"03_0101"},{w:"alek",t:"赤いやつや。……それ以上は、有料やで。",v:"03_0102"},{w:"hero",t:"なんだよ、それ。教えてくれたっていいだろ！",v:"03_0103"},{w:null,t:"男、望遠鏡の筒をていねいにちぢめて、かばんにもどす。"}];
GR_SC.g03_04=[{w:"alek",t:"その狐、こっちに渡しや。",v:"03_0107"},{w:"hero",t:"昼みたいには、いかねえぞ。",v:"03_0108"},{w:"hero",t:"だいたい、網まで出して、なんで帰ったんだよ。",v:"03_0109"},{w:"alek",t:"まだ運ぶなって言われたんや。",v:"03_0110"},{w:"alek",t:"今夜、お前らも一緒に連れてこいってな。二人ともや。",v:"03_0111"},{w:"hero",f:"serious",t:"……は？　おれらも？",v:"03_0112"},{w:"elly",f:"serious",t:"……やっぱり、昼の電話、わたしのことだ。",v:"03_0113"},{w:"alek",t:"（目をそらして）……気のせいやなかったわ。",v:"03_0114"},{w:"hero",t:"なんで、おれらまで行かなきゃいけないんだよ。",v:"03_0115"},{w:"alek",t:"理由なんか、おれも知らん。",v:"03_0116"},{w:"alek",t:"仕事の相手に、そう言われただけや。",v:"03_0117"},{w:"hero",t:"やっぱ一味じゃん。フォルン売る気だろ。",v:"03_0118"},{w:null,t:"ヤマト、フォルンの前に半歩出る。"},{w:"alek",t:"うっさいな。こっちにも、断れへんわけがあるんや。",v:"03_0120"},{w:"elly",t:"その子も、そのお仕事してるの？",v:"03_0121"},{w:"alek",t:"こいつは関係ないやろ。仕事の話に、こいつを入れんな。",v:"03_0122"},{w:"hero",t:"その子連れて仕事してんだろ。関係あるじゃん。",v:"03_0123"},{w:"alek",t:"もう話はええやろ。",v:"03_0124"},{w:"alek",t:"起きてる狐に網を出したって、どうせ逃げるんやろ？",v:"03_0125"},{w:"alek",t:"だから、勝負で決めようや。",v:"03_0126"},{w:"alek",t:"おれが勝ったら、狐とお前らを連れていくで。",v:"03_0127"},{w:"hero",f:"smile",t:"じゃあ、おれが勝ったら、どうすんだよ。",v:"03_0128"},{w:"alek",t:"おれは黙って帰るわ。",v:"03_0129"},{w:"alek",t:"仕事の相手には「森にはだれも来なかった」って言うとくわ。",v:"03_0130"},{w:null,t:"男の目が、一瞬だけ、ヤマトの顔に止まる。それから、はなれる。"},{w:"elly",t:"ヤマト、待って。その子、なんか変だよ。",v:"03_0132"},{w:"elly",t:"耳のうしろ、何か光ってる。",v:"03_0133"},{w:"hero",t:"光ってる？　……昼の分、返すだけだ。",v:"03_0134"},{w:null,t:"エリー、しゃがんで、ワニの子の頭の卵のからを見る。"},{w:"elly",t:"（ワニの子に）こんばんは。きみ、お名前は？",v:"03_0136"},{w:"alek",t:"名前は、おれに勝てたら教えたるわ。",v:"03_0137"}];
GR_SC.g03_05=[{w:null,t:"ヤマト、光る板を手前の切り株の上に置く。"},{w:null,t:"右を、小川が奥から手前へまっすぐ流れている。"},{w:null,t:"男、ワニの子を小川に放す。"},{w:null,t:"エリーは、小川を見ている。"},{w:null,t:"火花が、石を伝って、小川の水の上で、ぱちっと光る。"},{w:null,t:"ピリポン、びっくりして、エリーの髪にもぐる。"},{w:"elly",t:"ピリポン。こわかったら、そこの石のかげにいて。",v:"03_0148"},{w:"elly",t:"それだけでいいから。",v:"03_0149"},{w:"alek",t:"二体で来いや。",v:"03_0153"},{w:"elly",t:"ピリポンは、かくれてるだけだよ。",v:"03_0154"},{w:"alek",t:"ほな、それでええ。",v:"03_0155"},{w:"alek",t:"……始めよか。",v:"03_0157"}];
GR_SC.g03_07=[{w:null,t:"ヤマト、両手のこぶしを空へ突き上げる。"},{w:null,t:"ピリポン、固まっている。"},{w:"elly",t:"ピリポン、すごいよ……！",v:"03_0237"},{w:null,t:"アレク、ひっくり返ったワニの子のそばにひざをつく。曲がったあごに、手をそえる。"},{w:null,t:"耳のうしろのうろこのすき間から、割れたチップの半分が、ころっと落ちる。"},{w:"elly",t:"その黒いの、なに？",v:"03_0240"},{w:"alek",t:"仕事の相手が入れさせたもんや。",v:"03_0241"},{w:null,t:"アレク、かけらを指でつまんで、月あかりにかざす。"},{w:"alek",t:"……割れてもうたな。",v:"03_0243"},{w:"hero",t:"さっきの雷か？",v:"03_0244"},{w:"alek",t:"やろな。",v:"03_0245"},{w:null,t:"乾いた草の上で、ワニの子の背中のうろこが、白っぽくかわいていく。"},{w:null,t:"アレク、うろこから目を上げて、ヤマトを見る。"},{w:"alek",t:"乾くと、こいつ弱なるねん。",v:"03_0248"},{w:null,t:"ヤマト、小川へ走る。"},{w:"alek",t:"お前、何してんねん。",v:"03_0250"},{w:"hero",t:"かわいてんじゃん、こいつ。",v:"03_0251"},{w:null,t:"アレク、それを見ている。割れたチップをにぎった手が、ひざの上で止まっている。"},{w:null,t:"エリーも、ピリポンを肩にのせて、両手で水をすくいに走る。"},{w:null,t:"三回目の水がかかった時、ワニの子が目を開ける。"},{w:null,t:"アレク、割れたチップをにぎった手を、しばらく開かない。"},{w:"hero",f:"smile",t:"……勝ったぞ。約束だからな。",v:"03_0256"},{w:"alek",t:"おう。今夜は、狐は運ばへん。",v:"03_0257"},{w:"hero",t:"今夜は、って何だよ。",v:"03_0258"},{w:"alek",t:"仕事をやめたわけやない。",v:"03_0259"},{w:"elly",t:"その子にチップを入れた人の仕事、まだやるの？",v:"03_0260"},{w:"alek",t:"金がいるんや。",v:"03_0261"},{w:"hero",t:"金って……。",v:"03_0262"},{w:null,t:"アレク、答えない。"},{w:null,t:"アレク、ぐったりしたワニの子を抱き上げる。"},{w:"elly",t:"その子、休ませなきゃ。お水も、いっぱいいるよ。",v:"03_0265"},{w:"elly",f:"serious",t:"……うち、すぐそこだから。",v:"03_0266"},{w:"hero",f:"serious",t:"……しょうがねえな。今夜は、もどる。",v:"03_0267"},{w:"alek",t:"水おけ、あるか。こいつ、ひと晩つけときたいんや。",v:"03_0268"},{w:"elly",t:"あるよ！　ぶどう畑のはしの小屋に。",v:"03_0269"},{w:null,t:"エリーが歩きだすと、アレクもそのあとについてくる。"}];
GR_SC.g03_08=[{w:null,t:"夜ふけ。坂の上のホテル。",v:"03_0273"},{w:null,t:"玄関の明かりだけが、ついている。"},{w:null,t:"門の内側に、アナが、腕を組んで立っている。"},{w:"ana",t:"……こんな夜中に、二人とも、どこに行ってたの？",v:"03_0276"},{w:"elly",f:"surprised",t:"……えっと、……森。",v:"03_0277"},{w:"ana",t:"ちょっと出かけただけで、そんなに泥だらけになるの？",v:"03_0278"},{w:"ana",t:"電話、十二回もしたんだけど。",v:"03_0279"},{w:"elly",f:"sad",t:"（小さくなって）……ごめんなさい。音、切ってた。",v:"03_0280"},{w:"ana",t:"……で、あの人は、だれなの？",v:"03_0281"},{w:null,t:"門の外の、石の塀のそば。"},{w:"elly",f:"surprised",t:"えっと……森で会った人！",v:"03_0283"},{w:"ana",t:"……あとで、ちゃんと聞くからね。",v:"03_0284"},{w:null,t:"アナ、エリーの泥の服を見て、ため息。"},{w:null,t:"アレクの目が、リュックの横ポケットからはみ出したちらしの角に行く。"},{w:"alek",t:"白い都まで行くつもりなんか？",v:"03_0287"},{w:"hero",t:"行くよ。",v:"03_0288"},{w:"alek",t:"道なら、おれが知ってる。ヴィクターの車が通らへん道もな。",v:"03_0289"},{w:"alek",t:"……案内したろか？",v:"03_0290"},{w:"hero",t:"お前、狐を運ぶのが仕事なんだろ。",v:"03_0291"},{w:"alek",t:"届け先も、白い都や。",v:"03_0292"},{w:"alek",t:"お前らが自分で連れてってくれたら、手間がはぶけるやん。",v:"03_0293"},{w:"hero",f:"hurt",t:"着いたって、渡さねーぞ。",v:"03_0294"},{w:"hero",t:"こいつは、おれと大会に出るんだからな。",v:"03_0295"},{w:"alek",t:"できたらな。",v:"03_0296"},{w:null,t:"エリー、塀の下にしゃがむ。"},{w:"elly",f:"smile",t:"（ワニの子に）約束だよ。わたしたち、勝ったんだから、名前、教えて。",v:"03_0299"},{w:"alek",t:"こいつの名前は、クロッコや。",v:"03_0300"},{w:null,t:"【プロフィール】クロッコ／水／●○○／かむ力のない、のんきなワニ"},{w:"elly",t:"じゃあ、クロッコちゃんだね。",v:"03_0303"},{w:"alek",t:"「ちゃん」は、つけんでええって。",v:"03_0304"},{w:"hero",t:"……道、知らねえしな。案内、たのむ。おれ、ヤマト。",v:"03_0305"},{w:"alek",t:"おれは、アレクや。",v:"03_0306"},{w:null,t:"アナが、タオルを二枚持ってもどってくる。"},{w:"elly",t:"お姉ちゃん、この人、今夜泊めてあげて！",v:"03_0308"},{w:null,t:"エリー、クロッコの背中の、白く乾いたうろこを指さす。"},{w:null,t:"アナ、タオルを持ったまま、アレクを上から下まで見る。"},{w:null,t:"アレク、クロッコを抱いたまま、すっと背すじをのばす。"},{w:"alek",t:"（一段低い声で）……実は僕、北の国の王子でして。",v:"03_0312"},{w:"alek",t:"（一段低い声で）……お姉さん、僕とお茶しません？",v:"03_0313"},{w:null,t:"エリーの肩で寝ていたピリポンが、ビリリ。"},{w:"ana",t:"……で、一泊いくら払えるの？",v:"03_0315"},{w:null,t:"アレク、自分の手首の画面を見る。親指が、払いの欄の上で止まる。"},{w:null,t:"アナの目が、その手のひらに行く。"},{w:"alek",t:"（一段低い声で）……外でいいっす。屋根の分、浮くんで。",v:"03_0318"},{w:null,t:"腕の中のクロッコが、うす目をあける。"},{w:null,t:"アレク、あごから水をたらしたまま、低い声の顔をくずさない。"},{w:"ana",t:"その子、ひと晩じゅう水がいるでしょ。裏の小屋にしなさい。",v:"03_0321"},{w:null,t:"アナ、もうエリーの泥だらけの服を見ている。"}];
GR_SC.g03_09=[{w:null,t:"ヤマトの部屋。"},{w:null,t:"窓のふちに、フォルン。"},{w:null,t:"フォルン、音を立てずに床へ下りる。"},{w:null,t:"リュックの上に乗る。"},{w:null,t:"ヤマト、うす目をあける。"},{w:null,t:"ヤマト、ベッドから、そうっと手をのばす。"},{w:null,t:"ぺしっ。しっぽが、ヤマトの手の甲をはたく。"},{w:"hero",t:"（小声で）……ちぇっ。",v:"03_0332"},{w:null,t:"ヤマト、手を引っこめる。"}];
GR_SC.g03_10=[{w:null,t:"ぶどう畑のはしの道具小屋。"},{w:null,t:"アレクの手首の画面が、ぶるっとふるえる。"},{w:"x",n:"画面の声（アレクの耳の中）",t:"アレク。狐と子どもは、どうした。",v:"03_0338"},{w:null,t:"アレク、ホテルの一階の、はしの窓を見る。"},{w:"alek",t:"森には、だれも来ませんでした。",v:"03_0340"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……夕方から、ずっとか。",v:"03_0341"},{w:"alek",t:"はい。",v:"03_0342"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……ワニのチップの反応が、消えたぞ。",v:"03_0343"},{w:"alek",t:"川で暴れて、取れてもうたみたいです。",v:"03_0344"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……狐は、必ず運べ。",v:"03_0345"},{w:"alek",t:"はい。白い都まで、運びます。",v:"03_0346"},{w:null,t:"通話が切れる。"},{w:null,t:"アレク、ポケットから、割れたチップを出す。"},{w:null,t:"水おけの中で、クロッコが寝がえりをうつ。アレクの手が、その頭の上で止まる。"}];
GR_BT[3]={mid:[[{w:"alek",t:"行け。水や。",v:"03_0163"},{w:"hero",t:"フォルン、やり返せ！",v:"03_0168"},{w:"alek",t:"もぐれ。もう一回、水や。",v:"03_0170"},{w:"hero",t:"出んな！　そこにいろ！",v:"03_0172"},{w:null,t:"ヤマト、その耳を見る。"}],[{w:"alek",t:"手前に回れ。",v:"03_0175"},{w:"elly",t:"ピリポン！",v:"03_0178"},{w:null,t:"ヤマト、森を見わたす。"},{w:null,t:"ヤマトの目が、フォルンの小さくなった火から、しぶきを吸ってふくらんだ根もとの苔へ。"},{w:"hero",f:"serious",t:"……じゃんけんじゃん、これ。",v:"03_0187"},{w:null,t:"ヤマトの目が、石のかげのピリポンに行く。"},{w:null,t:"ヤマト、指を一本立てたまま、小川の水とピリポンを、交互に指さす。"},{w:"hero",f:"serious",t:"……エリー！",v:"03_0190"},{w:"elly",t:"ピリポン、あそこ！",v:"03_0191"},{w:null,t:"アレクの目が、はじめてヤマトからはなれる。"}],[{w:"alek",t:"下がれ！　そいつの電気から離れや。",v:"03_0198"},{w:null,t:"ヤマトの目が、小川から、左の、白っぽい石の地面へ行く。"},{w:null,t:"ヤマトの指が、川の中のワニの子と、石の地面の奥を、一本の線で結ぶ。"},{w:"hero",t:"フォルン！　もう、木の下にいなくていい！",v:"03_0203"},{w:"hero",t:"（石の地面の奥を指さして）あそこまで下がれ！",v:"03_0205"},{w:null,t:"エリー、石の地面のフォルンを見る。それから、石のかげで震えているピリポンを見る。"},{w:"elly",t:"ピリポン、もう少しだけ前に出られる？",v:"03_0209"},{w:"elly",t:"わたし、ここでずっと見てるから。",v:"03_0210"},{w:null,t:"アレク、石の地面の奥のフォルンを見る。しっぽの火が、まだ小さい。"}],[{w:"alek",t:"川から上がれ！　狐くわえて、引きずってこい！",v:"03_0214"},{w:null,t:"アレクの顔が、わずかに動く。"},{w:"alek",t:"もどれ！　川までもどるんや！",v:"03_0221"},{w:"elly",f:"serious",t:"……ピリポン、いける？",v:"03_0223"},{w:"elly",t:"ピリポン、ぱちって！",v:"03_0227"},{w:"hero",t:"フォルン、今だ！　そこからぶっ放せ！",v:"03_0229"}]],post:[{w:null,t:"ワニの子が、炎に押されて吹き飛び、小道の草の上を転がって、ひっくり返る。目を回して、起き上がらない。"},{w:null,t:"ひっくり返ったワニの子の耳のうしろのうろこを、雷の残りが、ちりちりっと走る。"}]};
GR_EP[3]={"t": "夜の森", "sc": [["g03_01", "森の小川（夕方）", 0], ["g03_02", "ホテルの裏口（夜）", 0], ["g03_03", "森の道（夜）", 0], ["g03_04", "口げんか", 0], ["g03_05", "向かい合う", 0], ["g03_06", "勝負（2Dアニメ）", 1], ["g03_07", "勝負のあと", 0], ["g03_08", "ホテルの門（夜ふけ）", 0], ["g03_09", "ホテルの一階のはしの部屋（夜ふけ）", 0], ["g03_10", "ホテルの裏・道具小屋（夜ふけ）", 0]]};
GR_SC.g04_01=[{w:null,t:"坂のとちゅうに、黒塗りのロボタクシーが止まっている。"},{w:null,t:"うしろの席。"},{w:null,t:"画面の字。「アレク　報告：森にはだれも来なかった」「オリーヴァ村　狐　まだ」。"},{w:"nina",t:"マルコ、起きなさい。仕事よ。",v:"04_0042"},{w:"marco",t:"……それ、アレクの仕事だろ。",v:"04_0043"},{w:"marco",t:"おれたち、もう外されたじゃねえか。",v:"04_0044"},{w:null,t:"ニーナ、画面の字を、マルコの顔の前へ向ける。"},{w:"nina",t:"だから、こっちに回ってきたのよ。",v:"04_0046"},{w:null,t:"マルコ、帽子を少しだけ上げる。"},{w:"marco",t:"……めんどくさいなあ。朝めし、まだなのに。",v:"04_0048"},{w:null,t:"マルコの足もとで、黒い体にオレンジの点の散った、小さなヤモリの子が、目をあける。"},{w:null,t:"第4話　夜明けの火",v:"04_0052"}];
GR_SC.g04_02=[{w:null,t:"坂の上のホテル。四日目の朝。",v:"04_0058"},{w:null,t:"ぶどう畑のはしの道具小屋から、アレクが、うすい掛け物をたたみながら出てくる。"},{w:null,t:"二階の窓から、アナが顔を出す。"},{w:"ana",t:"おはよう。じゃあ、ひと晩分の宿代ね。20ジェムコイン。",v:"04_0061"},{w:null,t:"アレク、手首の画面を見る。払いの欄の上で、親指が止まる。"},{w:"alek",t:"……画面で払うのは、ちょっと。",v:"04_0063"},{w:"ana",t:"わけありね。……じゃあ、裏の用水路の泥かき。",v:"04_0064"},{w:"ana",t:"それでいいから。",v:"04_0065"},{w:"alek",t:"……ほな、それで。",v:"04_0066"},{w:null,t:"小屋の横の石の水おけ。クロッコが体をしずめて、目をつむっている。"},{w:null,t:"小屋の前の用水路を、フォルンがひょいとまたぐ。"},{w:null,t:"フォルン、しっぽをぶるっとふって、知らん顔。"}];
GR_SC.g04_03=[{w:null,t:"朝ごはんのテラス。"},{w:null,t:"床を、丸い掃除ロボットがすべって回る。"},{w:null,t:"テラスの手すりの向こう、裏の畑。"},{w:"hero",t:"でさ、相手、川からばしゃーって撃ってくんの。",v:"04_0077"},{w:"x",n:"客の子A",t:"えっ、負けちゃうの？",v:"04_0078"},{w:"hero",t:"ふつうはな。でも、そこでおれが気づいたわけ。",v:"04_0079"},{w:"x",n:"客の子B",t:"何に気づいたの？",v:"04_0080"},{w:"hero",t:"（パンをほおばって）……とにかく、気づいたんだよ。",v:"04_0081"},{w:"x",n:"客の子A",t:"ふーん。",v:"04_0082"},{w:"elly",t:"（パンをちぎりながら）気づいたの、負けそうになってからだったよね。",v:"04_0083"},{w:"hero",t:"負けそうになってからでも、気づいたもんは気づいたんだ。",v:"04_0084"},{w:null,t:"テーブルのはしで、フォルンがしっぽの火の上でオリーブを転がしている。"},{w:null,t:"ヤマト、いちばん大きい焼きオリーブを、ひょいとつまむ。"},{w:"hero",t:"これは、作戦を考えたおれの分な。",v:"04_0087"},{w:null,t:"フォルンのしっぽの火が、ぼっとふくらむ。"},{w:"hero",t:"あっ、ち、ち、ち——",v:"04_0089"},{w:null,t:"オリーブが手のひらの上でおどる。"},{w:null,t:"フォルン、宙のオリーブを口で受けとめる。"},{w:null,t:"子どもたちが、どっと笑う。"},{w:null,t:"ヤマト、指をふうふう吹く。"},{w:"hero",t:"……と、とにかく。次にだれが来ても、おれとフォルンなら——",v:"04_0094"},{w:null,t:"テラスの入口に、アナが立っている。"},{w:"ana",t:"ヤマト。門のところに、あんたにお客さんが来てる。",v:"04_0096"}];
GR_SC.g04_04=[{w:null,t:"門の外に、マルコ。"},{w:"marco",t:"よう。この前の礼をしに来てやったぜ。",v:"04_0100"},{w:"hero",t:"あっ、この前の……マカロニ！",v:"04_0101"},{w:"marco",t:"誰がマカロニだ！　マルコだ！",v:"04_0102"},{w:"marco",t:"……あの狐、ここにいるんだろ？",v:"04_0103"},{w:null,t:"ヤマトの足もとで、フォルンの耳が立つ。"},{w:null,t:"マルコの目が、フォルンから、そのうしろへ行く。"},{w:"marco",t:"……アレク？　なにしてんだよ、そんなとこで。",v:"04_0106"},{w:"alek",t:"泥かきや。",v:"04_0107"},{w:"marco",t:"その狐、お前の係だろ。なんで、つかまえねえんだよ。",v:"04_0108"},{w:"alek",t:"おれのやり方があんねん。",v:"04_0109"},{w:"marco",t:"ふーん。……まあ、いいや。",v:"04_0110"},{w:null,t:"坂の下で、ニーナの画面が、かしゃっと鳴る。"},{w:"marco",t:"一対一で、どうだい。そっちが勝ったら、おれは手を引く。",v:"04_0112"},{w:"marco",t:"おれが勝ったら、狐はもらっていくぜ。",v:"04_0113"},{w:null,t:"アレク、泥だらけのまま、畑から門へ走ってくる。"},{w:"alek",t:"待て待て待て。ヤマト、勝手に返事すんなや。",v:"04_0115"},{w:"hero",t:"まだ何も言ってないって。",v:"04_0116"},{w:"hero",t:"（マルコに）受けなかったら、どうなんだよ。",v:"04_0117"},{w:"marco",t:"ニーナがドローンを呼んで、網だな。",v:"04_0118"},{w:null,t:"ヤマト、テラスの方をふり返る。"},{w:null,t:"ヤマト、アレクの顔を見る。"},{w:null,t:"アレク、テラスの子どもたちを見る。それから、水おけのクロッコ。"},{w:"alek",t:"……受けるしかないやん。",v:"04_0122"},{w:"hero",t:"分かってる。フォルン、行くぞ。",v:"04_0123"},{w:null,t:"マルコの肩のヤモリが、口をあける。"},{w:null,t:"エリーの肩のピリポンが、エリーの髪の中に、頭からもぐりこむ。"},{w:"marco",t:"こいつ、まだ上があるんだぜ。",v:"04_0126"},{w:"hero",t:"上？　関係ねえよ。燃やしたもん勝ちだろ。",v:"04_0127"},{w:null,t:"ヤマトは、もう門の外に出ている。"},{w:"marco",t:"場所は、どこでもいいけど。……裏の畑にしようか。",v:"04_0129"},{w:"marco",t:"林のそばなら、日かげがあるからな。",v:"04_0130"}];
GR_SC.g04_05=[{w:null,t:"ぶどう棚の前で、マルコが畑を見わたす。"},{w:null,t:"手前は、乾いた草の畑。"},{w:null,t:"マルコ、林のわきの石垣のかげに木箱を置いて、座る。"},{w:null,t:"【プロフィール】スミヤモ／炎／●○○／火の玉を落とすヤモリ"},{w:null,t:"ヤマト、フォルンを手前の畑のまん中に立たせる。"},{w:null,t:"アレクとエリーが、ぶどう棚の下に立つ。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"6や。……お前のより、上やで。",v:"04_0146"},{w:"hero",t:"上等じゃん。",v:"04_0147"},{w:"marco",t:"じゃ、始めようか。こっちは、いつでもいいぜ。",v:"04_0148"}];
GR_SC.g04_09=[{w:"hero",f:"smile",t:"……やった。やったぞ、フォルコン！",v:"04_0273"},{w:null,t:"フォルンの体から、光がすうっと引いていく。"},{w:null,t:"ヤマト、ひざをついたまま、目をぱちぱちさせる。"},{w:"hero",f:"serious",t:"……あ、戻った。",v:"04_0276"},{w:null,t:"ヤマト、ひざの高さのフォルンを、上から下まで二回見る。"},{w:"alek",t:"そういうもんや。",v:"04_0278"},{w:"elly",t:"フォルン、やけど見せて！",v:"04_0279"},{w:null,t:"エリー、かけよってしゃがむ。"},{w:null,t:"マルコ、オキヤモを両腕でかかえ上げて、重そうに肩にかつぎ直す。"},{w:"marco",t:"……約束は約束だ。今日は帰るぜ。",v:"04_0282"},{w:"nina",t:"送ったわよ、ボスに。今の写真。",v:"04_0283"},{w:"marco",t:"……おれは、もういいや。",v:"04_0284"},{w:null,t:"マルコ、帰りかけて、アレクの前で止まる。"},{w:"marco",t:"アレク。お前、ほんとに運ぶ気あんのか。",v:"04_0286"},{w:"alek",t:"仕事はするで。",v:"04_0287"},{w:"marco",t:"ならいいけどさ。うちのボス、しつこいからな。",v:"04_0288"},{w:null,t:"マルコ、坂を下りていく。肩の上で、オキヤモのしっぽがぶらぶらゆれる。"},{w:null,t:"アレク、用水路の湯気を見たまま、ヤマトの横に立つ。"},{w:"alek",t:"水ん中の火ぃは、ちぎれてまうんや。",v:"04_0291"},{w:"elly",t:"（フォルンの前足をなでながら）今日は、自分で気づいたね。",v:"04_0292"},{w:null,t:"ヤマト、目をそらして、焦げた前髪を指でつまむ。"},{w:null,t:"ヤマト、フォルンの前にしゃがむ。さっきまで見上げていた顔が、ひざの高さにある。"},{w:null,t:"フォルン、首をくるっと回して、ヤマトの右手の指なし手袋を、ぱくっとくわえて引きぬく。"},{w:"hero",t:"おい、それ、おれの手袋だって。",v:"04_0296"},{w:null,t:"フォルン、手袋をぶらぶらさせながら、畑の外へすたすた出ていく。"},{w:"hero",f:"serious",t:"……おい。返せって。",v:"04_0298"},{w:null,t:"エリーの髪の中から、ピリポンが目だけ出して、フォルンを見ている。"},{w:null,t:"アレク、追いかけかけたヤマトの襟首の泥を、だまって手の甲ではらう。"}];
GR_SC.g04_10=[{w:null,t:"ロビーの画面に、広告。"},{w:null,t:"ヤマト、その前に立っている。"},{w:null,t:"アレクがうしろに来る。"},{w:"alek",t:"今のうちに、村出よか。",v:"04_0306"},{w:null,t:"パンの袋をつめていたエリーの手が、一瞬だけ止まる。"},{w:"elly",f:"serious",t:"……お姉ちゃんに、言ってから。",v:"04_0308"},{w:"alek",t:"ほな、はよ言うてき。二分な。",v:"04_0309"},{w:null,t:"エリー、パンの袋をカウンターに置いて、ロビーの奥へ走っていく。"},{w:"hero",t:"白い都まで、どれくらいかかんの？",v:"04_0311"},{w:"alek",t:"歩きなら、二週間くらいや。",v:"04_0312"},{w:"hero",f:"serious",t:"……歩き？　ロボタクシーは？",v:"04_0313"},{w:null,t:"門の前を、ロボタクシーがすうっと通る。ヤマト、手を上げかける。"},{w:"alek",t:"乗ったら、行き先が全部残るやろ。",v:"04_0315"},{w:"hero",t:"残ったら困んの、お前だろ。マカロニの仲間だし。",v:"04_0316"},{w:"alek",t:"仲間ちゃう。白い都までは、仕事や。",v:"04_0317"},{w:"alek",t:"あと、大会の賞金。勝ったら、案内料で半分もらうで。",v:"04_0318"},{w:"hero",f:"serious",t:"……それは、勝ってから決めようぜ。",v:"04_0319"},{w:null,t:"アレク、水おけからクロッコを出して、背中にかつぐ。クロッコ、目はあけない。"},{w:null,t:"ロビーの奥から、エリーがアナの手を引いてもどってくる。"},{w:"ana",t:"おばあちゃんに聞いたら、行かせなさいって。",v:"04_0322"},{w:"ana",t:"……どうせ、止めても行くんでしょ。",v:"04_0323"},{w:null,t:"エリー、目をそらして、笑う。"},{w:"ana",t:"そのかわり毎晩、自分の画面で電話してきなさい。",v:"04_0325"},{w:null,t:"アナ、エリーのうしろのアレクを、一度だけ見る。"},{w:"ana",t:"電話が一晩抜けたら、むかえに行くからね。",v:"04_0327"},{w:"elly",f:"serious",t:"……うん。毎晩、かける。",v:"04_0328"},{w:null,t:"アナ、上着のポケットから、手のひらほどのうすい板を出す。"},{w:"ana",t:"それと、これ。旅のあいだの、ジェムコインのカード。",v:"04_0330"},{w:"elly",t:"いいの？",v:"04_0331"},{w:null,t:"エリー、カードを両手で受け取って、肩かけカバンの内ポケットにしまう。"},{w:null,t:"アナ、アレクの方を向く。"},{w:"ana",t:"（アレクに）宿代は、泥かきでちゃらにしてあげる。",v:"04_0334"},{w:"ana",t:"そのかわりカードの分は、帰ってきたら働いて返してね。",v:"04_0335"},{w:null,t:"アレク、エリーのカバンの内ポケットを見る。"},{w:null,t:"アレク、背すじをのばして、アナに頭を下げる。"},{w:"alek",t:"（一段低い声で）……ちゃんと返しに来ますわ。",v:"04_0338"},{w:"alek",t:"（もっと低い声で）……実は僕、島に別荘持ってまして。",v:"04_0339"},{w:"alek",t:"（もっと低い声で）……お姉さん、僕とお茶しません？",v:"04_0340"},{w:null,t:"エリーの髪の中のピリポンが、ビリリ。"},{w:null,t:"アナ、エリーのカバンのひもを直したまま、顔を上げない。"},{w:"ana",t:"お茶代も、カードの分につけとくね。",v:"04_0343"},{w:null,t:"アレク、口をあけたまま止まる。"},{w:null,t:"アレク、だまって背すじをもどす。"},{w:null,t:"アレクの目が、ヤマトのリュックの横ポケットに行く。"},{w:"alek",t:"それ、すられんで。",v:"04_0347"},{w:"hero",t:"だれが取るんだよ、こんなの。",v:"04_0348"},{w:null,t:"アレク、指二本で、ちらしをすっと抜く。"},{w:"alek",t:"……ほらな。",v:"04_0350"},{w:null,t:"ヤマト、ひったくって、ポケットの奥へ押しこむ。"},{w:null,t:"エリー、パンの袋を抱え直す。"},{w:"alek",t:"エリー、パンの袋、口あいてんで。",v:"04_0353"},{w:"elly",t:"知ってる。わざと。",v:"04_0354"},{w:null,t:"エリーの足もとで、フォルンがパンくずを拾って食べている。"},{w:null,t:"アレク、ヤマトとエリーの方を向く。"},{w:"alek",t:"森の道で行くで。",v:"04_0357"},{w:null,t:"三人とフォルンが、ぶどう畑の先の森の道へ。"},{w:null,t:"ヤマト、一度ふり返る。"}];
GR_SC.g04_11=[{w:null,t:"窓のない暗い部屋。"},{w:null,t:"白い右手が、写真を指で大きくする。"},{w:null,t:"となりの欄に、1話の写真。少年の前でしっぽを立てる、小さな狐。"},{w:null,t:"人さし指が、宙の字の板を、ゆっくり押していく。"},{w:null,t:"もう一枚。ニーナが門で撮った、泥かきのアレク。指が、それを一度大きくして、もどす。"},{w:null,t:"指が、送り先の並びの上で止まる。"},{w:null,t:"指が、机を、とん、とん。それから「ニーナ」を押す。"},{w:null,t:"字が一行。「ドローンを出せ。"}];
GR_BT[4]={mid:[[{w:"hero",f:"surprised",t:"（用水路の手前の土を指さして）フォルン、そっちじゃねえ！　こっちだ！",v:"04_0152"},{w:"marco",t:"スミヤモ、焼いちまえ。",v:"04_0156"},{w:"hero",t:"撃て、フォルン！　もっと撃て！",v:"04_0163"},{w:"hero",t:"ちがう、近くだ！　林まで行け！",v:"04_0165"},{w:null,t:"マルコのうしろで、ニーナが手首の画面を指で押す。"},{w:null,t:"マルコ、木箱から半分立ち上がる。"},{w:"hero",t:"出ろ！　フォルン、林から出ろ！",v:"04_0184"},{w:"hero",t:"右だ！　いや、左！　下がれ、フォルン！",v:"04_0186"},{w:null,t:"アレクは何も言わない。組んだ腕の指が、ひじをつかんでいる。"}],[{w:null,t:"マルコ、木箱から腰を上げて、のびをする。"},{w:"marco",t:"これ以上焦がすと、あとでボスがうるさいんだ。",v:"04_0192"},{w:"marco",t:"オキヤモ、止まれ。",v:"04_0193"},{w:"marco",t:"……オキヤモ？　止まれって言ってるだろ。",v:"04_0196"},{w:null,t:"ニーナの手首の画面が鳴る。"},{w:"marco",t:"……ニーナ、止められないのか？",v:"04_0198"},{w:null,t:"ニーナ、だまって画面をマルコに向ける。"},{w:null,t:"マルコ、ニーナの画面をのぞきこんだまま、だまる。"}],[{w:"marco",t:"……止まってくれよ。",v:"04_0207"},{w:null,t:"ヤマト、ぶどう棚の前から飛び出す。"},{w:null,t:"ヤマト、ふりほどこうとする。"},{w:null,t:"ヤマト、ひざをつく。"},{w:"hero",t:"（小さく、呼ぶだけ）……フォルン。",v:"04_0214"},{w:null,t:"ヤマトの目が、大きくなる。"},{w:"hero",t:"フォルン、進化！",v:"04_0223"},{w:"hero",f:"smile",t:"（小声で）……すっげー。",v:"04_0229"}],[{w:null,t:"ヤマトの目が、二つの炎を見くらべる。"},{w:"hero",t:"フォルコン、あいつを水から上げるな！",v:"04_0242"},{w:null,t:"ヤマト、何か叫びかけて、口を閉じる。"},{w:null,t:"マルコ、木箱のふちをつかんだまま、動けない。"},{w:"hero",t:"（オキヤモを指さして）フォルコン、フォックスファイヤー！",v:"04_0262"},{w:"marco",t:"……もういいって。お前、がんばったよ。",v:"04_0267"}]],post:[]};
GR_EP[4]={"t": "夜明けの火", "sc": [["g04_01", "村を見下ろす坂（夜明け）", 0], ["g04_02", "ホテルの裏・道具小屋（朝）", 0], ["g04_03", "ホテルのテラス（朝）", 0], ["g04_04", "ホテルの門", 0], ["g04_05", "ホテルの裏の畑・向かい合う", 0], ["g04_06", "勝負・炎どうし（2Dアニメ）", 1], ["g04_07", "勝負・止まらない（2Dアニメ）", 1], ["g04_08", "勝負・水から上げない（2Dアニメ）", 1], ["g04_09", "勝負のあと", 0], ["g04_10", "ホテルのロビーと門（昼前）", 0], ["g04_11", "窓のない部屋", 0]]};
GR_SC.g05_01=[{w:null,t:"オリーヴァ村を出た三人は、丘のオリーブの木の下で夜を明かした。",v:"05_0033"},{w:null,t:"丘の中腹。古いオリーブの木の下に、銀色のうすいシートが一枚。"},{w:null,t:"ヤマトだけ、シートからはみ出して、草の上で大の字。"},{w:null,t:"フォルンは、シートのはしで丸くなっている。しっぽの火だけが、シートの外に出ている。"},{w:null,t:"丘の下の道。"},{w:null,t:"アレク、目をあける。"},{w:null,t:"アレク、フォルンのしっぽをつかんで、シートの中へ押しこむ。"},{w:null,t:"アレク、ヤマトの腕をつかんで、シートの下へずるずる引きずりこむ。エリーは、目をつむったまま、自分でころころ転がって場所をあける。"},{w:null,t:"ドローンが丘を上がってきて、オリーブの木の上で止まる。"},{w:"hero",t:"（寝ぼけて）……なに。もう朝？　なんで、おれの腕、引っぱってんの。",v:"05_0043"},{w:"alek",t:"ヴィクターのドローンや。",v:"05_0044"},{w:"alek",t:"お前だけ、外で大の字で寝てたんやで。",v:"05_0045"},{w:"hero",t:"だったら、ふつうに起こせよ。",v:"05_0046"},{w:"alek",t:"ドローンの真下で、大声出せるかい。",v:"05_0047"},{w:"hero",f:"serious",t:"……おい、手袋。",v:"05_0051"},{w:null,t:"第5話　丘の畑",v:"05_0053"}];
GR_SC.g05_02=[{w:null,t:"オリーヴァ村の東。オリーブの丘が、いくつも続いている。",v:"05_0059"},{w:null,t:"道ばたで、収穫ロボットが一台休んでいる。"},{w:"elly",t:"今日のラッキースポットは、古い字のある所だって！",v:"05_0061"},{w:null,t:"ヤマトはフォルンのしっぽを、アレクは丘の下のドローンを見ている。"},{w:"elly",f:"serious",t:"……聞いてないし。",v:"05_0063"},{w:null,t:"エリー、ほっぺをぷくっとふくらませる。"},{w:null,t:"となりの大きな丘。"},{w:null,t:"こちらの斜面の畑。"},{w:"hero",t:"あっちの丘はロボットなのに、こっちは手か。",v:"05_0067"},{w:null,t:"ヤマト、ふしぎそうに、網の上の実を一つ拾って、近くの女の人のかごに入れる。"},{w:"x",n:"村の女の人",t:"ありがとう。……あなたたち、この丘を越えて行くの？",v:"05_0069"},{w:"elly",t:"うん。向こうがわに下りたいの。",v:"05_0070"},{w:"x",n:"村の女の人",t:"なら、いちばん上のヤニスさんの畑を通るしかないよ。",v:"05_0071"},{w:"x",n:"村の女の人",t:"先月から、よそ者にはきびしいけどね。",v:"05_0072"},{w:null,t:"ヤマト、丘のいちばん上を見上げる。"},{w:null,t:"クロッコは、アレクの足のうしろを、自分の足で歩いている。"}];
GR_SC.g05_03=[{w:null,t:"この丘のいちばん上に、ひときわ手入れのいい畑があった。",v:"05_0078"},{w:null,t:"畑の見えるところで、アレクの足が止まる。"},{w:null,t:"アレク、がけの下と石垣の高さを目ではかる。それから、畑の中の道へ歩き出す。"},{w:null,t:"手入れのいい木の並び。"},{w:null,t:"幹の小さな穴のいくつかに、黒い網の切れはしがひっかかったまま。"},{w:null,t:"畑のはしを、石を組んだ溝が流れている。"},{w:null,t:"手前のすみに、昔の脱穀場の、丸い石の床。"},{w:null,t:"畑のはしに、小さな石の家。"},{w:null,t:"男が一人、くずれた溝の石を、だまって積み直している。"},{w:null,t:"【字幕】「ヤニス」。"},{w:null,t:"ヤマト、石の床の上に、どさっと座って、両手をつく。"},{w:"hero",t:"エリー、この石、ぽかぽかしてる！",v:"05_0089"},{w:"hero",t:"朝早くたたき起こされたから、ちょっとだけ寝ていい？",v:"05_0090"},{w:"alek",t:"人の畑やで。",v:"05_0091"},{w:null,t:"エリーの肩から、ピリポンが石の床に、ぴょんと下りる。"},{w:null,t:"ヤマト、石についていた手を、さっと上げる。"},{w:null,t:"ピリポン、自分でびっくりして、エリーの足をかけ上がり、肩から髪の中にもぐる。"},{w:null,t:"太いオリーブの幹に、小さなカブトムシのテリオンがとまっている。"},{w:null,t:"【プロフィール】カブッコ／風／●○○／黄色い羽のカブトムシ"},{w:"hero",t:"カブトムシだ！",v:"05_0097"},{w:null,t:"ヤマト、幹にかけ寄る。"},{w:null,t:"カブッコが、幹の上で前足を、ぐっとふんばる。それから、つのを右下からすくい上げる。"},{w:null,t:"エリーだけが、それを見ている。"},{w:null,t:"ピリポンの毛の先から、火花が一つ、幹のカブッコのつのへ、ぴりっと跳ぶ。"},{w:null,t:"カブッコ、首をすくめて、羽をちぢめる。"},{w:null,t:"男の目が、ヤマトのうしろへ行く。"},{w:"stavros",f:"serious",t:"……よく見てるな。",v:"05_0106"},{w:"stavros",t:"先月の晩、ここに住んでた小さいのが、みんな連れていかれた。",v:"05_0109"},{w:"stavros",f:"serious",t:"……ヴィクターのチップだな。",v:"05_0113"},{w:"alek",t:"……そこの仕事、受けてます。",v:"05_0114"},{w:"hero",t:"でも、こいつ、まだ一回も狐を運んでねえんだよ！",v:"05_0116"},{w:"stavros",t:"「まだ」か。",v:"05_0117"},{w:"stavros",t:"口では、何とでも言える。",v:"05_0118"},{w:"stavros",t:"通りたいなら、勝負しろ。",v:"05_0120"},{w:"stavros",t:"負けたら、来た道を帰れ。",v:"05_0121"},{w:"alek",t:"ほな、こっちは三体で。",v:"05_0123"},{w:"elly",f:"serious",t:"……ピリポンも？",v:"05_0124"},{w:"alek",t:"ヤマトひとりより、ましやろ。",v:"05_0125"},{w:"hero",f:"serious",t:"……聞こえてんぞ。",v:"05_0126"},{w:"stavros",t:"そっちが三体なら、こっちも三体だ。",v:"05_0127"},{w:"hero",t:"え、三匹もいんの？",v:"05_0129"},{w:"stavros",t:"あの晩、家の中にいた三匹だけが残った。",v:"05_0130"}];
GR_SC.g05_04=[{w:null,t:"畑のまん中で、勝負が始まる。",v:"05_0137"},{w:null,t:"向こうのはしはオリーブの木。"},{w:null,t:"ヤニス、千年のオリーブの向こうがわ、幹のかげに立って、腕を組む。"},{w:null,t:"カブッコたちが、羽を一度広げる。"},{w:null,t:"羽の風で、手前の草が、さあっと一方へなびく。"},{w:null,t:"フォルン、手前のまん中に出る。"},{w:null,t:"ヤマト、手袋を拾って右手にはめる。"},{w:null,t:"アレク、クロッコを溝のそばの草に下ろす。"},{w:null,t:"エリー、石の床から十歩うしろの、石垣の前に立つ。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"stavros",t:"始め。",v:"05_0149"}];
GR_SC.g05_08=[{w:null,t:"昼。千年のオリーブの下。",v:"05_0241"},{w:null,t:"フォルコンとピリムサとヘラツノの体から、光がすうっと引いていく。"},{w:null,t:"ヤニス、カブッコ三匹のそばにしゃがむ。"},{w:null,t:"エリー、石の床の上のピリポンをだき上げる。"},{w:null,t:"エリー、ピリポンを顔の高さまで持ち上げて、その場でくるっと一回まわる。"},{w:null,t:"ピリポン、エリーのほっぺに、頭をすりすり。エリー、くすぐったそうに笑う。"},{w:"hero",t:"エリー、今の、もう一回なって！",v:"05_0247"},{w:"elly",t:"だめ。ピリポン、もう寝てる。",v:"05_0248"},{w:null,t:"エリーの腕の中で、ピリポン、鼻ちょうちん。"},{w:null,t:"アレク、溝からクロッコをだき上げて、ヤマトの横を通る。"},{w:"alek",t:"……お前の命令より、速かったな。",v:"05_0251"},{w:null,t:"ヤマト、言い返しかけて、口を閉じる。"},{w:null,t:"ヤマト、フォルンの前にしゃがむ。"},{w:"hero",f:"smile",t:"フォルン、さっきのフォルコン、すっげーかっこよかったぜ！",v:"05_0254"},{w:null,t:"フォルン、前足をなめたまま、ぷいとそっぽを向く。"},{w:null,t:"でも、しっぽの火だけが、ぼっと大きくなる。"},{w:null,t:"火が、ヤマトの前髪に届く。"},{w:"alek",t:"クロッコ、消してやれ。",v:"05_0258"},{w:null,t:"アレクの腕の中から、クロッコがヤマトの頭へ水をぴゅっ。"},{w:null,t:"ヤマト、前髪からしずくをたらして、だまる。"},{w:null,t:"エリー、指でなぞって、ちょっとだけ笑う。"},{w:null,t:"ヤニス、立ち上がって、アレクの前に来る。"},{w:null,t:"ヤニス、クロッコの頭に手のひらをのせる。それから、ふり返って、フォルンの耳のうしろを見る。"},{w:"stavros",t:"ドローンは、最後まで呼ばなかったな。",v:"05_0265"},{w:"alek",t:"勝負は、勝負なんで。",v:"05_0266"},{w:null,t:"ヤニス、石の家からガラスのびんを持ってくる。"},{w:"stavros",t:"しおみずに、二か月つけてある。食ってみろ。",v:"05_0268"},{w:null,t:"ヤマト、一つ口に入れる。顔が、きゅっとすっぱくなる。"},{w:"hero",t:"すっぱ！　……でも、うまい。もう一個、いい？",v:"05_0270"},{w:null,t:"ヤニス、うなずく。"},{w:null,t:"ヤニス、手首の画面にふれる。入口の柵が、すうっと下がって開く。"},{w:null,t:"ヤニスの手首の画面が、短く一回鳴る。"},{w:null,t:"写真の中の箱が、知らない字の書いた大きな荷物の箱の列に、ならべられている。"},{w:null,t:"ヤニスの指が、写真の上で止まる。"},{w:null,t:"ヤニス、だまって画面を閉じる。"},{w:null,t:"ヤマトは、ヤニスのななめうしろで、それを見ていた。"},{w:null,t:"アレクも、それを見ていた。"},{w:null,t:"ヤニス、かごを石の家の前に置いて、また、くずれた溝の石を積みはじめる。"},{w:null,t:"アレク、腕の中のクロッコの耳のうしろに、指を入れる。"},{w:null,t:"アレク、それを溝に落とす。"},{w:"stavros",t:"（石を積みながら）その仕事は、どうする。",v:"05_0283"},{w:"alek",t:"やめますわ。今日で。",v:"05_0284"},{w:"hero",t:"え。",v:"05_0285"},{w:"stavros",t:"なぜだ。",v:"05_0286"},{w:"alek",t:"割に合わへんので。",v:"05_0287"},{w:"stavros",f:"serious",t:"……そうか。",v:"05_0288"},{w:null,t:"アレク、溝のそばにしゃがむ。"},{w:null,t:"ヤニス、手を止めて、それを見る。"},{w:"hero",f:"serious",t:"……じゃあ、狐は？",v:"05_0291"},{w:"alek",t:"運ばへんわ。もう仕事ちゃう。",v:"05_0292"},{w:"hero",t:"なんだよ。最初からそう言えよ。",v:"05_0293"},{w:"alek",t:"最初は、仕事やったんや。",v:"05_0294"},{w:"hero",t:"じゃあ、もうついて来ねえのか？",v:"05_0295"},{w:"alek",t:"大会の賞金、半分はおれのやろ。",v:"05_0296"},{w:null,t:"アレク、ヤマトの背中を、ばしっとたたく。"},{w:null,t:"アレク、自分の手首の画面を開く。"},{w:"alek",t:"名無しにしたで。",v:"05_0299"},{w:"hero",t:"おっちゃん、この木って、何年生きてんの？",v:"05_0303"},{w:"stavros",t:"千年は、こえてる。",v:"05_0304"},{w:"hero",t:"千年……。",v:"05_0305"},{w:"ana",t:"エリー！　きのうの夜、どうしてかけてこなかったの！",v:"05_0308"},{w:"ana",t:"もう少しで、さがしに行くとこだったよ。",v:"05_0309"},{w:"elly",f:"sad",t:"ごめんね。きのうはオリーブの丘の上で寝てて——",v:"05_0310"},{w:"alek",t:"（小声で）場所を言うなや！",v:"05_0312"},{w:"elly",t:"……外で寝てたら、そのまま朝になっちゃったの。",v:"05_0313"},{w:"elly",t:"今夜からは、ちゃんとかけるから。",v:"05_0314"},{w:"ana",t:"……ごはんは、ちゃんと食べてる？",v:"05_0315"},{w:"elly",t:"うん。オリーブ、食べてる。",v:"05_0317"}];
GR_SC.g05_09=[{w:null,t:"夕方。三人は、畑の向こうの、いちばん高い丘のてっぺんに着いた。",v:"05_0323"},{w:null,t:"いちばん高い丘のてっぺんに、三人と三体。"},{w:null,t:"東の空。遠くの森の上に、灰色の煙が一本。"},{w:"hero",t:"あれ、煙だよな。何か燃えてんのか？",v:"05_0326"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:null,t:"煙の方角の、深い緑の場所。"},{w:"alek",t:"アルカディアの森や。白い都への道、あの中や。",v:"05_0330"},{w:"alek",t:"急ぐで。",v:"05_0331"},{w:null,t:"アレク、ゴーグルを頭に上げて、古い望遠鏡をのぞく。"},{w:null,t:"ドローンの胴に、オレンジの輪。"}];
GR_BT[5]={mid:[[{w:null,t:"ヤマト、三匹を目で追う。"},{w:"hero",t:"フォルン、まだ出るな。そこから一発いけ。",v:"05_0154"},{w:null,t:"ヤニス、手首をかざす。"},{w:"stavros",t:"カブッコ、進化。",v:"05_0158"},{w:null,t:"ヤマト、すぐに左の手首をかざす。"},{w:"hero",t:"フォルン、進化！",v:"05_0164"},{w:null,t:"ヤマトの目は、手首に落ちたまま。"},{w:"hero",f:"angry",t:"なんでだよ。進化だって！",v:"05_0167"}],[{w:"hero",t:"フォルン、進化！",v:"05_0178"},{w:"hero",t:"フォルコン、動くな。来たら、そこでぶっ放せ。",v:"05_0180"},{w:null,t:"ヤマト、指をそろえた手のひらを立てて、一歩うしろへ下がる。"},{w:"hero",t:"フォルコン、離れろ！　まだだ！",v:"05_0185"},{w:"alek",t:"クロッコ、みぞに引きずりこめ！",v:"05_0187"},{w:null,t:"エリーの目は、ヘラツノの前足に止まっている。"}],[{w:"elly",t:"ピリポン、ぱちって！",v:"05_0192"},{w:null,t:"ヤマトの目が、ヘラツノの止まった所に行く。"},{w:null,t:"ヤマトの目が、草の上を動く。"},{w:"hero",t:"フォルコン、まだふくな。あいつの下がる先で待て。",v:"05_0201"},{w:null,t:"エリー、石垣の前でしゃがむ。自分の手も、少しふるえている。"},{w:"elly",t:"ピリポン、進化！",v:"05_0212"}],[{w:null,t:"ヤニスの組んだ腕の指が、一本だけ動く。"},{w:null,t:"ヤマト、エリーの方を見る。だまって、うなずく。"},{w:"elly",t:"右！",v:"05_0222"},{w:"hero",t:"フォルコン、うしろをふさげ！",v:"05_0224"},{w:"elly",t:"ピリムサ！",v:"05_0227"},{w:"elly",t:"右！",v:"05_0231"}]],post:[{w:null,t:"ヘラツノが、草の上に、ころりと横になる。目を回している。"},{w:null,t:"アレク、ヤマトの腕を、ひじで小突く。"},{w:"alek",t:"羽の子は、雷に弱いんか。",v:"05_0236"},{w:"elly",t:"ピリムサ、えらいえらい！",v:"05_0237"},{w:null,t:"千年のオリーブの葉が、風で、さあっと鳴る。"}]};
GR_EP[5]={"t": "丘の畑", "sc": [["g05_01", "丘のオリーブの木の下（夜明け）", 0], ["g05_02", "丘の斜面（朝）", 0], ["g05_03", "ヤニスの畑", 0], ["g05_04", "向かい合う", 0], ["g05_05", "勝負・押される", 1], ["g05_06", "勝負・下がる先", 1], ["g05_07", "勝負・決着", 1], ["g05_08", "勝負のあと", 0], ["g05_09", "丘のてっぺん（夕方）", 0]]};
GR_SC.g06_01=[{w:null,t:"五日目の昼。アルカディアの森の、川べり。",v:"06_0028"},{w:null,t:"昼の森。乾いた落ち葉が、地面をうめている。"},{w:null,t:"川べりの大きな岩の上に、ニーナが黒い箱を置く。"},{w:null,t:"箱の穴から、言葉のない細い歌がもれる。草むらの奥で、小さな子が首を上げる。"},{w:null,t:"ニーナ、手首の画面にふれる。"},{w:"marco",t:"あばれると、網が破れるんだよなあ。",v:"06_0033"},{w:null,t:"ニーナ、足もとの小さなおりの戸をあける。"},{w:null,t:"【プロフィール】ビリトラ／雷／●○○／毛が逆立つと火花がはぜる"},{w:"nina",t:"あばれる子は、こいつでおどかせってさ。",v:"06_0036"},{w:null,t:"虎の子の背中の毛が、逆立つ。"},{w:"marco",t:"……もう、それくらいでいいだろ。",v:"06_0038"},{w:null,t:"虎の子、毛を下ろさない。"},{w:"marco",t:"ちょっと、止めてくれよ。",v:"06_0041"},{w:"nina",t:"……止まんないのよ、これ。",v:"06_0046"},{w:"marco",t:"森ごと焼く気かよ。",v:"06_0047"},{w:null,t:"第6話　燃える森",v:"06_0051"}];
GR_SC.g06_02=[{w:null,t:"六日目の昼すぎ。",v:"06_0057"},{w:null,t:"森へ続く道。三人とも、目の下にくま。"},{w:null,t:"アルカディア。楽園という名の森だ。",v:"06_0059"},{w:null,t:"森の入口。木の枠の自動ゲート。"},{w:null,t:"アレク、パーカーのフードを深くかぶる。受付のロボットの目から、顔をそらす。"},{w:null,t:"エリー、白い肩かけカバンから、手のひら大のうすいカードを出す。"},{w:null,t:"カードの上に、残高の数字が光る。"},{w:null,t:"アレク、横からその数字をのぞきこむ。"},{w:"alek",t:"エリー、そのカード、おれが持つわ。",v:"06_0065"},{w:"elly",t:"いいよ。アレク、お金の計算、好きだもんね。",v:"06_0066"},{w:"alek",t:"好きでやってるんやない。",v:"06_0067"},{w:null,t:"言いながら、アレク、カードを両手で受け取って、パーカーの内ポケットにしまう。"},{w:null,t:"ゲートが、すうっと開く。"}];
GR_SC.g06_03=[{w:null,t:"焦げたにおいが、だんだん強くなる。"},{w:null,t:"木のあいだがひらけた所。"},{w:null,t:"小川のふちに、手さげかばんほどの小さなポンプ。"},{w:"x",n:"作業員のおじさん",t:"泡は、これで終わりだ！　あとは水しかないぞ！",v:"06_0075"},{w:null,t:"アレク、もうクロッコを小川に下ろしている。"},{w:null,t:"エリー、肩のピリポンを髪の中へ押しもどして、バケツを回す人たちの中に入る。"},{w:null,t:"フォルン、燃える草の前に立つ。しっぽを、ひと振り。"},{w:null,t:"ヤマト、バケツの列に走っていって、前の人からバケツを受け取る。"},{w:null,t:"煙の向こうで、ぱちぱちっと新しい火の音。"},{w:null,t:"虎の子の頭のうしろで、チップがちかっと光る。目のふちが、オレンジ色。"},{w:"x",n:"作業員のおじさん",t:"あいつだ！　きのうから、あいつが火をつけて回ってる！",v:"06_0082"},{w:null,t:"虎の子を追って、煙の中から、すすだらけの二人組が走り出てくる。"},{w:"hero",t:"あっ！　マカロンと、えーと……！",v:"06_0084"},{w:"nina",t:"なによ、またあんたたちなの？",v:"06_0085"},{w:null,t:"ニーナの目が、小川のクロッコとアレクに止まる。"},{w:"nina",t:"……アレク？　あんた、そっちにいるの？",v:"06_0087"},{w:"alek",t:"（水をくみながら）仕事やめただけや。",v:"06_0088"},{w:"marco",t:"……え、やめれんの？",v:"06_0089"},{w:"hero",t:"お前らが燃やしたのかよ。",v:"06_0090"},{w:"nina",t:"燃えたのよ！　燃やしたんじゃないわ！",v:"06_0091"},{w:null,t:"ニーナの目が、ヤマトの足もとのフォルンに止まる。"},{w:"nina",t:"……ちょうどいいじゃないの。",v:"06_0093"},{w:"nina",t:"ボスがほしがってた狐よ。マルコ、もらっていくわよ！",v:"06_0094"},{w:"marco",t:"え、今か？　森、燃えてんだぞ。",v:"06_0095"},{w:"nina",t:"だからでしょ。だれも手が空いてないじゃないの。",v:"06_0096"},{w:"hero",t:"森が燃えてんのに、なに言ってんだよ！",v:"06_0097"},{w:null,t:"ニーナ、手首の画面を、虎の子の方へ向けてはじく。"},{w:"nina",t:"行きなさい！　狐をやっちゃって！",v:"06_0099"},{w:null,t:"虎の子の毛が逆立つ。"},{w:null,t:"フォルンが、その火の前に跳びこむ。しっぽで吸いこむ。"},{w:null,t:"スミヤモの小さな火と、フォルンのしっぽの火が、一瞬だけ重なって、太く立つ。"},{w:"x",n:"森番のおばあさん",t:"みんな、上の焼けあとまで下がるよ！",v:"06_0105"}];
GR_SC.g06_05=[{w:null,t:"ヤマトが大木のかげから走っていって、フォルンの前にしゃがむ。"},{w:null,t:"フォルン、ふらつきながら、ヤマトのうしろへ回る。"},{w:null,t:"ヤマト、ひざをついたまま、背中の焦げあとを見る。こぶしを、小さくにぎる。"},{w:"hero",f:"serious",t:"……お前、焦げてんじゃん。",v:"06_0175"},{w:null,t:"エリーが焼けあとから走ってくる。"},{w:"elly",t:"フォルン、背中、冷やそ！",v:"06_0177"},{w:null,t:"フォルン、そっぽを向いたまま、エリーの手の水を一回だけなめる。"},{w:null,t:"スミヤモが、マルコの足もとにもどってくる。マルコ、しゃがんで、スミヤモの頭に手をのせる。"},{w:null,t:"マルコ、立ち上がって、だまってバケツの列に入る。"},{w:"hero",f:"serious",t:"……お前。",v:"06_0184"},{w:"marco",t:"今、それどころじゃないだろ。バケツ、次に回してくれ。",v:"06_0185"},{w:"hero",f:"serious",t:"……やるじゃん、ニンニクとマカロン。",v:"06_0188"},{w:"nina",t:"誰がニンニクとマカロンよ！",v:"06_0189"},{w:"nina",t:"ドローンが来たわ。写真に写る前に、行くわよ。",v:"06_0191"}];
GR_SC.g06_06=[{w:null,t:"森の裏がわの、舗装された細い道。"},{w:null,t:"木のあいだから、ニーナとマルコが出てくる。"},{w:null,t:"ニーナの手首の画面に、字。"},{w:null,t:"ニーナ、送り先の「本部」の欄を、長く押して消す。"},{w:null,t:"マルコ、スミヤモの耳のうしろのチップを見る。"},{w:null,t:"二人、車に背を向けて、反対がわの草の小道を歩きだす。"},{w:"marco",t:"……朝めし、まだだな。",v:"06_0201"},{w:"nina",t:"……行くわよ。",v:"06_0202"},{w:null,t:"うしろで、ドアがすうっと閉まる。"}];
GR_SC.g06_07=[{w:null,t:"ラドン川。この秋は、夜になると、川から歌が聞こえる。",v:"06_0206"},{w:null,t:"森の外がわを流れる川。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:null,t:"森の道の線に、赤い字。"},{w:null,t:"船着き場に、白い小さな観光船。"},{w:null,t:"切符の機械。"}];
GR_SC.g06_08=[{w:null,t:"白い小さな観光船。だれも舵をにぎっていない。"},{w:null,t:"エリー、カバンから光るテリオンのシール帳を出す。"},{w:"elly",t:"ねえねえ、シール交換しよ！",v:"06_0218"},{w:null,t:"ヤマトは、光る川を見ている。"},{w:null,t:"アレク、カードを見たまま、手のひらだけエリーの方へ出す。"},{w:null,t:"エリー、目を丸くして、その手のひらにシールを一枚貼る。"},{w:null,t:"アレク、見もせずに、そのシールをゴーグルのバンドに貼る。"},{w:null,t:"エリー、にこにこして、次のシールを選ぶ。"},{w:null,t:"案内のロボットが、かごを持って回っている。"},{w:null,t:"エリーがフォルンにも耳あてを持っていく。"},{w:null,t:"ヤマトだけ、耳せんを取らない。"},{w:"elly",t:"ヤマト、耳せんしないの？",v:"06_0227"},{w:"hero",t:"だって、どんな歌か聞いてみたいじゃん。",v:"06_0228"},{w:"alek",t:"聞いたら、川に入ってまう歌らしいで。",v:"06_0229"},{w:null,t:"ヤマト、船のまん中の太い柱を見上げる。"},{w:"hero",t:"じゃあさ、あの柱におれをしばっといてくれよ。",v:"06_0231"},{w:"hero",t:"それなら、飛びこめないだろ。",v:"06_0232"},{w:"alek",t:"言うとくけど、歌終わるまで、ほどかへんで。",v:"06_0234"},{w:"hero",t:"いいって。おれ、そんなのに負けねーし。",v:"06_0235"},{w:"elly",t:"……歌を聞いた船乗りは、岩へ寄っていったって。",v:"06_0239"},{w:"elly",t:"船長は、自分を柱にしばらせたんだって。",v:"06_0240"},{w:"hero",f:"serious",t:"……で、その船長、どうやってほどいたんだ。",v:"06_0244"}];
GR_SC.g06_09=[{w:null,t:"川幅が広くなる。"},{w:null,t:"歌が聞こえてくる。"},{w:null,t:"船べりのフォルンのしっぽの火が、ぱちぱちと大きく鳴りだす。"},{w:null,t:"フォルン、耳を伏せて、自分の火の音の中にうずくまる。"},{w:null,t:"岸の葦のあいだから、野生の子たちが出てくる。"},{w:null,t:"ヤマトの目が、その子たちを追う。"},{w:"hero",t:"ちょっと、ほどけ！　ちょっとだけでいいから！",v:"06_0256"},{w:"hero",t:"エリー！　ほどけって！　エリーってば！",v:"06_0259"},{w:"hero",t:"フォルン！　あの岩の箱だ！　あそこから鳴ってる！",v:"06_0265"},{w:"alek",t:"なんや、ずっと口が動いてたけど。何か言うてたんか？",v:"06_0274"},{w:"hero",f:"serious",t:"……べつに。ぜんぜん、平気だったし。",v:"06_0275"},{w:"alek",t:"結び目、三つにしといて正解やったな。",v:"06_0276"}];
GR_SC.g06_10=[{w:null,t:"最後の船着き場。"},{w:"alek",t:"あの箱、昼の二人のや。",v:"06_0283"},{w:"hero",f:"serious",t:"……あいつら、さっき火、消してたじゃん。",v:"06_0284"},{w:"alek",t:"置いたん、きのうやろ。",v:"06_0285"},{w:null,t:"岸から上がる道に、細い柱が二本。"},{w:null,t:"ひもの向こうは、まっ暗な森。"},{w:"alek",t:"今夜は、どっか寝るとこさがすしかないわ。",v:"06_0288"},{w:null,t:"道のわきの明かりの方へ歩く。"},{w:null,t:"地面が、ひもで四角く区切ってある。"},{w:null,t:"バケツ。ブラシ。"},{w:null,t:"そのはしに、小さな組み立て式の小屋。"},{w:null,t:"エリー、小屋の戸を、こんこんとたたく。"},{w:"x",n:"女の人",t:"……こんな夜ふけに、何の用？",v:"06_0295"},{w:"elly",t:"こんばんは！　今夜、泊まれる所はありませんか！",v:"06_0296"},{w:"alek",t:"床で十分っす。助かります。",v:"06_0297"},{w:"x",n:"女の人",t:"……床でいいなら、入って。",v:"06_0299"}];
GR_BT[6]={mid:[[{w:"hero",f:"surprised",t:"フォルン、追え！",v:"06_0113"},{w:null,t:"ヤマト、大木のかげから飛び出す。手をのばして、フォルンの方へ走る。"},{w:"marco",t:"出んな！　お前まで焦げるだろ！",v:"06_0119"},{w:null,t:"ヤマト、大木のかげのはしで、その声に足が止まる。"},{w:null,t:"ヤマト、転がったフォルンを見る。のばした手が、宙で止まっている。"},{w:"nina",t:"もう一発！",v:"06_0123"},{w:"nina",t:"ちょっと、そっちじゃないわよ！　狐だけでいいの！",v:"06_0130"},{w:null,t:"ニーナ、画面をはじく。"}],[{w:"marco",t:"ニーナ、止めろって！",v:"06_0132"},{w:"nina",t:"……止まんないのよ！",v:"06_0133"},{w:null,t:"ニーナ、画面の「止まるな」を見る。それから、あとずさる村の人たちを見る。"},{w:null,t:"ヤマトの目が、虎の子から、おばあさんの足もとの火へ動く。"},{w:"hero",t:"フォルン、撃つな！　あっちの火だ！",v:"06_0137"},{w:null,t:"ヤマト、焼けあとの手前の火を、まっすぐ指さす。"},{w:null,t:"おばあさんの足もとの火の前に、すべりこむ。しっぽをひと振り。"},{w:null,t:"ヤマトのとなりで、マルコがそれを見ている。"},{w:"marco",t:"……スミヤモ、行くぜ。",v:"06_0144"},{w:"nina",t:"マルコ！　あんた、どっちの味方よ！",v:"06_0145"}],[{w:"marco",t:"森ごと燃えたら、狐もなにもねえだろ！",v:"06_0146"},{w:null,t:"ヤマト、となりのマルコを見る。"},{w:"marco",t:"おい！　そっちからも寄せろ！",v:"06_0150"},{w:"hero",t:"おう！　フォルン、前だ！",v:"06_0151"},{w:null,t:"ヤマト、指をそろえた手のひらを、フォルンへまっすぐ立てる。"},{w:"hero",t:"フォルン、今だ！",v:"06_0159"},{w:"marco",t:"スミヤモ、いっしょにやれ！",v:"06_0160"}]],post:[{w:null,t:"頭のうしろのチップが、ぱきっと割れる。目のふちのオレンジ色が、すうっと消える。"},{w:null,t:"虎の子、起き上がって、ぶるっと水をはらう。"},{w:null,t:"焼けあとから、アレクがバケツを下げて走り下りてくる。"},{w:"alek",t:"火ぃ二つ合わせたら、太なるんか。",v:"06_0168"}]};
GR_EP[6]={"t": "燃える森", "sc": [["g06_01", "アルカディアの森・川べりの岩（5日目の昼）", 0], ["g06_02", "アルカディアの森の入口（6日目の昼すぎ）", 0], ["g06_03", "森の中（昼すぎ）", 0], ["g06_04", "勝負・森の火（2Dアニメ）", 1], ["g06_05", "森の中・火のあと（昼すぎ）", 0], ["g06_06", "森の裏の道（夕方前）", 0], ["g06_07", "川の船着き場（夕方）", 0], ["g06_08", "観光船の上（夜）", 0], ["g06_09", "歌の瀬（夜）", 0], ["g06_10", "森の外れの船着き場（夜ふけ）", 0]]};
GR_SC.g07_01=[{w:null,t:"森の外れの発掘場。三人は、ここの小屋に泊めてもらった。",v:"07_0025"},{w:null,t:"組み立て式の小屋の中。"},{w:null,t:"女の人が、床の手前の半分を指さす。"},{w:"x",n:"女の人",t:"奥は、先に来た子が使ってるから。",v:"07_0028"},{w:null,t:"奥の床に、銀色のシート。"},{w:null,t:"【字幕】「レン」。"},{w:"x",n:"女の人",t:"今夜は、迷子がよく来るねえ。",v:"07_0031"},{w:null,t:"ヤマト、手首の画面でテリオンの動画を開く。"},{w:"dimi",f:"serious",t:"……日本の人？",v:"07_0033"},{w:"hero",t:"そうだけど。……え、日本語しゃべれんの？",v:"07_0034"},{w:"dimi",t:"親が日本人なんだ。おれは、アメリカから来た。",v:"07_0035"},{w:"elly",t:"へえ、アメリカから。わたしはエリー。こっちはヤマト。",v:"07_0036"},{w:"dimi",t:"レン。",v:"07_0037"},{w:null,t:"レン、それだけ言って、手首の画面に目をもどす。"},{w:null,t:"アレクの手が、パーカーのポケットの前で止まる。"},{w:"alek",t:"レンって……前の大会で優勝した、あのレンか？",v:"07_0040"},{w:"dimi",t:"ああ。",v:"07_0041"},{w:null,t:"エリー、口に手を当てる。"},{w:"hero",f:"serious",t:"……優勝？　マジか。",v:"07_0043"},{w:"hero",t:"今年も出んのか。",v:"07_0044"},{w:"dimi",t:"出る。",v:"07_0045"},{w:"hero",t:"おれも出る！",v:"07_0046"},{w:null,t:"レンの目が、戸口で丸くなっているフォルンの、しっぽの火に行く。"},{w:"dimi",t:"あの狐、お前の相棒か？",v:"07_0048"},{w:"hero",t:"相棒だよ。……まだ登録してねえけど。",v:"07_0049"},{w:null,t:"ヤマト、戸口の方を指さす。"},{w:"dimi",t:"その狐、お前の言うこと聞くのか？",v:"07_0051"},{w:"hero",t:"聞くよ！　……たまに。",v:"07_0052"},{w:null,t:"レン、それには何も言わない。手首の画面に目をもどす。"},{w:null,t:"レンの画面に、写真が一枚。"},{w:null,t:"レン、画面を消して、シートに横になる。"},{w:null,t:"ヤマト、エリーに顔を寄せる。"},{w:"hero",t:"（小声で）なんか、感じわりいな。アメリカのやつ。",v:"07_0057"},{w:"elly",t:"（小声で）名前、レンだって。さっき聞いたでしょ。",v:"07_0058"},{w:null,t:"第7話　発掘場",v:"07_0060"}];
GR_SC.g07_02=[{w:null,t:"次の日の朝。",v:"07_0066"},{w:null,t:"朝の光。ひもで四角く区切った地面に、掘りかけの穴がいくつも。"},{w:null,t:"奥の床の銀色のシートは、きちんとたたんである。"},{w:null,t:"ヤマト、青いシートのまわりを、ぐるぐる回っている。"},{w:null,t:"小屋から、女の人が出てくる。"},{w:"x",n:"女の人",t:"それ、気になる？",v:"07_0071"},{w:"hero",t:"なる！　きのうの夜から、ずっと気になってたんだよ。",v:"07_0072"},{w:"x",n:"女の人",t:"じゃあ、朝ごはんの前に、ちょっとだけね。",v:"07_0073"},{w:null,t:"女の人、手首の画面にふれる。"},{w:null,t:"シートの下は、赤土の大きな岩。"},{w:null,t:"へこみの中は、空っぽ。"},{w:null,t:"ヤマト、一歩下がって、首をそらして見上げる。"},{w:"hero",f:"serious",t:"……でっけえ。これ、なんの骨？",v:"07_0078"},{w:"x",n:"女の人",t:"骨じゃなくて、骨の型なの。",v:"07_0079"},{w:"alek",t:"型ってことは……骨は、どこにあるんすか。",v:"07_0080"},{w:"x",n:"女の人",t:"三年掘ってるけど、かけら一つ出てこない。",v:"07_0081"},{w:"alek",t:"三年で、ゼロ……。それ、元取れるんすか。",v:"07_0082"},{w:null,t:"足もとのクロッコが、アレクを見上げる。"},{w:"x",n:"女の人",t:"取れてたら、もっといい小屋に住んでるよ。",v:"07_0084"},{w:null,t:"アレク、前髪から水をたらしたまま、真顔で、型のふちを目で追っていく。"},{w:null,t:"ヤマト、型の肩のあたりの、なだらかに盛り上がった線を見上げている。"},{w:null,t:"山のようにまるく盛り上がって、先でがくっと落ちる形。"},{w:"hero",t:"（女の人に）肩んとこ、山みてえ。",v:"07_0089"},{w:"x",n:"女の人",t:"でしょ。……今日は村の子の発掘体験の日なの。",v:"07_0090"},{w:"x",n:"女の人",t:"手伝ってくれる？",v:"07_0091"},{w:null,t:"エリー、アイボリーのニットに、濃い色のまっすぐなデニム。"},{w:null,t:"髪は肩にかけた一本の三つ編み。"},{w:"elly",t:"まかせて！　ふるい、どこ？",v:"07_0094"},{w:"hero",t:"おれも化石掘りたい！　どこ掘りゃいい？",v:"07_0095"},{w:"x",n:"女の人",t:"ひもの中はだめ。きみは、子どもたちとふるいの係ね。",v:"07_0096"},{w:null,t:"ヤマト、肩を落とす。"}];
GR_SC.g07_03=[{w:null,t:"村の子どもたちが五人。"},{w:null,t:"仕分けのロボットが、四本の足で歩きながら、ふるいに残った石を箱に分けていく。"},{w:null,t:"ヤマトも、子どもたちにまざって、ふるいをふる。"},{w:null,t:"女の人が、手をたたいて、子どもたちを型の前に集める。"},{w:"x",n:"女の人",t:"はい、休けい。この型の昔話、してあげる。",v:"07_0104"},{w:"x",n:"女の人",t:"村のおばあちゃんたちから聞いた話だけどね。",v:"07_0105"},{w:null,t:"子どもたちが、型の前の地面に座る。"},{w:"x",n:"女の人",t:"大昔の生き物は、昔の言葉しか聞かないんだって。",v:"07_0107"},{w:"x",n:"女の人",t:"今の言葉で「おすわり」って言っても、知らん顔。",v:"07_0108"},{w:"x",n:"村の女の子",t:"じゃあ、昔の言葉で言ったら、おすわりするの？",v:"07_0109"},{w:"x",n:"女の人",t:"するする。骨だけになっても、たぶんするよ。",v:"07_0110"},{w:null,t:"子どもたちが笑う。"},{w:null,t:"エリーの、ピリポンの頭をなでていた指が、一度だけ止まる。"},{w:"x",n:"女の人",t:"それとね、この型の主は、だれかが連れていったんだって。",v:"07_0113"},{w:"x",n:"村の男の子",t:"こんなに大きいのを？　どうやって連れてくの？",v:"07_0114"},{w:"x",n:"女の人",t:"さあ。ひもでもつけて、引っぱったんじゃない？",v:"07_0115"},{w:"x",n:"村の男の子",t:"ひもじゃ無理だよ！　ちぎれちゃうって。",v:"07_0116"},{w:"x",n:"女の人",t:"だよねえ。おばあちゃんたちも、そこは知らないの。",v:"07_0117"},{w:null,t:"アレク、型の空っぽのへこみを見ている。"},{w:null,t:"休けいの続き。"},{w:"x",n:"村の女の子",t:"この子、しっぽが燃えてる！　だれの子？",v:"07_0120"},{w:null,t:"ヤマト、ふるいを置いて、すっと立ち上がる。"},{w:"hero",t:"おれの相棒。フォルンっていうんだ。",v:"07_0122"},{w:null,t:"フォルン、目をあけずに、しっぽを一回だけふる。"},{w:"x",n:"村の男の子",t:"この子、強いの？",v:"07_0124"},{w:"hero",t:"強いよ。白い都の大会にも出るしな。",v:"07_0125"},{w:"hero",t:"優勝なんか、楽勝だよ。",v:"07_0126"},{w:null,t:"日なたのフォルン、片目だけあけて、ヤマトを見る。"},{w:null,t:"少しはなれたアレク、ため息をひとつ。"},{w:"x",n:"村の男の子",t:"すげえ！",v:"07_0129"},{w:"x",n:"村の女の子",t:"それ、世界じゅうから来る大会でしょ？",v:"07_0130"},{w:"hero",t:"そう。そこで一番になるんだよ。",v:"07_0131"},{w:null,t:"型の外。少しはなれた木のかげ。"},{w:null,t:"レンの口のはしが、ほんの少しだけ上がる。"}];
GR_SC.g07_04=[{w:null,t:"ヤマト、子どもたちのあいだを抜けて、レンの方へ歩いていく。"},{w:"hero",t:"おい、アメリカ。今、笑ったろ。",v:"07_0137"},{w:"dimi",t:"笑ってない。",v:"07_0138"},{w:"hero",t:"笑ったって！　ほんとに勝てるから言ってんだよ！",v:"07_0139"},{w:"dimi",t:"大会に出るなら、どうせどこかで当たる。",v:"07_0140"},{w:"dimi",t:"今やるか？",v:"07_0141"},{w:"hero",t:"やって——",v:"07_0142"},{w:null,t:"アレクが、うしろからヤマトの肩をつかむ。"},{w:"alek",t:"待て待て、前の優勝者やぞ。",v:"07_0144"},{w:"alek",t:"テリオンも見えへんのに、受けんなや。",v:"07_0145"},{w:null,t:"ヤマト、アレクの手をふりはらう。"},{w:"hero",t:"テリオンなんか、どっかにいんだろ。やってやるよ！",v:"07_0147"},{w:"x",n:"女の人",t:"はい、そこまで。今は子どもたちがいるでしょ。",v:"07_0148"},{w:"x",n:"女の人",t:"やるなら夕方。ひもの外でね。型にだけは当てないで。",v:"07_0149"},{w:"dimi",t:"わかった。夕方まで待つ。",v:"07_0150"},{w:null,t:"レン、木のかげへもどって、また画面を見る。"},{w:null,t:"ヤマト、ふくれっつらで、ふるいの係にもどる。"},{w:null,t:"レンの足もとの地面。"},{w:null,t:"盛り上がった土のすき間から、緑の目が一つ、のぞく。"},{w:null,t:"小鳥の羽から色が抜けて、灰色のまま、ぴたりと止まる。"}];
GR_SC.g07_06=[{w:null,t:"女の人が来て、型の青いシートの焦げたはしを、指でつまむ。"},{w:"x",n:"女の人",t:"……型は、無事。あの子、強かったね。",v:"07_0227"},{w:null,t:"アレク、うなずく。"},{w:null,t:"アレク、自分の目を指でさす。"},{w:"alek",t:"目ぇ合うたら、固まるんか。",v:"07_0230"},{w:null,t:"ヤマト、アレクの腕の中の、灰色のクロッコを見る。"},{w:"alek",t:"……あれは、しゃあない。",v:"07_0232"},{w:"hero",t:"分かってるよ。",v:"07_0233"},{w:null,t:"ヤマト、その場にひざをつく。"},{w:"hero",f:"angry",t:"くそっ……！",v:"07_0235"},{w:null,t:"ヤマト、アレクの顔を見ないまま、立ち上がって、倒れたフォルンの方へ歩いていく。"},{w:null,t:"レン、何も言わずに小屋の方へ歩いていく。"},{w:null,t:"エリー、ピリポンをだき上げる。"},{w:"alek",t:"（クロッコの背中をさすりながら）……ピリポン、色もどったか。",v:"07_0239"},{w:"elly",t:"うん。もうちょっと。",v:"07_0240"},{w:null,t:"アレク、地面に座る。"},{w:null,t:"クロッコのしっぽの先から、灰色が抜ける。"},{w:"hero",t:"エリー、テリオンの薬、ちょっと借りるな。",v:"07_0244"},{w:"elly",t:"いいよ。そっとね。",v:"07_0245"},{w:"elly",t:"ちょっと、また右手！　ほら、見せて。",v:"07_0250"}];
GR_SC.g07_07=[{w:null,t:"光る板の下のテーブル。"},{w:null,t:"女の人が、奥のレンにテーブルを指さして呼ぶ。レンは首を横にふって、奥のシートの上で一人で食べている。"},{w:null,t:"ヤマト、スープに口をつけない。"},{w:"elly",t:"ヤマト、ご飯、先。",v:"07_0257"},{w:"hero",f:"serious",t:"……食べてるよ。",v:"07_0258"},{w:null,t:"ヤマト、豆を一つだけ口に入れる。"},{w:null,t:"エリー、自分のパンを半分にちぎって、だまってヤマトの皿に置く。"},{w:"alek",t:"食わへんなら、それ、おれがもらうで。",v:"07_0261"},{w:null,t:"アレクの手が、ヤマトの皿のパンにのびる。"},{w:"alek",t:"なんや。食えるやん。",v:"07_0263"},{w:null,t:"アレク、自分のスープをすする。"},{w:"elly",t:"ねえ、あの型の主って、何を食べてたの？",v:"07_0266"},{w:"x",n:"女の人",t:"それがね、歯が一本も出てこないの。",v:"07_0267"},{w:"x",n:"女の人",t:"生きてるところ、一回でいいから見てみたいね。",v:"07_0268"}];
GR_SC.g07_08=[{w:null,t:"夜ふけ。みんな寝ている。ヤマトだけ、目をあけている。"},{w:null,t:"ヤマト、シートから出る。"},{w:null,t:"ヤマト、フォルンの背中の前の床に置く。"},{w:null,t:"フォルン、目をあけない。"},{w:null,t:"ヤマト、小屋の戸をそっとあける。"},{w:null,t:"月の光。小屋のわきの地面が、こんもり盛り上がっている。"},{w:null,t:"ヤマト、少しはなれた所に、ひざを抱えて座る。"},{w:null,t:"じっと見ている。"},{w:null,t:"小屋の戸が、うしろで静かにあく。"},{w:"dimi",f:"serious",t:"……まだ見てんのか。",v:"07_0282"},{w:null,t:"ヤマトの背中は動かない。目は、バジリクのまぶたのまま。"},{w:null,t:"レン、ヤマトの見ている先を、一度だけ見る。"},{w:"dimi",t:"あしたの朝、先に出る。",v:"07_0285"},{w:"dimi",t:"大会で待ってる。",v:"07_0286"},{w:null,t:"ヤマト、ふり向かない。ばんそうこうの指で、足もとの赤土に、閉じた目を一つ描く。"},{w:null,t:"消して、もう一回描く。"},{w:null,t:"レン、それを見て、何も言わずに小屋へもどる。"},{w:null,t:"小屋の角の暗がり。"},{w:null,t:"フォルン、ヤマトの方を、一回だけ見る。"},{w:null,t:"月が、小屋の屋根の向こうへ動いていく。"}];
GR_BT[7]={mid:[[{w:null,t:"夕方。子どもたちが帰ったあとの発掘場。",v:"07_0161"},{w:null,t:"レン、骨の型の横の、区画のロープの外まで下がって立つ。"},{w:null,t:"ヤマト、息をのむ。"},{w:null,t:"レンの手首の画面。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"おい、レベル32や。やばいで。",v:"07_0171"},{w:"hero",f:"surprised",t:"32！？　……だったら、三体で囲んでやろうぜ。",v:"07_0173"},{w:"dimi",t:"三体まとめてでいい。",v:"07_0174"}],[{w:"hero",t:"あとで、三対一はずるいとか言うなよ！",v:"07_0176"},{w:"dimi",t:"言わない。いつでも来い。",v:"07_0178"},{w:"elly",t:"ピリポン、いける？",v:"07_0179"},{w:null,t:"ヤマトとエリー、左の手首の画面をかざす。"},{w:"x",n:"二人",t:"進化！",v:"07_0183"},{w:"hero",t:"バラバラに行け！　ピリムサは前でひきつけろ！",v:"07_0186"}],[{w:"alek",t:"クロッコ、右から回れ！",v:"07_0187"},{w:"dimi",t:"それ、効かない。",v:"07_0192"},{w:"dimi",t:"バジリク、もぐれ。",v:"07_0193"},{w:"hero",t:"穴のまわり、かこめ！",v:"07_0196"},{w:null,t:"ヤマトの目だけが、それを見ている。"},{w:"dimi",t:"魔眼封石（まがんロック）。",v:"07_0206"}]],post:[{w:null,t:"小さなクロッコは、灰色になったその場で、ころりと横に倒れて目を回す。"},{w:"elly",t:"ピリムサ！",v:"07_0210"},{w:"alek",t:"クロッコ！",v:"07_0211"},{w:"hero",t:"なんだ、今の……！",v:"07_0212"},{w:null,t:"光の輪は、顔を伏せたフォルコンの背中の毛の上を、すべって消える。"},{w:null,t:"フォルコン、顔を伏せたまま、低い所から炎を吐く。"},{w:null,t:"バジリクの前足の鱗に、小さな黒い焦げあとが一つ。"},{w:null,t:"レンの目が、下を向いたままのフォルコンに止まる。"},{w:"hero",t:"フォルコン、よけろ！",v:"07_0218"},{w:"dimi",t:"終わり。",v:"07_0222"}]};
GR_EP[7]={"t": "発掘場", "sc": [["g07_01", "発掘場の小屋（6日目の夜ふけ）", 0], ["g07_02", "発掘場（7日目の朝）", 0], ["g07_03", "発掘場・体験の場所（昼前）", 0], ["g07_04", "型の前（昼）", 0], ["g07_05", "発掘場（夕方）　勝負", 1], ["g07_06", "勝負のあと（夕方）", 0], ["g07_07", "小屋の中（夜）", 0], ["g07_08", "小屋の外（夜ふけ）", 0]]};
GR_SC.g08_01=[{w:null,t:"森の道が開いた朝。三人は、海ぞいの道を港へ向かった。",v:"08_0026"},{w:null,t:"海ぞいの白い道。"},{w:null,t:"ヤマトの右手の指に、ばんそうこう。"},{w:null,t:"ヤマト、ふり返る。"},{w:"hero",f:"serious",t:"……なんで、あんなうしろなんだよ。",v:"08_0030"},{w:"alek",t:"きのう、お前のことかんだからやろ。",v:"08_0031"},{w:null,t:"エリー、道ばたの古い石の道しるべの前で、ぴたりと止まる。"},{w:"elly",t:"あっ、ここだ！",v:"08_0033"},{w:"elly",t:"ねえ、ちょっとだけ寄り道していい？",v:"08_0034"},{w:"hero",t:"寄り道って、どこにだよ。",v:"08_0035"},{w:null,t:"エリーの指の先。"},{w:"elly",t:"ぶどう小屋！　毎年、遊びに来てるの。",v:"08_0037"},{w:"alek",t:"港まで、まだ二日かかるんやで。",v:"08_0038"},{w:null,t:"エリーは聞いていない。"},{w:"hero",t:"しょうがねえな。行くぞ、アレク！",v:"08_0040"},{w:"alek",t:"なんでお前が仕切るんや。",v:"08_0041"},{w:null,t:"第8話　エリーのぶどう小屋",v:"08_0043"}];
GR_SC.g08_02=[{w:null,t:"村のはずれ。"},{w:null,t:"棚の下を、収穫のロボットが一台、ゆっくり歩いている。"},{w:null,t:"となりの段は、観光の農園。"},{w:null,t:"棚のはしの、鳥よけの細い網。"},{w:null,t:"【プロフィール】ピーグル／風／●○○／茶色い小さなタカの子"},{w:null,t:"ヤマト、すぐに網へ手をのばす。"},{w:null,t:"ピーグル、羽を逆立てて、キイッと鳴く。"},{w:"elly",t:"ヤマト、ストップ。",v:"08_0057"},{w:null,t:"エリー、ヤマトの手をそっと下ろさせる。"},{w:null,t:"エリー、ゆっくりまばたきする。両手を、ひざの上で開いて見せる。"},{w:null,t:"ピーグルのばたつきが、止まる。首をかしげて、エリーの指先を見る。"},{w:"elly",t:"こわかったね。今、ほどくからね。",v:"08_0061"},{w:null,t:"エリー、網の目を、一つずつ指でゆるめていく。"},{w:null,t:"網から出たピーグル、エリーの腕を伝って、肩までかけ上がる。"},{w:null,t:"エリー、カバンから小さな薬の筒と、すきとおった貼りものを出す。"},{w:null,t:"ピーグル、エリーの耳のうしろに顔をうずめる。"},{w:null,t:"エリーの髪の中から、ピリポンが顔を出す。"},{w:"elly",t:"ピリポン、やきもちやかないの。",v:"08_0067"},{w:"hero",t:"なんでエリーには、すぐ寄ってくんだよ。",v:"08_0068"},{w:"elly",t:"ヤマトは、すぐ手が出るもん。",v:"08_0069"},{w:null,t:"ヤマト、五歩うしろのフォルンを見る。"}];
GR_SC.g08_03=[{w:null,t:"棚の高い所に、ロボットの手が届かなかった房が、ぽつぽつ残っている。"},{w:null,t:"アレクのカゴは、まだ底が見えている。"},{w:null,t:"小屋の戸口。"},{w:null,t:"となりの段から、ぶどう畑のおじさんとおばさんが、からのカゴを持って下りてくる（2100年の作業着）。"},{w:"x",n:"おじさん",t:"おう、エリー。今年も来たか。",v:"08_0077"},{w:"elly",t:"来たよ！　この二人、旅の仲間なの。",v:"08_0078"},{w:"hero",t:"なあ、戸の上の石、なんて書いてあんの？",v:"08_0079"},{w:"x",n:"おじさん",t:"だれも読めねえんだ。昔の字でな。",v:"08_0080"},{w:"x",n:"おばさん",t:"村の勇者さまが、化け物を追いはらった石だよ。",v:"08_0081"},{w:"hero",t:"化け物!?　どんなやつ？",v:"08_0082"},{w:"x",n:"おばさん",t:"それがね、だれも字が読めないから。",v:"08_0083"},{w:null,t:"エリー、つま先立ちになる。"},{w:null,t:"苔の下から、字のとなりの彫り物が出てくる。"},{w:"elly",f:"surprised",t:"えっとね……「大きなけものが、ぶどうを食べに来る」。",v:"08_0087"},{w:"elly",t:"「半分あげれば、戸はこわされない」。",v:"08_0088"},{w:"hero",f:"serious",t:"……それだけ？",v:"08_0090"},{w:"elly",t:"うん。あと、「今年は、あげすぎた」だって。",v:"08_0091"},{w:null,t:"おじさんとおばさん、口をあけたまま、顔を見合わせる。"},{w:"x",n:"おじさん",t:"……勇者さまは？",v:"08_0093"},{w:"elly",t:"どこにも出てこないよ。",v:"08_0094"},{w:"x",n:"おばさん",t:"毎年、あの石に頭下げてたのに……。",v:"08_0095"},{w:"alek",t:"ぶどうの分け方のメモやん。",v:"08_0096"},{w:null,t:"おじさん、カゴを落とす。"},{w:null,t:"坂の上から、村の人が一人、二人と下りてきて、石の前に集まる。"},{w:null,t:"アレク、踏み場のわきの、苔だらけの別の古い石の前にしゃがむ。"},{w:"alek",t:"……『この下に、我が金塊、眠れたし』。",v:"08_0100"},{w:"hero",f:"serious",t:"……お前、読めねえだろ。",v:"08_0101"},{w:"hero",t:"フォルン、ずっとあそこから来ねえんだけど。",v:"08_0104"},{w:"elly",t:"手を出さないで、待つの。さっきの子もそう。",v:"08_0105"},{w:"hero",f:"smile",t:"じっと、な。……よし。",v:"08_0106"},{w:"elly",t:"ヤマトも踏む？　気持ちいいよ！",v:"08_0108"},{w:"hero",t:"踏まねえ。今、練習中だから。",v:"08_0109"},{w:null,t:"ヤマト、石段で、ひざに手を置いて、じっと座っている。"},{w:null,t:"エリーの足の下で、ぶどうがぶちゅっとつぶれる。紫の汁が槽のふちから飛んで、ヤマトの顔にかかる。"},{w:"hero",t:"うわっ、つめてっ！",v:"08_0112"},{w:null,t:"ヤマト、跳び上がる。"},{w:"elly",t:"ごめーん！",v:"08_0114"},{w:null,t:"アレク、カゴを置いて、ヤマトのとなりに座る。房を一つ、ヤマトの口の前に出す。"},{w:"alek",t:"食うか？",v:"08_0117"},{w:null,t:"ヤマト、目をつむったまま、首を横にふる。"},{w:null,t:"アレク、ヤマトの口の前で、一粒ずつ自分で食べていく。"},{w:null,t:"フォルンが、日なたから歩いてくる。"},{w:"hero",t:"（目をつむったまま）……アレク、それ、わざとだろ。",v:"08_0121"},{w:"alek",t:"何がや。",v:"08_0122"},{w:null,t:"ヤマト、目をあけて、アレクの口に房ごと押しこむ。"},{w:"alek",t:"（口いっぱいで）……何すんねん。",v:"08_0124"},{w:null,t:"フォルン、ヤマトの足をまたいで、そのまま小屋のかげへ行ってしまう。"},{w:"elly",f:"serious",t:"……今の、すっごく惜しかったよ。",v:"08_0126"},{w:"hero",f:"serious",t:"……知ってる。",v:"08_0127"}];
GR_SC.g08_05=[{w:null,t:"森のふち。ベルクマが、木の根もとで止まって、ふり返る。口のまわりの紫を、前足でこすっている。"},{w:null,t:"エリー、棚のあいだを上がっていく。"},{w:"alek",t:"おい、エリー！",v:"08_0201"},{w:"elly",t:"だいじょうぶ。もう、おなかいっぱいの顔してるもん。",v:"08_0202"},{w:null,t:"エリー、低い声で、うなるまねをする。"},{w:null,t:"ベルクマ、首をかしげる。"},{w:"elly",t:"来年は、半分こね！",v:"08_0205"},{w:null,t:"ベルクマ、のそのそ向きを変えて、森の中へ消える。"},{w:null,t:"エリーの肩に、ピーグルが跳び下りてくる。"},{w:null,t:"小屋の前。フォルン、日なたのあとの温かい石の上で、丸くなっている。"}];
GR_SC.g08_06=[{w:null,t:"夜。小屋の前の石段。"},{w:null,t:"エリー、石段のいちばん上で、手首の画面にふれる。空中に、アナの声の波の形だけが出る（声だけの電話・顔は映さない）。"},{w:"elly",t:"お姉ちゃん、今年も来たよ。ぶどう小屋！",v:"08_0213"},{w:"alek",t:"（槽のふちから、小声で）……おれのことも、言うといて。",v:"08_0214"},{w:null,t:"エリーは聞いていない。画面に向かって、手をふっている。"},{w:"ana",t:"旅の途中で寄ったの？　クマの子、今年も来た？",v:"08_0216"},{w:"elly",t:"来た！　ぶどう、半分こしようねって言った。",v:"08_0217"},{w:"ana",t:"去年、戸をこわした子と？",v:"08_0218"},{w:"elly",t:"うん。今年は、ちゃんと話せたよ。",v:"08_0219"},{w:"ana",t:"……また、そんなことして。",v:"08_0220"},{w:null,t:"エリー、笑って、画面を切る。"},{w:null,t:"石段の下の段に、ヤマト。顔の紫のしみが、まだうすく残っている。"},{w:null,t:"棚の網のそばで、ピーグルが羽を広げる。"},{w:"hero",t:"エリー、なんであんな昔の字、読めんだよ。",v:"08_0224"},{w:"elly",t:"おばあちゃんの村の言葉が、昔の字とほとんど同じなの。",v:"08_0225"},{w:"alek",t:"読めて、どうするんや。",v:"08_0226"},{w:"elly",t:"世界には、入っちゃいけない古代の遺跡がたくさんあるの。",v:"08_0227"},{w:"elly",t:"それを見て回って、本当の古代の歴史を知りたいんだあ。",v:"08_0228"},{w:"alek",t:"入ったらあかんのやろ。",v:"08_0229"},{w:"elly",t:"だから、見たいんだよ！",v:"08_0230"},{w:"hero",t:"遺跡って、石しかねえじゃん。",v:"08_0231"},{w:null,t:"エリーの髪の中から、ピリポンが顔だけ出す。"},{w:null,t:"ヤマトの前髪の先が、ちりっと焦げる。ヤマト、煙をひとすじ吐いて、だまる。"},{w:null,t:"ピーグル、棚の上から、ふわっと夜の空へ飛び立つ。"},{w:null,t:"エリー、立ち上がって、両手を大きくふる。"},{w:"elly",t:"またねー！",v:"08_0236"},{w:null,t:"アレク、望遠鏡を、また空に向ける。"},{w:"hero",t:"アレクは？　なんで旅してんだよ。",v:"08_0238"},{w:"alek",t:"金ためて、ロケットであれに行くねん。",v:"08_0239"},{w:null,t:"アレクの望遠鏡の先。"},{w:"hero",t:"火星!?　一人で？",v:"08_0241"},{w:"alek",t:"一人ちゃう。",v:"08_0242"},{w:null,t:"アレク、足の先で、寝ているクロッコをちょんとつつく。"},{w:null,t:"クロッコ、寝たまま、しっぽを一回ふる。"},{w:null,t:"ヤマト、石段にあおむけにねころがる。"},{w:null,t:"フォルン、ヤマトのひざに前足をかける。"},{w:null,t:"ヤマトの体が、固まる。"},{w:null,t:"エリーが、両手で口をおさえる。"},{w:null,t:"ヤマトの右手が、そっとフォルンの背中へのびる。"},{w:null,t:"ぺしっ。しっぽが、その手をはたく。"}];
GR_SC.g08_07=[{w:null,t:"明かりを落とした広い部屋。"},{w:null,t:"窓のそばに、すその長い黒いコートの女。"},{w:null,t:"【字幕】「カシア」。"},{w:null,t:"画面に、空から撮った写真。"},{w:null,t:"カシア、写真を指で広げる。"},{w:null,t:"カシアの指が、そこで止まる。"},{w:null,t:"カシア、画面を閉じる。窓に、カシアの顔だけがうっすら映る。"}];
GR_BT[8]={mid:[[{w:"elly",t:"あっ、またあの子だ。",v:"08_0136"},{w:"alek",t:"また？",v:"08_0137"},{w:"elly",t:"毎年、残りのぶどうを食べに来るの。",v:"08_0138"},{w:"elly",t:"去年は、小屋の戸をこわされちゃった。",v:"08_0139"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:null,t:"ヤマト、もう石段から立っている。"},{w:"hero",t:"フォルン、追っぱらうぞ！",v:"08_0144"},{w:null,t:"ヤマト、手首の画面をかざす。"}],[{w:"hero",t:"フォルン、進化！",v:"08_0148"},{w:"hero",t:"フォルコン、火、ふけ！",v:"08_0152"},{w:"alek",t:"待て待て待て！",v:"08_0154"},{w:null,t:"ヤマト、口の前で、手が止まる。"},{w:"elly",t:"待って！　撃たないで！",v:"08_0164"},{w:null,t:"エリーの目が、戸の上の古い石へ。それから、足もとのカゴへ。"},{w:null,t:"エリー、戸の上の石を、だまって指さす。"},{w:null,t:"ヤマト、石を見る。"},{w:null,t:"ヤマト、カゴのぶどうを両手ですくって、半分を、からのカゴにうつす。"},{w:"elly",t:"こっちは、わたしたちの分。",v:"08_0179"}],[{w:"alek",t:"……ほんまに、メモどおりやん。",v:"08_0183"},{w:null,t:"エリー、返事のかわりに、戸の上の古い石の字を指でなぞる。"},{w:null,t:"ヤマト、立てていた手のひらを、ゆっくり下ろす。"},{w:null,t:"ヤマト、その場にしゃがむ。"},{w:null,t:"ヤマト、手をのばしかけて、ひざの上でにぎる。"},{w:"elly",t:"（小声で）……来たね。",v:"08_0189"},{w:"hero",t:"（フォルンを見たまま）……しゃべんな。",v:"08_0190"},{w:"alek",t:"（ぶどうを口に入れながら）お前が手ぇ出さへんの、初めて見たわ。",v:"08_0191"},{w:"hero",f:"serious",t:"……練習中なんだよ。",v:"08_0192"},{w:"elly",t:"（小声で）……アレクも、しゃべんないで。",v:"08_0193"}]],post:[{w:null,t:"アレク、口を閉じる。"},{w:null,t:"棚から、ぶどうが一粒落ちる。"},{w:null,t:"フォルン、立ち上がる。"}]};
GR_EP[8]={"t": "エリーのぶどう小屋", "sc": [["g08_01", "海ぞいの道（8日目の朝）", 0], ["g08_02", "ぶどう小屋（昼すぎ）", 0], ["g08_03", "ぶどう棚と踏み場（昼すぎ〜夕方）", 0], ["g08_04", "ぶどう棚（夕方）　勝負", 1], ["g08_05", "森のふち（夕方）", 0], ["g08_06", "ぶどう小屋の前（夜）", 0], ["g08_07", "白い都・高い窓の部屋（同じ夜）", 0]]};
GR_SC.g09_01=[{w:null,t:"ぶどう小屋を出て、二日目の朝。港町ナフリアに着いた。",v:"09_0026"},{w:null,t:"朝の港。白い家が坂にびっしり並んでいる。"},{w:null,t:"海から、箱を下げたドローンが何機も飛んでくる。"},{w:null,t:"ヤマトのすぐうしろを、フォルンが歩いている。"},{w:null,t:"エリー、青に白い水玉のロングワンピース。"},{w:null,t:"髪はおろして、ゆるいウェーブ。"},{w:"elly",t:"連絡船の乗り場って、どっち？",v:"09_0032"},{w:"hero",t:"まかせとけ！　こっちだ！",v:"09_0033"},{w:null,t:"ヤマト、胸を張って先頭を歩く。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"お前、全然違うやんけ！",v:"09_0039"},{w:null,t:"坂の途中で、ヤマトが止まる。だまって回れ右して、下りてくる。"},{w:null,t:"フォルンが、ヤマトを追いこして先に立つ。"},{w:"alek",t:"無人の船は、登録見るで。……一応、試すか。",v:"09_0042"},{w:null,t:"白い大きな無人の連絡船の乗り場。"},{w:null,t:"ヤマト、フォルンを板の前へ押し出そうとする。"},{w:"hero",f:"serious",t:"……ここまで歩いてきたのに？",v:"09_0048"},{w:"elly",t:"じゃあ、どうやって白い都まで行くの？",v:"09_0049"},{w:"alek",t:"港には、名前を聞かへん船もおるで。",v:"09_0050"},{w:"hero",t:"アレク、前見て歩けよ。",v:"09_0053"},{w:"alek",t:"客を乗せる船を探してるんやから、話しかけんなや——",v:"09_0054"},{w:null,t:"第9話　海を渡る",v:"09_0060"}];
GR_SC.g09_02=[{w:null,t:"アレクの望遠鏡が、桟橋の板の上に転がっている。"},{w:null,t:"クロッコ、桟橋から海へ跳びこむ。アレクのパーカーのえりに、口を大きく開けて、くわえに行く。"},{w:null,t:"もう一回。つるっ。"},{w:"elly",t:"クロッコ、がんばって！　もうちょっとだよ！",v:"09_0069"},{w:null,t:"そこへ、小さな舟がすうっと寄ってくる。"},{w:null,t:"【字幕】「マリナ」。"},{w:null,t:"マリナ、鉤をのばして、アレクのパーカーのフードに引っかける。"},{w:null,t:"アレク、舟の底にあおむけ。"},{w:null,t:"クロッコも、舟のへりにあごをかけて、よじ登ってくる。"},{w:null,t:"桟橋の上で、ヤマトが腹をかかえて笑っている。"},{w:null,t:"ヤマトの足もとのフォルンが、跳び上がって、しっぽでヤマトの顔をぱしっとたたく。"},{w:null,t:"ヤマト、桟橋のへりから身を乗り出す。目は、舟のうしろの青黒い背中。"},{w:"marina",t:"よそ見して歩くやつが、毎朝一人は落ちるんだよ。",v:"09_0078"},{w:null,t:"アレク、舟の底で起き上がる。"},{w:"alek",t:"……どうも。助かりました。",v:"09_0080"},{w:null,t:"アレク、ぬれた前髪を指でととのえる。"},{w:"alek",t:"（一段低い声で）……実は僕、クルーザー持ってまして。",v:"09_0082"},{w:"alek",t:"（一段低い声で）……今度、クルージングしません？",v:"09_0083"},{w:null,t:"マリナ、もう舟のロープを巻いている。"},{w:null,t:"アレク、背すじをのばしたまま、しずくをたらして待つ。クロッコは知らん顔。"},{w:"alek",t:"引き上げてもろたの、タダっすよね。",v:"09_0086"},{w:"marina",t:"船代に乗せとくよ。",v:"09_0087"},{w:null,t:"クロッコ、すわったアレクの胸に、ずぶぬれのままよじ登る。"},{w:"alek",t:"かむ力もないくせに、跳びこむなや。",v:"09_0089"},{w:null,t:"アレク、クロッコの頭に、ぬれた手をのせる。"},{w:null,t:"マリナ、舟を桟橋につける。"},{w:null,t:"エリー、拾った望遠鏡を、アレクの胸に置く。"},{w:"elly",t:"お姉さん、白い都まで船、出してる？",v:"09_0093"},{w:"marina",t:"出してるよ。沖の細長いのが、うちの客船。",v:"09_0094"},{w:"alek",t:"三人と、三体。……なんぼですか。",v:"09_0095"},{w:null,t:"マリナ、手首の画面に数字を出して見せる。"},{w:"alek",t:"……足りへんっす。",v:"09_0097"},{w:"hero",t:"じゃあさ、あと払いにしてくれよ！",v:"09_0099"},{w:"hero",t:"白い都の大会の賞金が入ったら、ちゃんと払うから。",v:"09_0100"},{w:"marina",t:"大会に出るの？　その狐で？",v:"09_0101"},{w:"hero",f:"serious",t:"……出るよ。勝つし。",v:"09_0104"},{w:"marina",t:"賞金なんて、勝ってみないと分かんないでしょ。",v:"09_0105"},{w:"alek",t:"負けたら、荷下ろし三日でどうっすか。",v:"09_0106"},{w:"marina",t:"……夕方出る。乗りな。",v:"09_0108"},{w:"elly",f:"smile",t:"ほんとに!?　やった！",v:"09_0109"}];
GR_SC.g09_03=[{w:null,t:"その夕方。三人は、マリナの客船に乗った。",v:"09_0112"},{w:null,t:"夕方の港。マリナの客船。"},{w:null,t:"客は少ない。"},{w:null,t:"マリナ、操縦の台で手首の画面にふれる。"},{w:null,t:"アレク、船室の壁ぎわに、背中をぴったりつけて座っている。"},{w:"hero",t:"（にやにや）海、きれいだぞ。落ちても拾ってもらえるし。",v:"09_0117"},{w:"alek",t:"行かへん。",v:"09_0118"},{w:null,t:"日がしずんだ海。"},{w:null,t:"エリー、男の子の横にしゃがんでいる。"},{w:"elly",t:"ねえ、この子かわいくない？　きみが育ててるの？",v:"09_0121"},{w:"x",n:"男の子",t:"うん。ぼくが卵からかえしたんだよ。",v:"09_0122"},{w:"x",n:"おじいさん",t:"白い都に着いたら、すぐ登録しような。",v:"09_0123"},{w:"elly",t:"それまで、しっかり抱っこしとこうね。",v:"09_0124"},{w:null,t:"エリー、船べりで、自分の手首の画面にふれる。空中に、アナの声の波の形だけが出る（声だけの電話・顔は映さない）。"},{w:"elly",t:"お姉ちゃん！　今、船の上だよ！",v:"09_0126"},{w:"ana",t:"エリー、ちゃんと食べた？",v:"09_0127"},{w:"elly",t:"食べたよ！　さっき、あったかいパンもらったの。",v:"09_0128"},{w:"ana",t:"よかった。夜は冷えるから、気をつけてね。",v:"09_0129"},{w:null,t:"壁ぎわのアレク、アナの声に、背すじだけ、ぴんとのびる。"},{w:null,t:"エリー、笑って手をふって、画面を切る。"},{w:null,t:"エリー、ポケットから、はちみつのあめの、すきとおった包みを出す。"},{w:null,t:"光るお菓子帳に当てる。"},{w:null,t:"甲板のはし。フォルンが、波しぶきを一つ、しっぽの先にもらう。"},{w:null,t:"フォルン、そこで丸くなる。"},{w:"hero",t:"フォルン、そこ、客の荷物の上だぞ。",v:"09_0136"},{w:"hero",f:"serious",t:"……荷物、焦がすなよ。",v:"09_0138"}];
GR_SC.g09_04=[{w:null,t:"月のない海。"},{w:null,t:"甲板に、テリオンが二体。"},{w:null,t:"【プロフィール】アロガルド／森／●●○／とげの葉をまとう緑の獣"},{w:null,t:"黒い船の甲板のすみ。"},{w:null,t:"アロガルドとソヨモモは、そちらを一度も見ない。"},{w:null,t:"そのうしろに、大柄な男。"},{w:null,t:"【字幕】「ゼノ」。"},{w:null,t:"ゼノの足もとで、水の子が一体、大きなあくびをする。"},{w:null,t:"【プロフィール】ラッコン／水／●●○／いつも眠そうなラッコ"},{w:null,t:"ゼノの手首の画面。"},{w:"zeno",t:"あの船に寄せろ。明かりはつけるな。",v:"09_0151"},{w:"marina",t:"……ゼノの船だ。",v:"09_0155"},{w:"alek",t:"（小声で）……目ぇ合わすな。",v:"09_0156"},{w:"marina",t:"みんな、船室に入って！　戸から顔を出さないで！",v:"09_0159"},{w:"zeno",t:"狐と、登録のない子は全部もらっていく。",v:"09_0164"},{w:"hero",t:"フォルンは渡さねえぞ！",v:"09_0166"},{w:"elly",t:"船室の子たちにも、さわらせないからね！",v:"09_0169"},{w:"zeno",t:"坊主。その狐は、だれの相棒でもない。",v:"09_0170"},{w:"hero",f:"surprised",t:"おれの相棒だ！　どこにも行かねえ！",v:"09_0171"},{w:"x",n:"二人",t:"進化！",v:"09_0178"}];
GR_SC.g09_06=[{w:null,t:"三体の光が引き、もとの姿へ。"},{w:"hero",f:"smile",t:"……すっげー。クロベク、かっけえ。",v:"09_0260"},{w:"alek",t:"当たり前や。こいつ、やればできんねん。",v:"09_0261"},{w:"alek",t:"船代、これで上がらへんやろな。",v:"09_0262"},{w:"elly",t:"（戸口から）上がらないよ。お客さんの子、守ったもん。",v:"09_0263"},{w:null,t:"ヤマトとアレク、同時に、クロベクが伏せていた板を指さす。"},{w:"hero",f:"serious",t:"……あれ、おれが先に気づいたんだぞ。",v:"09_0265"},{w:"alek",t:"おれが先に使うた。",v:"09_0266"},{w:null,t:"アレク、ヤマトへあごをしゃくる。"},{w:"alek",t:"……伏せたら、ほんまに見いひんのやな。",v:"09_0268"},{w:null,t:"甲板のフォルン、耳だけこっちへ向けて、しっぽで甲板を一回ぱたり。"},{w:"hero",t:"お前、さっき、へりの方に出てたな。",v:"09_0270"},{w:"alek",t:"……出てへん。",v:"09_0271"},{w:null,t:"アレク、クロッコを抱いたまま、壁に背中をぴったりつけ直す。"},{w:null,t:"ヤマト、立ち上がって、フォルンの方へ行く。"},{w:null,t:"フォルンは甲板に座りこんだまま、ヤマトの方を見ずに前足をなめる。"},{w:null,t:"ヤマト、フォルンの前にしゃがむ。右手をのばしかけて、ばんそうこうの指を見て、止める。"},{w:null,t:"ヤマト、手を引っこめて、となりに座る。"},{w:null,t:"木箱の山のかげから、鳥の子がよちよち出てくる。"},{w:null,t:"エリー、男の子のうしろにしゃがんで、肩を抱く。男の子の手が、エリーの左のそでをつかむ。"},{w:"x",n:"男の子",t:"お姉ちゃん、ひじ……。",v:"09_0279"},{w:"elly",t:"へーき、へーき。",v:"09_0280"},{w:null,t:"エリー、そでを下ろしてひじを隠し、男の子の頭をなでる。"},{w:"elly",f:"serious",t:"……ありがと。",v:"09_0283"}];
GR_SC.g09_07=[{w:null,t:"夜明け。小雨はやんでいる。"},{w:null,t:"近づくと、港の岸壁に、大きな大会の旗が何本もはためいている。"},{w:null,t:"客たちは船室の入口で眠っている。"},{w:null,t:"エリーも、男の子のとなりで、ひざを抱えて眠っている。"},{w:null,t:"アレクは、壁ぎわで、クロッコをひざにのせたまま眠っている。"},{w:null,t:"船べりに、ヤマト。"},{w:null,t:"ヤマト、旗を見て、にっと笑う。"},{w:null,t:"首に灰色のタオル。"},{w:null,t:"男、手首の画面にふれる。"},{w:null,t:"ゼノの指が、送り先の「本部」を押す。"}];
GR_BT[9]={mid:[[{w:null,t:"ゼノ、手首の画面に一度ふれるだけ。"},{w:"x",n:"男の子",t:"待って！",v:"09_0189"},{w:null,t:"エリー、戸口の前で男の子に飛びつき、抱えて戸口の中へ倒れこむ。"},{w:null,t:"エリー、すぐに笑って、そでを下ろしてひじを隠す。"},{w:"hero",t:"フォルコン、あの緑のでかいのに一発だけ！",v:"09_0194"},{w:"zeno",t:"ラッコン。まとめて返せ。",v:"09_0196"},{w:"hero",t:"フォルコン！",v:"09_0198"},{w:"elly",t:"（戸口から）ピリムサ！　そこから動かないで！",v:"09_0200"},{w:"alek",t:"クロッコ、水を吐け！",v:"09_0203"},{w:null,t:"アレク、壁から背中をはがす。"}],[{w:"alek",t:"クロッコ、上がってこい！",v:"09_0209"},{w:null,t:"アレク、左の手首の画面をかざす。"},{w:"alek",t:"クロッコ、進化！",v:"09_0214"},{w:"alek",t:"クロベク、それや！　かまんでええ、突け！",v:"09_0222"},{w:null,t:"ゼノ、手首の画面を見たまま、指を一本だけ動かす。"},{w:"zeno",t:"ラッコン、突き返せ。",v:"09_0224"},{w:null,t:"ヤマトの目が、アロガルドの目を追う。"},{w:null,t:"ヤマト、右手を上げる。"},{w:"hero",t:"フォルコン、フォックスファイヤー！",v:"09_0233"},{w:null,t:"アレク、目を回したアロガルドと、それを見もしないソヨモモを見くらべる。"},{w:null,t:"アレク、壁ぎわから、もう半歩、前へ出る。"},{w:"alek",t:"クロベク、伏せえ！",v:"09_0240"}]],post:[{w:null,t:"アロガルドのチップが、ぱきんと割れる。"},{w:null,t:"黒い船とは反対の海へ飛びこみ、白い都の方へ泳いで逃げていく。"},{w:null,t:"ゼノの手首の画面が光る。"},{w:"zeno",t:"……引き上げる。",v:"09_0251"}]};
GR_EP[9]={"t": "海を渡る", "sc": [["g09_01", "港町ナフリア（10日目の朝）", 0], ["g09_02", "桟橋とマリナの舟（朝）", 0], ["g09_03", "マリナの客船・甲板（10日目の夕方〜夜のはじめ）", 0], ["g09_04", "夜の海・黒い船（夜ふけ）", 0], ["g09_05", "甲板の勝負", 1], ["g09_06", "勝負のあと（夜ふけ）", 0], ["g09_07", "夜明けの海", 0]]};
GR_SC.g10_01=[{w:null,t:"夜の海をこえて、マリナの船は白い都の港に着いた。",v:"10_0026"},{w:null,t:"朝の港。白い石の古い倉庫が並ぶ岸壁。"},{w:null,t:"港のうしろの丘。"},{w:null,t:"マリナの船が岸壁につく。"},{w:null,t:"渡し板を下りる三人と三体。"},{w:null,t:"エリー、水色と白のジャージの上着。"},{w:null,t:"長いズボンに白いスニーカー。"},{w:null,t:"アレク、肩のヤマトの上着を、見もせずにヤマトの頭へ放る。"},{w:null,t:"ヤマト、上着を頭にのせたまま、岸壁を歩きだす。"},{w:"marina",t:"大会、がんばんなよ。",v:"10_0035"},{w:"marina",t:"きのうの夜のあれなら、いいとこまで行けるよ。",v:"10_0036"},{w:"hero",t:"いいとこじゃなくて、優勝するんだって。",v:"10_0037"},{w:"marina",t:"そう言う子から、先に負けて帰ってくるんだよ。",v:"10_0038"},{w:"marina",t:"船代、忘れんじゃないよ。",v:"10_0039"},{w:"alek",t:"……賞金から、払いますわ。",v:"10_0040"},{w:null,t:"マリナは、もう船にもどっている。"},{w:null,t:"ヤマト、港の沖を見る。"},{w:"hero",t:"あのヒゲのおっさん、また来ねえだろうな。",v:"10_0043"},{w:null,t:"エリーの髪の中で、ピリポンが小さくなっている。顔を出さない。"},{w:"elly",t:"もう来なくていいよ。ピリポン、まだ髪から出てこないもん。",v:"10_0045"},{w:"hero",t:"ピリポン、まだビビってんのか。……来たら、ぶっ倒す。",v:"10_0046"},{w:null,t:"アレク、港の出口の坂を見上げる。"},{w:"alek",t:"受付、朝のうちに閉まるで。しゃべってんと行くで。",v:"10_0048"},{w:null,t:"第10話　白い都の大会",v:"10_0050"}];
GR_SC.g10_02=[{w:null,t:"白い都。昔の石の町に、きょうは大会の屋台が並んでいる。",v:"10_0056"},{w:null,t:"白い石畳の坂道。"},{w:null,t:"串焼きの屋台では、ロボットの腕が肉を返している。"},{w:null,t:"世界じゅうから来た人とテリオン。"},{w:null,t:"エリー、歩きながら手首の画面を見る。"},{w:"elly",t:"今日のラッキースポットは、古い字のある所だって！",v:"10_0061"},{w:null,t:"ヤマトは串焼きの屋台を、アレクは値札を見ている。"},{w:"elly",f:"serious",t:"……聞いてないし。",v:"10_0063"},{w:null,t:"エリー、ふと横を向く。"},{w:null,t:"エリー、小さな屋台の前で止まる。"},{w:null,t:"台に「大会限定」の札。"},{w:"elly",t:"アレク、これ大会の時しか売ってないんだって！",v:"10_0067"},{w:"alek",t:"……で、なんぼや。",v:"10_0068"},{w:null,t:"空中の値札。アレク、すぐ目をそらす。"},{w:"alek",t:"人形は、勝ってからや。",v:"10_0070"},{w:"elly",f:"surprised",t:"ほんと！？　約束だよ。",v:"10_0071"},{w:"hero",f:"serious",t:"……お前のおごり？",v:"10_0075"},{w:"alek",t:"賞金から引くで。",v:"10_0076"}];
GR_SC.g10_03=[{w:null,t:"坂の上がひらける。"},{w:null,t:"入口に、案内のロボットと、宙に浮かぶ受付の画面。"},{w:null,t:"入口のとなりに、白い石の小さな建物。"},{w:"x",n:"受付のロボット",t:"白い都テリオン大会へ、ようこそ。三体までの部ですね。",v:"10_0082"},{w:"x",n:"受付のロボット",t:"組の名前を、どうぞ。",v:"10_0083"},{w:"hero",t:"チーム・フォルンで！",v:"10_0084"},{w:"elly",t:"えー、ピリポンとクロッコも入れてよ。",v:"10_0085"},{w:null,t:"二人がもめているあいだに、アレクが受付の画面に指で打ちこんでいる。"},{w:"x",n:"受付のロボット",t:"「オリーヴァ村」で、受け付けました。",v:"10_0087"},{w:"elly",t:"（にこっ）オリーヴァ村、いいね！",v:"10_0088"},{w:"hero",f:"serious",t:"……勝手に決めんなよ。",v:"10_0089"},{w:"alek",t:"もめてたら、日ぃ暮れるで。",v:"10_0090"},{w:null,t:"アレク、カードを当てる。"},{w:null,t:"エリー、受け取った番号のバッジを、ジャージの上着に付ける。"},{w:null,t:"受付のロボットが、こちらの三体の首元に、順に光をかざす。"},{w:null,t:"フォルン、うしろ足で首をかく。"},{w:null,t:"ヤマト、画面の赤い字を見る。入口のとなりの白い窓口を、一回だけ見る。"},{w:"x",n:"受付のロボット",t:"開会式のあと、すぐに1回戦です。選手の入口へどうぞ。",v:"10_0096"}];
GR_SC.g10_04=[{w:null,t:"【ここから一つながりのカメラ】"},{w:null,t:"満員の客席。"},{w:null,t:"選手の入口に、三人と三体。"},{w:"x",n:"実況（場内の声）",t:"協賛の会社より、ごあいさつをいただきます。",v:"10_0103"},{w:null,t:"大きな画面に、協賛の会社の名前と印だけが出る。顔は映らない。"},{w:null,t:"カメラ、客席の上を貴賓席へ。"},{w:"victor",t:"みなさん、白い都へ、ようこそ。",v:"10_0106"},{w:"victor",t:"世界じゅうから、強い子が来てくれました。",v:"10_0107"},{w:null,t:"拍手。カメラ、客席を横に流れて、選手の入口のアレクへ。"},{w:null,t:"クロッコの頭をなでていたアレクの手が、止まる。"},{w:"victor",t:"どの子にも、いい試合を期待しています。",v:"10_0110"},{w:null,t:"アレクの目だけが、声の出どころの貴賓席へ上がる。"},{w:null,t:"アレク、パーカーのポケットから古い望遠鏡を出して、貴賓席に向ける。"},{w:"hero",t:"エリー、あそこ。船のヒゲのおっさんがいるぞ。",v:"10_0119"},{w:"elly",f:"surprised",t:"えっ、どこ？",v:"10_0120"},{w:"x",n:"実況（場内の声）",t:"開会式は、ここまで！　まもなく1回戦です！",v:"10_0121"},{w:"hero",t:"なんであいつが、偉い席にいんだよ！",v:"10_0123"},{w:"alek",t:"知らん。休み場、行くで。",v:"10_0124"}];
GR_SC.g10_05=[{w:null,t:"競技場の裏。"},{w:null,t:"エリーが、休み場の台から、選手に配る軽食の包みを三つもらってくる。"},{w:null,t:"ヤマトの方へ、砂の上を歩いてくる。"},{w:null,t:"ヤマトのうしろ、裏の門が、音もなく開く。"},{w:null,t:"エリーの足が止まる。笑顔は、そのまま。"},{w:null,t:"ヤマト、エリーの顔を見る。"},{w:null,t:"エリー、また、ふつうに歩いてくる。"},{w:"hero",f:"serious",t:"……エリー、今——",v:"10_0136"},{w:"elly",t:"はい、ヤマトの分！",v:"10_0137"},{w:null,t:"ヤマト、包みを受け取る。エリーの顔を見る。"},{w:null,t:"エリー、アレクの長いすに包みを置いて、飲み物を取りに台へ戻っていく。"},{w:null,t:"ヤマト、車寄せの方をもう一度見て、アレクに小さな声で。"},{w:"hero",t:"あれ、あの一味の車だろ。ヒゲのおっさんもいたし。",v:"10_0141"},{w:"alek",t:"……クロッコ、もうちょい水や。",v:"10_0142"},{w:null,t:"アレクは、クロッコに水をかける手もとから、目を上げない。"},{w:"x",n:"実況（場内の声）",t:"1回戦が始まります。オリーヴァ村の三人は、試合場へどうぞ。",v:"10_0144"}];
GR_SC.g10_07=[{w:null,t:"選手の通路。"},{w:null,t:"タリク、パオッコを両腕で抱き上げる。"},{w:null,t:"ヤマト、立ち止まる。"},{w:null,t:"ヤマト、出口の向こう、競技場の入口のとなりの白い窓口の方を、一回だけ見る。"},{w:null,t:"通路の出口。"},{w:"x",n:"子ども",t:"狐のお兄ちゃん、サインちょうだい！",v:"10_0271"},{w:"hero",t:"え、おれ？　……しょうがねえなあ。並べ並べ。",v:"10_0272"},{w:null,t:"ヤマト、子どもの画面に、指で大きくサインを書く。"},{w:"hero",t:"次も勝つから、ちゃんと見とけよ。",v:"10_0274"},{w:"x",n:"子ども",t:"狐にも、サインしてもらって！",v:"10_0275"},{w:null,t:"子どもが、画面をフォルンの鼻先に向ける。"},{w:"hero",t:"こいつ、そういうのやらねえんだよ。……足だけ貸してやるか。",v:"10_0277"},{w:null,t:"ヤマト、子どもの画面を、フォルンの前足の前に差し出す。"},{w:null,t:"フォルン、前足で、画面をぺしっとはらう。"},{w:null,t:"フォルン、そのままヤマトの顔に跳びつき、すすけた前足で、ほっぺを、ぎゅっとふんで、床へ跳び下りる。"},{w:"elly",t:"ヤマト、こっち向いて。……はい、撮れた。",v:"10_0284"},{w:"x",n:"ブラジルの二人",t:"融合！",v:"10_0288"},{w:"x",n:"実況（場内の声）",t:"二体が一つに！　ブラジルの組、融合です！",v:"10_0291"},{w:"hero",f:"smile",t:"……すっげー……！",v:"10_0297"},{w:"alek",t:"……おれも、初めて見たわ。",v:"10_0298"}];
GR_SC.g10_08=[{w:null,t:"競技場の下の、古い石の壁の控え室。"},{w:null,t:"三体は小さな姿にもどっている。"},{w:null,t:"しっぽの先に、灰色の象の毛が一本からまっている。"},{w:null,t:"とどく前に、しっぽで手をはたかれる。"},{w:"hero",t:"次、中国だって。あと二つで優勝だぜ！",v:"10_0307"},{w:"alek",t:"一個ずつや。次だけ見とけ。",v:"10_0308"},{w:null,t:"アレク、クロッコの背中を布でふく。"},{w:null,t:"アレク、ポケットから透明の貼りものを一枚出して、顔を上げないまま、エリーのひざの上に置く。"},{w:null,t:"エリー、目を丸くして、左のそでを押さえる。それから、ちょっと笑って、古い貼りものをはがす。"},{w:null,t:"控え室の戸口に、濃い灰色のスーツの男が立っている。"},{w:null,t:"男の目が、長いすのはしのフォルンに止まる。"},{w:null,t:"フォルン、顔を上げる。"},{w:null,t:"男、空中の対戦表の「オリーヴァ村」の字を、指で一回なぞる。笑顔のまま。"},{w:null,t:"男、胸に手を当てて、軽く一礼する。"},{w:null,t:"ヤマトとエリーが、顔を上げて戸口を見る。"},{w:null,t:"エリー、白いカバンのひもを、指に巻きつける。"},{w:"hero",t:"アレク、今のスーツのおっさん、だれ？",v:"10_0319"},{w:null,t:"アレクだけが、顔を上げない。"}];
GR_BT[10]={mid:[[{w:null,t:"タリクの目が、フォルンの首元に止まる。"},{w:"tarik",t:"その狐も、登録なしか。",v:"10_0162"},{w:"hero",t:"そっちもだろ。",v:"10_0163"},{w:"tarik",t:"ああ。優勝すれば、登録できる。",v:"10_0164"},{w:"hero",f:"serious",t:"……こっちもだ。優勝は、ゆずらねえ。",v:"10_0165"},{w:"x",n:"審判",t:"始め！",v:"10_0166"},{w:null,t:"タリク、手首の画面をかざす。"}],[{w:"tarik",t:"進化！",v:"10_0169"},{w:null,t:"三人が、手首の画面をかざす。"},{w:"x",n:"三人",t:"進化！",v:"10_0176"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"クロベク、水や。",v:"10_0184"},{w:null,t:"ヤマトの目が、砂の線をたどって、壁で止まる。"},{w:"hero",t:"フォルコン、穴から下がれ！　壁まで！",v:"10_0194"},{w:null,t:"ヤマトの目は、床じゅうの石のすき間を、順に追っている。"},{w:"hero",t:"フォルコン！",v:"10_0213"},{w:null,t:"ヤマト、くちびるをかむ。倒れたフォルコンから目をそらす。"}],[{w:"elly",t:"ピリムサ、あの穴の前に立って。わざと見えるように。",v:"10_0226"},{w:"alek",t:"クロベク、穴の横に回れ。正面やなくて、横や。",v:"10_0227"},{w:"tarik",t:"パオドン、ふりほどけ！",v:"10_0245"},{w:"elly",t:"ピリムサ、顔に、ぱちって！",v:"10_0247"},{w:"alek",t:"クロベク、決めろ！",v:"10_0249"},{w:null,t:"アレク、ヤマトの横に並んで、背中を手の甲でたたく。"},{w:"alek",t:"穴、一つしかないもんな。",v:"10_0254"}]],post:[{w:null,t:"アルマド、倒れたパオドンの鼻先に、丸い体をくっつけて動かない。"},{w:null,t:"タリク、帽子を取って、審判に手を上げる。"},{w:null,t:"フォルコン、しっぽをはなして、床にあごをつける。"}]};
GR_EP[10]={"t": "白い都の大会", "sc": [["g10_01", "白い都の港（11日目の朝）", 0], ["g10_02", "屋台の町（朝）", 0], ["g10_03", "古い競技場の受付（朝）", 0], ["g10_04", "開会（一つながりのカメラ）", 0], ["g10_05", "競技場の裏の休み場（1回戦の前）", 0], ["g10_06", "1回戦", 1], ["g10_07", "選手の通路（1回戦のあと）", 0], ["g10_08", "控え室（1回戦のあと）", 0]]};
GR_SC.g11_01=[{w:null,t:"大会の二日目。三人は、アレクが見つけた一番安い宿で朝を迎えた。",v:"11_0025"},{w:null,t:"古い石の建物の上の階。"},{w:null,t:"ヤマト、寝棚の上であぐらをかいて、手首の画面を見ている。"},{w:"hero",t:"エリー、見ろよ。きのうの1回戦、ニュースになってる！",v:"11_0028"},{w:null,t:"空中の画面。"},{w:null,t:"窓のへりで、フォルンがしっぽの火でオリーブを焼いている。"},{w:null,t:"宿の台所のロボットが、いちばん安い朝ごはんの盆（パンと、はちみつのヨーグルト）を出す。"},{w:null,t:"アレクの盆にだけ、アレクが自分で買ったぶどうジュース。"},{w:"elly",t:"ニュースより、ご飯、先！",v:"11_0033"},{w:null,t:"ピリポンが、エリーのヨーグルトのふたを、はしからなめている。"},{w:null,t:"アレク、パンをかじりながら、自分の手首の画面で大会の対戦表を見ている。"},{w:"alek",t:"きょうの相手、中国の道場の子らしいで。",v:"11_0036"},{w:"alek",t:"ここまで、一体もやられてへんねん。",v:"11_0037"},{w:"hero",t:"じゃあ、おれたちが最初に倒してやろうぜ！",v:"11_0038"},{w:null,t:"ヤマト、寝棚から身を乗り出して、空中の画面をフォルンの鼻先へ向ける。"},{w:"hero",t:"見ろ、フォルン。お前、ニュースに出てるぞ！",v:"11_0040"},{w:null,t:"窓のへりのフォルン、オリーブから目を上げずに、そっぽを向く。"},{w:null,t:"しっぽの火だけが、ぼっと大きくなる。"},{w:"alek",t:"クロッコ、消してやれ。",v:"11_0043"},{w:null,t:"足もとのクロッコが、ヤマトの頭へ水をぴゅっ。"},{w:null,t:"しずくで、画面がカメラに切りかわる。"},{w:"alek",t:"（早口で）……貴様、おれのジュース飲んで、水で薄めたやろ！",v:"11_0050"},{w:"hero",t:"（口のはしが紫）……飲んでねえ。",v:"11_0051"},{w:"alek",t:"しばく！",v:"11_0052"},{w:"elly",t:"（ヨーグルトを食べながら）朝から元気ね。",v:"11_0054"},{w:null,t:"第11話　準決勝",v:"11_0056"}];
GR_SC.g11_02=[{w:null,t:"競技場の下の通路。"},{w:"elly",t:"ねえねえ、三人おそろい。オリーヴァ村の印！",v:"11_0063"},{w:null,t:"ヤマトもアレクも、受け取って、見もせずにポケットへ入れる。"},{w:"hero",t:"（画面を見たまま）……あとでな。",v:"11_0065"},{w:null,t:"エリー、自分の手首の腕輪だけ、ぴかっと光らせる。"},{w:null,t:"エリーが前を向いたすきに、アレク、ポケットの腕輪を手首にはめる。"},{w:null,t:"競技場の下の、石の壁の通路。"},{w:null,t:"すれちがいざま、カマコロがハオの肩からひょいと床に下りる。"},{w:null,t:"フォルンの毛が、ぶわっと逆立つ。"},{w:null,t:"カマコロ、かまを二本とも上げて、フォルンの顔の前で止まる。"},{w:"hero",t:"おい、フォルン！　まだ始まってないって！",v:"11_0072"},{w:"hao",t:"すみません。",v:"11_0074"},{w:"hao",t:"翻訳機、使ってないんですか。",v:"11_0082"},{w:"alek",t:"……お前、中国の言葉もいけるんか。",v:"11_0085"},{w:"elly",t:"フォルン、勝負の前から負けず嫌いだね。",v:"11_0089"},{w:"hero",t:"負けず嫌いなのは、向こうのかまきりの方だろ。",v:"11_0090"}];
GR_SC.g11_03=[{w:null,t:"競技場のまん中。"},{w:null,t:"ヤマトの足もとのフォルン、しっぽの火の先を、黒い石にのせる。"},{w:null,t:"フォルン、しっぽを白い石の方へよける。"},{w:null,t:"相手の陣の前。"},{w:null,t:"選手の入口から床に出たヤマト、だまって一枚石のそばにしゃがむ。"},{w:null,t:"ヤマト、一枚石の外のへりに、手のひらをつく。"},{w:null,t:"ホエマルの潮吹きが、ぽちゃっと低く落ちる。"},{w:null,t:"エリーの目が、一枚石の古い字の横の、彫り物で止まる。"},{w:null,t:"エリー、ヤマトの袖を引いて、そこを見せる。"},{w:null,t:"ヤマト、一枚石と、溝の中のホエマルを、一回ずつ見る。"},{w:null,t:"貴賓席。日よけの下で、濃い灰色のスーツの男が座っている。"},{w:"x",n:"実況（場内の声）",t:"選手は、陣へ戻ってください。",v:"11_0107"},{w:null,t:"ヤマト、立ち上がって、こちらの陣へ戻る。"},{w:null,t:"選手の入口で、アレクが一度だけ貴賓席を見上げる。すぐに目をそらして、クロッコを溝の近くへ下ろす。"},{w:"x",n:"実況（場内の声）",t:"準決勝、第一試合！　中国代表、ハオ選手の組！",v:"11_0110"},{w:"x",n:"実況（場内の声）",t:"対するは、オリーヴァ村の三人！",v:"11_0111"}];
GR_SC.g11_05=[{w:null,t:"エルレオンの光がほどけて、フォルンとピリポンの小さな姿に分かれてもどる。"},{w:null,t:"ハオ、倒れたホエマルを両手でかかえ上げて、溝の水にそっと浸けてやる。"},{w:null,t:"ヤマト、フォルンを両手で持ち上げようとする。"},{w:null,t:"手がとどく前に、フォルン、するっとよけて、ヤマトの足もとに座る。"},{w:null,t:"エリーのひざの上で、ピリポンが毛のしずくを放電で飛ばす。"},{w:"elly",t:"ヤマト、今の、すごかったね！",v:"11_0241"},{w:null,t:"エリー、ヤマトの頭をなでようと、手をのばす。"},{w:"hero",f:"serious",t:"……まあな。",v:"11_0243"},{w:null,t:"うしろから、アレクがヤマトの首に腕を回して、頭をぐしゃぐしゃにする。ヤマト、笑いながら、その腕をふりほどく。"},{w:null,t:"アレク、分かれたフォルンとピリポンを、一体ずつ指でさす。うんうんと、二回うなずく。"},{w:null,t:"ヤマト、自分の手首の画面を、もう一度見る。"},{w:null,t:"ハオの肩のカマコロと、ヤマトの足もとのフォルン。目が合う。"},{w:null,t:"ハオ、カマコロの頭を指でおさえて、ヤマトに礼をする。今度は、ヤマトの足もとではなく、顔を見て。"},{w:"hao",t:"竹の森に来たら、案内します。",v:"11_0249"},{w:"hero",t:"竹の森って、どこにあんの？",v:"11_0250"},{w:"hao",t:"中国の、ずっと山の方です。画面に送っておきます。",v:"11_0251"},{w:null,t:"ハオ、手首の画面を、ヤマトの画面にこつんと当てる。"},{w:null,t:"ハオ、反対側の入口へ歩いていく。"},{w:null,t:"ヤマトの手首の画面が、ぴろんと鳴る。"},{w:null,t:"貴賓席。日よけの下の席は、もう空いている。"}];
GR_SC.g11_06=[{w:null,t:"通路の壁の大きな空中の画面。"},{w:null,t:"相手の三体のうち、バジリクの方を見ていた二体から色が抜けて、灰色に止まる。顔をそむけていた一体だけは、色が抜けない。"},{w:null,t:"ヤマトの目が、画面の、色の抜けなかった一体に止まる（1カット・台詞なし）。"},{w:"x",n:"実況（場内の声）",t:"決勝は、あすの午後！",v:"11_0261"},{w:"x",n:"実況（場内の声）",t:"オリーヴァ村の三人　対　前回の優勝者、レン選手！",v:"11_0262"},{w:"x",n:"実況（場内の声）",t:"レン選手は、今年も一人と一体で勝ち上がってきました！",v:"11_0263"},{w:null,t:"画面に、決勝の組み合わせ。"},{w:null,t:"通路の向こうから、レンが一人で歩いてくる。"},{w:null,t:"ヤマト、立ち止まる。"},{w:null,t:"レン、ヤマトの横を通りすぎる。"},{w:null,t:"ヤマト、ふり向く。"},{w:null,t:"ヤマトのうしろに、アレクとエリー。"},{w:"alek",t:"（ヤマトの横に並んで）……決勝、あいつか。",v:"11_0270"},{w:"hero",f:"serious",t:"……今度は、勝つ。",v:"11_0271"},{w:null,t:"通路の先。レン、歩きながら手首の画面を開く。"},{w:null,t:"送った字は「あした、決勝」。"},{w:null,t:"レン、画面を閉じる。"}];
GR_BT[11]={mid:[[{w:null,t:"ハオ、拳を手のひらに当てて礼。"},{w:"hao",t:"もう、足が前に出てますよ。",v:"11_0122"},{w:null,t:"ヤマトのつま先が、陣の線から半分はみ出している。"},{w:"x",n:"審判",t:"始め！",v:"11_0125"},{w:null,t:"ハオ、両手を横に開いてから、手首の画面をかざす。"},{w:"hao",t:"進化。",v:"11_0128"},{w:"x",n:"三人",t:"進化！",v:"11_0129"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"hero",f:"serious",t:"……フォルコン、まだだ。",v:"11_0137"}],[{w:"alek",t:"クロベク、溝に入れ！",v:"11_0138"},{w:"hao",t:"カマケン、溝のワニを。",v:"11_0144"},{w:"hao",t:"カマケン、狐を。",v:"11_0154"},{w:null,t:"ヤマト、走ってくるカマケンを指さす。"},{w:"hero",t:"フォルコン、フォックスファイヤー！",v:"11_0160"},{w:null,t:"ハオ、手首の画面を静かにかざす。"},{w:"hao",t:"……ホエルン、進化。",v:"11_0172"}],[{w:"alek",t:"クロベク、ふちにつかまれ！",v:"11_0176"},{w:null,t:"エリー、ふらつくピリムサを見る。自分の左の手首を、胸の前に上げる。"},{w:"elly",t:"ヤマト、いっしょにやろう。",v:"11_0182"},{w:null,t:"ヤマトの目が、エリーの手首に行く。"},{w:"alek",t:"くっつけたら、やられる時は二体いっぺんやで。",v:"11_0184"},{w:null,t:"ヤマトの目が、フォルコンへもどる。"},{w:"hero",f:"serious",t:"……フォルコン、行け！",v:"11_0186"},{w:null,t:"ヤマト、こぶしを握ったまま、フォルコンを見る。"},{w:null,t:"ヤマト、息を一つはく。"},{w:"x",n:"二人",t:"融合！",v:"11_0196"}],[{w:"hero",t:"エルレオン！",v:"11_0202"},{w:null,t:"エリー、ヤマトを見て、一回うなずく。"},{w:null,t:"ヤマトの目が、溝のふちのホエリオスと、そのうしろの一枚石を、一回ずつ見る。"},{w:null,t:"ヤマト、ホエリオスを指さす。"},{w:"hero",t:"エルレオン、引っぱり上げろ！",v:"11_0210"},{w:null,t:"エリー、ピリムサの方の手首を、ぐっと手前に引く。"},{w:null,t:"ヤマトとエリー、手首を並べて上げる。"},{w:"hero",t:"エルレオン、エレキスパーク！",v:"11_0221"},{w:"elly",t:"うん！",v:"11_0222"},{w:null,t:"アレク、ヤマトの肩をこぶしで軽く押して、一枚石の上のホエリオスを指さす。"},{w:"alek",t:"……陸に上げたら、水出せへんのか。",v:"11_0227"},{w:"elly",t:"ね、引っぱったでしょ！",v:"11_0229"}]],post:[]};
GR_EP[11]={"t": "準決勝", "sc": [["g11_01", "安い宿（朝）", 0], ["g11_02", "競技場の選手の通路（昼前）", 0], ["g11_03", "古い石の床に、水の溝（昼）", 0], ["g11_04", "準決勝", 1], ["g11_05", "勝負のあと（床のはし）", 0], ["g11_06", "客席の下の通路（準決勝、第二試合のあと）", 0]]};
GR_SC.g12_01=[{w:null,t:"決勝の前の夜。",v:"12_0027"},{w:null,t:"宿の廊下の小さな窓辺。"},{w:"elly",t:"お姉ちゃん、あしたね、決勝なんだよ。",v:"12_0029"},{w:"ana",t:"決勝！？　村のみんなに言わなきゃ。ロビーの画面で流すからね。",v:"12_0030"},{w:"elly",t:"えー、やめてよ。はずかしいもん。",v:"12_0031"},{w:"ana",t:"そんなことより、ちゃんと食べた？",v:"12_0032"},{w:"elly",t:"食べたよ。アレクが、安い串のお店を見つけてくれたの。",v:"12_0033"},{w:"ana",t:"あの子、ほんとに安いとこ見つけるのがうまいね。",v:"12_0034"},{w:"elly",t:"うん。でも人形は、勝ってからだって。",v:"12_0035"},{w:null,t:"声の波形が、笑い声で大きくゆれる。"},{w:null,t:"部屋。明かりを落とした中。"},{w:null,t:"ヤマトだけ、寝棚の上に座っている。"},{w:null,t:"ヤマトの画面。閉じた目の絵。"},{w:null,t:"アレク、寝返りを打って、ヤマトの背中を見る。"},{w:"alek",t:"まだ起きてるんか。あしたは決勝やで、早く——",v:"12_0041"},{w:null,t:"アレク、体を起こして、ヤマトの画面をのぞく。閉じた目の絵が、何枚も。"},{w:null,t:"アレク、少しのあいだ、その絵を見ている。"},{w:"alek",t:"あした、寝坊すんなや。",v:"12_0044"},{w:null,t:"アレク、掛け物を頭までかぶる。"},{w:null,t:"窓のへりで丸くなっていたフォルンが、片目だけあけて、ヤマトの指の動きを見ている。"},{w:null,t:"第12話　決勝",v:"12_0048"}];
GR_SC.g12_02=[{w:null,t:"大会の三日目。決勝の客席は、上の方の席まで人でうまっていた。",v:"12_0054"},{w:null,t:"満員の客席。"},{w:null,t:"床の水の溝は、石のふたでふさがれている。"},{w:null,t:"貴賓席。日よけの下に、濃い灰色のスーツの男。"},{w:"x",n:"実況（場内の声）",t:"白い都テリオン大会、決勝！",v:"12_0059"},{w:"x",n:"実況（場内の声）",t:"前回の優勝者、レン選手！",v:"12_0060"},{w:null,t:"向こうの入口から、レンが一人で歩いてくる。"},{w:"dimi",f:"serious",t:"……バジリク。",v:"12_0062"},{w:null,t:"床のまん中で、地面がふくらむ。"},{w:"x",n:"実況（場内の声）",t:"対するは、オリーヴァ村の三人！",v:"12_0064"},{w:null,t:"選手の入口の横に、テリオン用の水の鉢。"},{w:null,t:"エリー、手首の画面を見る。"},{w:"elly",t:"ラッキーカラーは、白だって！",v:"12_0067"},{w:"hero",f:"serious",t:"……もともと白いだろ。",v:"12_0069"}];
GR_SC.g12_04=[{w:null,t:"光が引いて、フォルンに。"},{w:null,t:"大きな画面の勝ち残りの表から、レンの名前の光がすっと消える。"},{w:null,t:"レン、しゃがんだまま、その画面を見上げる。"},{w:null,t:"レン、立ち上がる。"},{w:"hero",f:"serious",t:"……またやろうぜ、レン。",v:"12_0176"},{w:null,t:"レン、振り向かずに手を一回だけ上げる。"},{w:null,t:"登録の欄の、大人の男の名前。"},{w:null,t:"レン、画面を閉じる。"}];
GR_SC.g12_05=[{w:null,t:"床のまん中に、白い小さな台。係の人（2100年の白っぽい制服）が、空中に光の窓口を開く。"},{w:"x",n:"係の人",t:"相棒の登録です。手首を、窓口にかざしてください。",v:"12_0185"},{w:null,t:"ヤマト、左の手首をかざす。"},{w:null,t:"ヤマト、立ち上がる。"},{w:null,t:"ヤマト、手首の横の板を、フォルンの鼻先へ近づける。"},{w:null,t:"フォルン、においもかがずに、くるっとうしろを向く。"},{w:null,t:"客席が、どっと笑う。"},{w:null,t:"ヤマト、板を差し出していた手を、ゆっくり下ろす。"},{w:"hero",f:"serious",t:"……ちぇっ。別に。",v:"12_0192"},{w:null,t:"ヤマト、窓口に背を向けて、歩き出す。"},{w:null,t:"エリーが、一歩前に出かけて、止まる。アレクは腕を組んだまま、動かない。"},{w:null,t:"フォルン、走る。"},{w:null,t:"下ろしたままのヤマトの手のひらに、ぴょんと跳び乗る。"},{w:null,t:"ヤマトの足が止まる。"},{w:null,t:"フォルン、ヤマトの手のひらの上から、手首の横に浮かぶ光の板へ、前足をのばす。"},{w:null,t:"文字盤のふちの小さな印が、四つ光っている。"},{w:null,t:"板が光る。字が変わる。"},{w:null,t:"フォルンの首元に、小さな光の点がともる。"},{w:null,t:"客席が、一拍遅れて、わっと沸く。"},{w:null,t:"フォルン、ヤマトの手のひらの上で、もう知らん顔をして、前足をなめている。"}];
GR_SC.g12_06=[{w:"x",n:"実況（場内の声）",t:"優勝、オリーヴァ村！　協賛の会社より、盾が贈られます！",v:"12_0207"},{w:null,t:"貴賓席から、濃い灰色のスーツの男が床へ下りてくる。いつもの笑顔。"},{w:null,t:"男、ヤマトの前に立つ。"},{w:"victor",t:"優勝、おめでとうございます。",v:"12_0210"},{w:null,t:"フォルン、手のひらから、ヤマトの肩へ跳び移る。"},{w:null,t:"男、ヤマトの肩の上のフォルンに、手をのばしかける。"},{w:null,t:"フォルン、濃い灰色のスーツをにらんで、のどの奥で低くうなる。"},{w:null,t:"男、手を止めて、笑ったまま引っこめる。"},{w:"victor",t:"おっと。これは、失礼。",v:"12_0215"},{w:null,t:"男、付き人から盾を受け取って、ヤマトに渡す。"},{w:"hero",t:"ありがとな、スーツのおっさん！",v:"12_0218"},{w:"victor",t:"……誰が、おっさんですか。",v:"12_0219"},{w:null,t:"男、笑顔のまま。"},{w:null,t:"男、アレクの前へ。手を差し出す。"},{w:"victor",t:"あなたも、見事でした。",v:"12_0222"},{w:"alek",t:"……どうも。",v:"12_0223"},{w:"victor",t:"才能が、おありだ。",v:"12_0227"},{w:"elly",t:"ありがとうございます！",v:"12_0228"}];
GR_SC.g12_07=[{w:null,t:"係のお姉さんが、賞金の光の板を出す。アレク、その顔を見て、すっと前に出る。"},{w:null,t:"アレク、前髪を手ぐしで直す。"},{w:"alek",t:"（一段低い声で）……実は僕、この競技場のオーナーの息子でして。",v:"12_0238"},{w:"alek",t:"……毎年、一番ええ席で見てるんすわ。",v:"12_0239"},{w:null,t:"係のお姉さん、にこっと笑って、光の板をヤマトの方へ向ける。"},{w:"x",n:"賞金の係の人",t:"賞金は、優勝した方へ。",v:"12_0241"},{w:null,t:"ヤマト、盾を抱えたまま、肩でアレクを前へ押し出す。"},{w:null,t:"アレク、背すじをのばしたまま、光の板の数字をのぞきこむ。"},{w:"alek",t:"……なんぼや。",v:"12_0244"},{w:null,t:"係のお姉さんが、アレクのカードに光の板を当てる。"},{w:null,t:"アレク、すぐパーカーの内ポケットにしまう。"},{w:null,t:"フォルン、ヤマトの肩の上から、盾のふちをかじっている。"}];
GR_SC.g12_08=[{w:null,t:"その夜。白い都の屋台の町は、遅くまで明かりが消えなかった。",v:"12_0253"},{w:null,t:"屋台の長い机。"},{w:null,t:"アレク、串にも手をつけずに、カードの残高の数字を見ている。"},{w:null,t:"アレク、カードをパーカーの内ポケットにしまう。"},{w:null,t:"エリーは、大会の初日に買えなかった大会限定の光る人形を、手のひらにのせて、にこにこしている。"},{w:"hero",t:"それ、アレクが買ったのか？",v:"12_0258"},{w:"alek",t:"……約束は、約束や。",v:"12_0259"},{w:null,t:"エリー、人形を両手で包んで、アレクにぺこりと頭を下げる。"},{w:null,t:"エリー、人形を机に立てて、頭をなでる。"},{w:"hero",t:"串、もう一本！",v:"12_0262"},{w:null,t:"店のロボットの腕が、まん中の皿に、串を一本だけのせる。"},{w:null,t:"ヤマトとアレクの目が、同時にその串に止まる。"},{w:null,t:"二人、手をひざに置いたまま動かない。"},{w:"alek",t:"じゃんけんや。",v:"12_0266"},{w:"hero",f:"serious",t:"……おう。",v:"12_0267"},{w:null,t:"二人、こぶしをかまえる。"},{w:"hero",t:"（かじって）……うめえ。",v:"12_0278"},{w:"elly",t:"ジュース、おかわりもらってくるね！",v:"12_0279"},{w:"alek",t:"ほな、おれのは大きいのな。",v:"12_0280"},{w:"elly",t:"はーい。",v:"12_0281"}];
GR_BT[12]={mid:[[{w:null,t:"レン、手首の画面を見ずに立つ。地面から顔を出すバジリク。"},{w:null,t:"ヤマトの手首の画面の端に、きのうの夜描いた絵が一瞬（閉じた目の絵がいくつも）。"},{w:"x",n:"審判",t:"始め！",v:"12_0080"},{w:null,t:"三人が、手首の画面をかざす。"},{w:"x",n:"三人",t:"進化！",v:"12_0083"},{w:"hero",t:"フォルコン、一番うしろだ。",v:"12_0085"},{w:"hero",t:"ピリムサは左、クロベクは右！　はなれろ！",v:"12_0086"},{w:"elly",t:"分かった。ピリムサ、左ね！",v:"12_0087"},{w:"alek",t:"は？　フォルコン、前に出さへんの？",v:"12_0088"}],[{w:"hero",t:"いいから。",v:"12_0089"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"岩には水やろ！　クロベク、突け！",v:"12_0095"},{w:null,t:"レンは、画面も見ずに、バジリクの背中だけを見ている。"},{w:"dimi",t:"魔眼封石（まがんロック）。",v:"12_0101"},{w:"alek",t:"クロベク！",v:"12_0103"},{w:null,t:"ヤマト、フォルコンの真うしろ、数歩はなれた所で膝をつく。手のひらを開いて、顔の高さに上げる。"},{w:"hero",t:"フォルコン、待ってくれ。",v:"12_0109"},{w:"dimi",f:"serious",t:"……見ないのか。",v:"12_0115"},{w:null,t:"レン、バジリクの背中から、初めて目を上げる。"},{w:null,t:"レンの目が、光るフォルコンと、ヤマトの手のひらを往復する。"},{w:null,t:"ヤマトの目が床へ落ちる。"}],[{w:"hero",t:"フォルコン、前見てろ。合図したら、すぐ行け。",v:"12_0128"},{w:null,t:"ヤマト、手のひらを下ろして、膝をついたまま、さらに数歩うしろへ下がる。"},{w:"elly",t:"ピリムサ、一回だけでいい！",v:"12_0131"},{w:"alek",t:"クロベク、回りこめ。出た所を横から突くで。",v:"12_0132"},{w:null,t:"ヤマト、手首の画面をかざす。"},{w:"hero",t:"フォルコン、進化！",v:"12_0138"},{w:"dimi",t:"魔眼――",v:"12_0148"},{w:null,t:"レンの口が、言いかけたまま止まる。"},{w:"hero",t:"いっけえ、フォルレオン！　灼熱地獄（しゃくねつじごく）！！",v:"12_0151"},{w:null,t:"ヤマトの声で、フォルレオンが跳ぶ。"}]],post:[{w:null,t:"バジリクが目を開けかける。"},{w:null,t:"審判の旗。観客席が一拍遅れて爆発する。"},{w:"hero",f:"smile",t:"……勝った。勝ったぞ、フォルン！！",v:"12_0159"},{w:null,t:"アレク、ヤマトの方を向いて、自分のまぶたを指でとんとさす。"},{w:"alek",t:"砂入ったら、目ぇ閉じるんや。",v:"12_0161"},{w:"elly",f:"smile",t:"ヤマト、勝った！　勝ったよ！",v:"12_0163"}]};
GR_EP[12]={"t": "決勝", "sc": [["g12_01", "宿（決勝の前の夜）", 0], ["g12_02", "決勝の日の競技場（午後）", 0], ["g12_03", "決勝", 1], ["g12_04", "勝負のあと（表示と、名前を呼ぶ）", 0], ["g12_05", "登録の窓口", 0], ["g12_06", "表彰", 0], ["g12_07", "表彰のあと（賞金）", 0], ["g12_08", "お祝いの夜（屋台の町）", 0]]};
GR_SC.g13_01=[{w:null,t:"大会が終わった夜。港のそばの屋台の町は、お祭りだった。",v:"13_0024"},{w:null,t:"港のそばの屋台の町。"},{w:null,t:"屋台が並ぶ。"},{w:null,t:"通りのまん中の空中の画面に、きょうの決勝がくり返し流れている。"},{w:null,t:"屋台の長い机。"},{w:null,t:"ヤマトのまわりに、子どもたちが五、六人。"},{w:"x",n:"屋台の子ども",t:"ねえ、優勝した狐って、この子？",v:"13_0030"},{w:"hero",t:"そうだぜ。今は寝てるけどな。",v:"13_0031"},{w:"x",n:"屋台の子ども",t:"決勝の火、すごかった！　さわってもいい？",v:"13_0032"},{w:"hero",t:"こいつに聞けよ。",v:"13_0033"},{w:null,t:"ヤマト、左の手のひらを上にして、フォルンの前に置く。"},{w:null,t:"フォルン、片目をあける。"},{w:null,t:"フォルン、女の子の手のひらに、前足をぽんとのせる。"},{w:null,t:"女の子が、きゃあっと跳びはねる。子どもたち、わっと笑う。"},{w:null,t:"机の向かいの、アレクの席は空いている。"},{w:null,t:"フォルン、何もなかった顔で、また丸くなる。"},{w:null,t:"アレク、通りのくじの屋台から、景品の小さな袋をかかえて戻ってくる。"},{w:"hero",t:"アレク、それ全部くじか？",v:"13_0041"},{w:"alek",t:"（早口で）全部や。一軒一回、ただやねん。",v:"13_0042"},{w:"hero",t:"それ、何に使うんだよ。",v:"13_0043"},{w:"alek",t:"……使わへん。",v:"13_0044"},{w:"x",n:"屋台の女の子",t:"それ、一個ちょうだい。",v:"13_0046"},{w:"alek",t:"……一回ぶんの値打ちあんねんぞ。",v:"13_0047"},{w:"hero",t:"使わねえんだろ。",v:"13_0048"}];
GR_SC.g13_02=[{w:null,t:"飲み物の屋台。"},{w:null,t:"エリー、列に並ぶ。"},{w:"kasia",t:"エリーさんね。優勝、おめでとう。",v:"13_0057"},{w:"elly",f:"surprised",t:"ありがとう！　……えっと、だれ？",v:"13_0058"},{w:"kasia",t:"カシアよ。ヴィクターさまが、お呼びよ。",v:"13_0059"},{w:null,t:"エリーの笑顔が、止まる。"},{w:null,t:"エリーの目が、カシアの耳のオレンジの輪へ行く。それから、通りの空中の画面。"},{w:"elly",f:"serious",t:"……行かない。友だちが待ってるもん。",v:"13_0062"},{w:"kasia",t:"あら。聞いてるんじゃないのよ。",v:"13_0063"},{w:null,t:"カシア、目だけで、エリーのうしろを見る。"},{w:null,t:"エリーの影に、大きな影が重なる。"},{w:null,t:"ゼノ、何も言わずに、エリーの腰をかかえて、肩にかつぎ上げる。"},{w:"elly",t:"はなして！　……ヤマト！",v:"13_0071"},{w:null,t:"第13話　さらわれた夜",v:"13_0073"}];
GR_SC.g13_03=[{w:null,t:"屋台の机。ヤマト、顔を上げる。"},{w:null,t:"通りの向こう。"},{w:"hero",t:"エリー！",v:"13_0081"},{w:null,t:"ヤマト、もう走りだしている。机のフォルンが、ぱっと目をあけて、ヤマトの横を走る。"},{w:null,t:"アレク、串を放り出し、盾とクロッコをかかえて追う。"},{w:null,t:"階段の上。石だたみに、ころがったカップと、白い肩かけカバン。"},{w:null,t:"ヤマト、走りながらカバンをつかみ上げ、肩にかける。"}];
GR_SC.g13_04=[{w:null,t:"屋台の明かりが、背中の方に遠くなる。"},{w:null,t:"海へまっすぐのびる一本の桟橋。"},{w:null,t:"ヤマトの目が、欠けた光の玉に一回だけ止まる。"},{w:null,t:"桟橋の先に、明かりを消した黒い船。ゼノが、エリーをかついだまま、船へ上がっていく。"},{w:null,t:"甲板のエリーが、こっちを見る。"},{w:"elly",t:"ヤマト！",v:"13_0094"},{w:"hero",t:"待ってろ！　今行く！",v:"13_0095"}];
GR_SC.g13_06=[{w:null,t:"黒い船の明かりが一つ、ともる。"},{w:null,t:"ヤマト、走る。"},{w:null,t:"甲板のへりに、エリー。ゼノの手をふりはらって、手すりから身を乗り出す。"},{w:"elly",t:"ヤマト！",v:"13_0163"},{w:null,t:"ヤマト、桟橋のいちばん先で、右手をいっぱいにのばす。"},{w:null,t:"ヤマト、板のへりをけって跳ぼうとする——"},{w:null,t:"うしろから、アレクがヤマトの上着のえりをつかむ。"},{w:"alek",t:"あかん！　落ちたら終わりや！",v:"13_0168"},{w:null,t:"ヤマトの手が、空をつかむ。"},{w:null,t:"ゼノの大きな手が、エリーの肩をうしろへ引く。"},{w:null,t:"船の明かりが、沖へ小さくなっていく。"},{w:null,t:"ヤマト、のばした手を下ろさない。"},{w:null,t:"アレク、えりをはなす。"},{w:null,t:"フォルンが、よろよろと歩いてきて、ヤマトの足もとで止まる。ヤマトの顔を見上げる。"}];
GR_SC.g13_07=[{w:null,t:"安い宿の部屋。"},{w:null,t:"ヤマト、盾を壁に立てかける。"},{w:null,t:"ヤマトのポケットから、エリーにもらったおそろいの光る腕輪が一つ、ころがり出る。"},{w:null,t:"フォルンが、テーブルに跳び上がる。"},{w:null,t:"ヤマトの手首が、呼び出しの音で鳴る。"},{w:null,t:"ヤマト、画面を見たまま、止まる。"},{w:null,t:"声だけの電話。空中に、アナの声の波形が小さく浮かぶ（顔は映さない）。"},{w:"ana",t:"ヤマト！　見てたよ、優勝！　村じゅう大さわぎよ。",v:"13_0187"},{w:"ana",t:"で、エリーは？　さっきから、かからないの。",v:"13_0188"},{w:"hero",f:"serious",t:"……アナさん。エリー、連れてかれた。",v:"13_0189"},{w:null,t:"声の波形が、平らになる。"},{w:"ana",t:"……だれに。",v:"13_0191"},{w:"hero",t:"黒いコートの女と、船のヒゲのおっさん。",v:"13_0192"},{w:"hero",t:"耳と胸に、オレンジの輪つけてた。",v:"13_0193"},{w:null,t:"長い間。波形が、小さくふるえる。"},{w:"ana",t:"……あの黒い車の連中ね。",v:"13_0195"},{w:"ana",t:"村のみんなに、心当たりを聞いて回る。",v:"13_0196"},{w:"hero",f:"serious",t:"……あした、迎えに行く。",v:"13_0197"},{w:"ana",t:"……ヤマト。あんたまで、いなくならないでよ。",v:"13_0198"},{w:null,t:"ヤマト、返事ができない。"},{w:"alek",t:"（画面に顔を寄せて）……アナさん。こいつは、おれが見ときます。",v:"13_0200"},{w:"ana",t:"……うん。お願い。",v:"13_0201"},{w:null,t:"声の波形が消える。"},{w:null,t:"ヤマト、寝棚のはしに座る。右手を、ひざの上で開いたり閉じたりしている。"}];
GR_SC.g13_08=[{w:null,t:"アレク、窓ぎわに立っている。"},{w:null,t:"指が、一つの行で止まる。"},{w:null,t:"アレク、その行を消そうとして、指を止める。"},{w:null,t:"ヤマト、それを見ていない。"},{w:"hero",t:"アレク。あしたの朝、行くぞ。",v:"13_0210"},{w:"alek",t:"……どこ行くんや。",v:"13_0211"},{w:"hero",t:"知らねえよ。探すの、お前の得意だろ。",v:"13_0212"},{w:null,t:"アレク、答えない。"},{w:"hero",f:"serious",t:"……お前、なんか隠してんだろ。",v:"13_0214"},{w:"alek",t:"……何もあらへん。",v:"13_0215"},{w:null,t:"アレク、明かりを消す。"},{w:null,t:"カバンの上のフォルンが、耳だけアレクの方へ向ける。"}];
GR_SC.g13_09=[{w:null,t:"同じ夜。白い都から遠く離れた、丘の上。",v:"13_0220"},{w:null,t:"丘の頂上に、古い石の門。"},{w:null,t:"門の奥に、白い屋敷。"},{w:null,t:"丘のふもとから、黒い車が一台、坂を上っていく。"},{w:null,t:"車のうしろの窓。エリーの横顔。"},{w:null,t:"門が、内側から開く。"}];
GR_BT[13]={mid:[[{w:"kasia",t:"その子は、もう話がついてるの。",v:"13_0101"},{w:"hero",t:"どけよ！　エリー返せ！",v:"13_0102"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:null,t:"ヤマトとアレクが、手首の画面をかざす。"},{w:"x",n:"二人",t:"進化！",v:"13_0107"},{w:null,t:"ヤマト、もう一度、手首の画面をかざす。"},{w:"hero",t:"フォルコン、進化！",v:"13_0113"},{w:null,t:"ヤマト、手首を見て、それからフォルコンを見る。"},{w:null,t:"ヤマトとアレク、二体のうしろ、岸の側へ大きく下がって立つ。"},{w:"hero",t:"フォルコン、撃て！",v:"13_0117"},{w:"alek",t:"クロベク、行け！",v:"13_0119"}],[{w:"alek",t:"羽の音がせえへん。目、離すなよ、ヤマト！",v:"13_0122"},{w:null,t:"ヤマト、暗い空を探すのをやめる。"},{w:null,t:"ヤマト、手のひらを下ろす。右手で、二本目の街灯の真上の暗がりを指す。"},{w:"alek",t:"クロベク、今や！",v:"13_0134"},{w:null,t:"アレク、ヤマトの横へ走りこんで、二本目の街灯を指でさす。"},{w:"alek",t:"光が欠けたとこに、おったんか。",v:"13_0138"},{w:null,t:"ヤマト、一回だけうなずく。"},{w:null,t:"ヤマト、柱の根もとのヨルフクを指さす。"},{w:"hero",t:"フォルコン、フォックスファイヤー！",v:"13_0142"},{w:"hero",f:"surprised",t:"うそだろ……！",v:"13_0150"},{w:null,t:"アレク、ヤマトの方を向いて、石段のカシアの手首を指さす。"},{w:"alek",t:"……画面押して、無理やり変えよった。",v:"13_0155"}]],post:[]};
GR_EP[13]={"t": "さらわれた夜", "sc": [["g13_01", "白い都・屋台の町（夜）", 0], ["g13_02", "飲み物の屋台の裏", 0], ["g13_03", "屋台の机〜港へ下りる階段", 0], ["g13_04", "三番桟橋（夜）", 0], ["g13_05", "勝負（2Dアニメ）", 1], ["g13_06", "桟橋の先", 0], ["g13_07", "安い宿の部屋（夜ふけ）", 0], ["g13_08", "安い宿の部屋（同じ夜）", 0], ["g13_09", "獅子門の丘（夜）", 0]]};
GR_SC.g14_01=[{w:null,t:"エリーのいない朝。二人は、白い都を出た。",v:"14_0024"},{w:null,t:"宿の入口で、アレクが優勝の盾を、預かりのロボットに渡す。"},{w:null,t:"宿の前の道に、白いロボタクシーがすっと止まる。"},{w:null,t:"車の中の空中の文字「行き先をどうぞ」。"},{w:"hero",t:"で、どこ行くんだよ。",v:"14_0028"},{w:null,t:"アレク、頭のゴーグルも下ろさずに、空中の文字に言う。"},{w:"alek",t:"獅子門の丘。北の坂の下まで。",v:"14_0030"},{w:null,t:"空中の文字「獅子門の丘　北の坂の下　約1時間30分」。"},{w:"hero",f:"serious",t:"……早っ。",v:"14_0032"},{w:"alek",t:"あの女のピアス、見たやろ。あの輪の連中の屋敷や。",v:"14_0033"},{w:"hero",f:"serious",t:"……坂の下まで、なんで分かんだよ。",v:"14_0034"},{w:null,t:"アレク、窓の外を見ている。"},{w:null,t:"ヤマト、アレクの横顔を見る。"},{w:null,t:"第14話　獅子門の丘",v:"14_0038"}];
GR_SC.g14_02=[{w:null,t:"坂の下の道。"},{w:null,t:"坂の下のオリーブ林。"},{w:"alek",t:"かたっ。きのうのパンやん。",v:"14_0046"},{w:"hero",t:"フォルン、ちょっとだけ、あっためてくれ。",v:"14_0047"},{w:null,t:"ヤマト、パンをフォルンの前に置く。"},{w:null,t:"ぼっ。パンが、まっ黒なかたまりになる。"},{w:null,t:"ヤマト、まっ黒なかたまりを二つに割って、片方をアレクにわたす。自分の方を、平気な顔でばりばりかじる。"},{w:null,t:"アレク、まっ黒なはしを、かじる。顔じゅうしわだらけになる。"},{w:"alek",t:"……よう、うまそうに食えるな。",v:"14_0052"},{w:"hero",t:"うまいじゃん。",v:"14_0053"},{w:null,t:"ヤマト、かじる手を止めて、手の中の黒いパンを見る。"},{w:null,t:"少しはなれた木の根もと。フォルンが、自分のしっぽの火で、落ちていたオリーブを一つずつあぶって、一人で食べている。"},{w:null,t:"ヤマト、立ち上がる。"}];
GR_SC.g14_03=[{w:null,t:"丘の上に、石の獅子が二頭、門を守っていた。",v:"14_0059"},{w:null,t:"丘の頂上。古い石の門。"},{w:null,t:"門の内側に、新しい白い柵。"},{w:null,t:"二人が呼ぶ前に、白い柵が、すうっと横に開く。"},{w:null,t:"門の内側に、濃い灰色のスーツの男が立っている。"},{w:null,t:"男のうしろに、大きな黒い影。"},{w:null,t:"【プロフィール】ヴァンプロード／闇／●●●／黒い羽をコートにする"},{w:null,t:"そのまたうしろに、ゼノ。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"……レベル45。闇や。",v:"14_0069"},{w:null,t:"ヴィクター、一歩前へ出る。"},{w:"victor",t:"早かったな。",v:"14_0071"},{w:"hero",t:"あんた……大会で盾くれたおっさん！",v:"14_0072"},{w:"victor",t:"ヴィクターだ。",v:"14_0073"},{w:null,t:"ヤマト、男の指の輪を見る。"},{w:"hero",f:"serious",t:"……やっぱり、お前らか。",v:"14_0075"},{w:"hero",t:"エリー返せよ！",v:"14_0076"},{w:null,t:"ヴィクターの指輪の指が、門の柱を、とん、とん。"},{w:"victor",t:"……ヴァンプロード。出ろ。",v:"14_0078"},{w:null,t:"ヴァンプロード、一歩前へ。"},{w:null,t:"ヤマトの足もとで、フォルンが前に出る。"},{w:"hero",t:"フォルン、進化！",v:"14_0084"},{w:"hero",f:"serious",t:"……フォルン、撃て！",v:"14_0086"},{w:"victor",t:"狐に用はない。話があるのは、そっちだ。",v:"14_0102"},{w:"victor",t:"エリーなら上だ。……茶でも出そう。上がっていけ。",v:"14_0104"},{w:"hero",t:"茶なんかいらねえ。エリー出せよ。",v:"14_0105"}];
GR_SC.g14_04=[{w:null,t:"屋敷の奥のテラス。"},{w:null,t:"テラスの前は、刈りこんだ芝の庭。"},{w:null,t:"ヴァンプロードは、ヴィクターの椅子のうしろに立っている。"},{w:null,t:"ヴィクター、カップを持ち上げる。"},{w:null,t:"ヴィクターの横の空中に、ロケットの図面が一枚。"},{w:"victor",t:"アレク。ロケットの金なら、いくらでも出す。",v:"14_0115"},{w:null,t:"ヴィクター、胸のポケットから、手のひらほどのうすいカードを出す。"},{w:null,t:"胸のポケットの奥に、角のすり切れた古い単語帳が見える。"},{w:null,t:"アレク、カードを見る。手をのばさない。"},{w:"hero",f:"serious",t:"……アレク。こいつのこと、知ってたのかよ。",v:"14_0119"},{w:"alek",t:"……仕事の相手やった。声だけや。",v:"14_0120"},{w:"hero",t:"仕事って、フォルンを運べってやつか？",v:"14_0121"},{w:null,t:"アレク、答えない。カードから目を上げない。"},{w:null,t:"ヴィクター、カップを置く。笑顔のまま。"},{w:"victor",t:"……仕事を頼んだのは、おれだ。",v:"14_0124"},{w:null,t:"ヤマトの目が、アレクの手首の画面に行く。"}];
GR_SC.g14_05=[{w:null,t:"屋敷の中から、テラスへ下りる白い階段。"},{w:null,t:"階段の上に、カシアが立っている。"},{w:"hero",t:"エリー！",v:"14_0133"},{w:null,t:"ヤマト、椅子をけって立つ。"},{w:"hero",t:"けがしてねえか？　帰るぞ！",v:"14_0135"},{w:"elly",f:"serious",t:"……けが、してない。",v:"14_0136"},{w:"hero",t:"じゃあ、下りてこいよ。",v:"14_0137"},{w:"elly",f:"serious",t:"……アレクも、来てくれたんだ。",v:"14_0138"},{w:null,t:"エリー、笑う。でも、階段の三段上で止まったまま、下りてこない。"},{w:null,t:"エリーの目が、庭の奥の古い柱へ行く。"},{w:null,t:"ヴィクター、カップを置く。笑顔のまま立ち上がる。"},{w:"victor",t:"読めたか。",v:"14_0142"},{w:null,t:"エリー、柱の字を見たまま、小さくうなずく。"},{w:"victor",t:"古代の字を読めるのは、おまえだけだ。",v:"14_0144"},{w:"victor",t:"ここにいれば、封じられた記録を全部読ませてやる。",v:"14_0145"},{w:"victor",t:"村にも、手は出さんでおいてやる。",v:"14_0146"},{w:null,t:"ヴィクター、指を一度だけ動かす。エリーの目の前の空中に、画面が一枚開く。"},{w:null,t:"ヴィクター、指輪の指で、階段の手すりを、とん、とん。"},{w:"victor",t:"……決めろ。",v:"14_0150"},{w:"victor",t:"おまえしだいだ。",v:"14_0151"},{w:null,t:"画面が閉じる。"},{w:null,t:"エリーの目が、手首の白い画面に落ちる。"},{w:null,t:"エリーの手が、手すりをにぎる。"},{w:null,t:"ヤマト、ヴィクターとエリーを見くらべる。"},{w:"hero",t:"なに言ってんだよ。エリー、行くぞ。",v:"14_0156"},{w:null,t:"エリー、ヤマトを見る。それから、ヴィクターを見る。"},{w:null,t:"エリー、ゆっくり、首を横にふる。"},{w:"elly",f:"serious",t:"……わたし、ここに残る。",v:"14_0159"},{w:"hero",t:"は？",v:"14_0160"},{w:null,t:"ヤマト、階段を三段かけ上がる。"},{w:"hero",t:"こいつの言うことなんか、信じんなよ！　来いって！",v:"14_0162"},{w:null,t:"ヤマト、エリーの腕を引っぱって、階段を下りる。"},{w:null,t:"エリー、腕を大きくふる。ヤマトの手が、はじかれてはなれる。"},{w:"alek",t:"……エリー、ほんまにええんか。",v:"14_0173"},{w:"elly",f:"serious",t:"……へーき、へーき。",v:"14_0175"},{w:"victor",t:"ゼノ。客が帰る。門まで送れ。",v:"14_0178"}];
GR_SC.g14_06=[{w:null,t:"門の外。うしろで、ゼノが白い柵を閉める。"},{w:null,t:"屋敷の裏の道から、黒い荷車が出てきて、二人を追いこす。"},{w:null,t:"ヤマト、手首の画面を上げて、札を一枚撮る。"},{w:null,t:"丘を下りる道。"},{w:null,t:"アレクが前、ヤマトがうしろ。"},{w:null,t:"アレク、パーカーのポケットから研究費のカードを出す。"},{w:null,t:"道ばたの、ごみを集めるロボットの箱が、口をあけて待っている。"},{w:null,t:"アレク、カードを箱の上にかざす。……そのまま、ポケットに戻す。"},{w:null,t:"ヤマトは、それを見ている。"},{w:null,t:"坂の下。乗ってきたロボタクシーが、道で待っている。"},{w:null,t:"ヤマト、車の方へは行かない。"},{w:"hero",t:"おれ、ここで寝る。",v:"14_0194"},{w:null,t:"ヤマト、右の手首に白いリボンを結び直す。目は、丘の上の門。"},{w:null,t:"アレク、車のドアの前で止まる。"},{w:"alek",t:"……ほな、今夜は宿代、浮くな。",v:"14_0197"},{w:null,t:"ヤマト、門を見たまま、根もとの横を少しだけあける。"},{w:null,t:"アレク、荷物から、銀色のうすいシートを出す。"}];
GR_SC.g14_07=[{w:null,t:"古い木の下に、銀色のうすいシートが一枚。"},{w:null,t:"シートの下で、アレクがヤマトに背中を向けて横になっている。"},{w:null,t:"ヤマトは、あおむけ。右の手のひらを、顔の前に上げて見ている。"},{w:null,t:"右の手首に、さっき結んだ白いリボン。"},{w:null,t:"ヤマト、手をにぎる。"},{w:null,t:"草をふむ、小さな足音。"},{w:null,t:"フォルン、シートにもぐりこむ。"},{w:null,t:"ヤマト、手を胸の上に下ろす。"},{w:null,t:"ヤマトとフォルンの間に、指一本ぶんのすき間。"},{w:null,t:"背中を向けたアレクの手首が、小さく光る。"},{w:null,t:"背中を向けたアレクの目が、暗い中で、あいている。"}];
GR_SC.g14_08=[{w:null,t:"同じ夜。屋敷の、地下。",v:"14_0215"},{w:null,t:"天井の低い、白い部屋。"},{w:null,t:"画面に、古い石の扉。"},{w:null,t:"エリーが、扉の前に立っている。"},{w:null,t:"うしろの暗がりに、ヴィクターの濃い灰色のスーツ。"},{w:null,t:"エリー、扉のいちばん上の字を見る。"},{w:"victor",t:"近いうちに、本物の前に立ってもらう。",v:"14_0221"},{w:null,t:"エリー、映った扉の字を、指でなぞりはじめる。"},{w:null,t:"扉の字が、エリーの指の速さで、一つずつ白く光っていく。"},{w:null,t:"エリー、指を止めずに、ヴィクターの方をふり向く。にっこり笑う。"},{w:null,t:"ヴィクターの指輪の指が、とん、と一回だけ。……二回目は、来ない。"},{w:null,t:"ヴィクターの笑顔が、少しだけ止まる。"},{w:null,t:"エリー、前を向き直して、指をはなす。"},{w:null,t:"エリー、左の手首の白い画面を、そっとさわる。"}];
GR_EP[14]={"t": "獅子門の丘", "sc": [["g14_01", "白い都の宿の前（朝）", 0], ["g14_02", "丘のふもとのオリーブ林（昼）", 0], ["g14_03", "獅子の門", 0], ["g14_04", "屋敷のテラス", 0], ["g14_05", "テラスの階段", 0], ["g14_06", "帰り道（夕方）", 0], ["g14_07", "丘のふもとのオリーブ林（夜）", 0], ["g14_08", "屋敷の地下（夜）", 0]]};
GR_SC.g15_01=[{w:null,t:"オリーブの木の横。"},{w:null,t:"間に空いた席。"},{w:null,t:"空中の文字「行き先をどうぞ」。"},{w:"hero",t:"（空中の文字に）……コリンタ。",v:"15_0029"},{w:"alek",t:"村ちゃうんか。",v:"15_0030"},{w:null,t:"ヤマト、手首の画面をアレクの顔の前に向ける。"},{w:null,t:"アレク、ゴーグルを下ろしかけて、やめる。だまって窓の外を見る。"},{w:null,t:"町を南北にまっすぐ走る運河。"},{w:null,t:"空中の文字の下に、赤い字「この先の橋　通れません」。"},{w:null,t:"前に、運河をまたぐ低い橋。"},{w:"alek",t:"……橋、閉まってるやん。",v:"15_0037"},{w:"hero",f:"serious",t:"……あいつのこと、なんで黙ってたんだよ。",v:"15_0038"},{w:"alek",t:"言うてたら、何か変わったんか。",v:"15_0039"},{w:"hero",t:"変わったよ！",v:"15_0040"},{w:"hero",t:"エリーだって、連れてかれずに済んだかもしれねえだろ！",v:"15_0041"},{w:"alek",t:"言うたら、お前、一人で突っこんでたやろ！",v:"15_0042"},{w:"hero",t:"今だって、一人で行くよ！",v:"15_0043"},{w:null,t:"アレク、ドアを乱暴に開けて、先に降りる。"}];
GR_SC.g15_02=[{w:null,t:"ヤマト、車から降りて、机の前へ。"},{w:null,t:"机の上に、端末が一台。"},{w:"hero",t:"おい、名札。橋いつ開くんだよ。",v:"15_0052"},{w:"nomos",t:"誰が名札ですか。ノモスです。",v:"15_0053"},{w:"nomos",t:"決まりですから、通せません。",v:"15_0054"},{w:null,t:"ノモスの目が、橋の向こうの黒い荷の船へ、一回だけ行く。"},{w:null,t:"第15話　運河の町コリンタ",v:"15_0057"}];
GR_SC.g15_03=[{w:null,t:"ヤマト、ノモスの胸のオレンジの輪を見る。"},{w:"hero",t:"お前、あいつの——",v:"15_0064"},{w:"alek",t:"（ヤマトの前に出て）ほな待合所、一泊いくらっすか。",v:"15_0065"},{w:null,t:"ヤマト、アレクの背中をにらむ。"},{w:"hero",f:"serious",t:"……また、それかよ。",v:"15_0067"},{w:null,t:"アレク、聞いていない。"},{w:null,t:"岸の上の、古い石の倉庫を直した待合所。"},{w:"nomos",t:"一人、十五ジェムコインです。",v:"15_0070"},{w:"alek",t:"テリオンは、ただっすよね。",v:"15_0071"},{w:"nomos",t:"テリオンも一人に数える、と決まりに書いてあります。",v:"15_0072"},{w:"alek",t:"ほな、こいつら外で寝かせるんで。",v:"15_0073"},{w:null,t:"アレクの足もとのクロッコが、運河のへりに首をつっこむ。"},{w:null,t:"アレク、ずぶぬれのまま、真顔で手首の画面の計算を続ける。"},{w:"nomos",t:"テリオンを外で寝かせるのは、決まりで禁止です。",v:"15_0076"},{w:null,t:"アレク、画面を打つ指のまま、固まる。"},{w:null,t:"ヤマト、ふきだしかける。口を手でおさえる。"},{w:null,t:"自分の手首の画面で払って、運河名物の揚げ菓子を一袋買って戻る。"},{w:"alek",t:"……そんなもん、なんぼしたんや。",v:"15_0081"}];
GR_SC.g15_04=[{w:null,t:"橋の手前の、運河ぞいの石だたみの広場。"},{w:null,t:"植えこみの前に、小さな札。"},{w:null,t:"字の下に、人の絵とテリオンの絵。"},{w:null,t:"庭師のロボットが、葉の先をそろえている。"},{w:null,t:"ホタルンが一匹、植えこみの葉のあいだへ、すっともぐる。"},{w:null,t:"【プロフィール】ホタルン／光・森／●●○／葉のかげにもぐるホタル"},{w:null,t:"光だけが、葉のすき間からもれる。"},{w:null,t:"ヤマト、船のへりのケースの前に立つ。"},{w:null,t:"ヤマトの手が、ケースのふたにかかる。"},{w:null,t:"橋のたもとで、ノモスが立ち上がる。"},{w:"nomos",t:"荷にさわるのは、禁止です。",v:"15_0097"},{w:"hero",t:"中にテリオンいるじゃねえか！　こんなの、ほっとけるかよ！",v:"15_0098"},{w:null,t:"ノモス、机の上の端末を押す。"},{w:null,t:"船の屋根から、光る虫のような子が二匹、ふわっと飛び立つ。"}];
GR_SC.g15_06=[{w:null,t:"橋の向こうから、黒い車が一台、音もなく来て止まる。"},{w:null,t:"ノモスが、机のうしろで背すじをのばし直す。"},{w:null,t:"車から、濃い灰色のスーツの男が降りる。"},{w:null,t:"最後に、車のうしろの大きな影が、のそりと降りる。"},{w:null,t:"ヴィクター、広場の石だたみの焦げあとを見る。それから、ノモスを見る。"},{w:null,t:"ヴィクター、ノモスの机を、指輪の指で、とん、とん。"},{w:"victor",t:"荷を先に出せ。橋はそのあとだ。",v:"15_0176"},{w:"nomos",t:"はい。決まりどおりに。",v:"15_0177"},{w:null,t:"ヴィクター、広場のまん中を歩いてくる。"},{w:null,t:"フォルンが、ヤマトとアレクのあいだの石だたみに座っている。勝負のあとで、肩で息をしている。"},{w:"victor",t:"その狐も、言うことを聞くようにしてやる。",v:"15_0182"},{w:"hero",t:"さわんな！",v:"15_0183"},{w:"hero",t:"フォルン！",v:"15_0186"},{w:"victor",t:"嫌われたか。",v:"15_0194"},{w:"victor",t:"自分から来た子の方が、高く売れる。",v:"15_0196"},{w:"victor",t:"放してやれ。",v:"15_0198"}];
GR_SC.g15_07=[{w:null,t:"運河の岸。待合所の裏。"},{w:null,t:"アレク、岸の石に腰をおろす。"},{w:null,t:"アレク、自分の手首の画面にふれる。"},{w:null,t:"声だけの電話。空中に、アナの声の波形が小さく浮かぶ（顔は映さない）。"},{w:"ana",t:"アレク？　きのうの夜、何か送りかけたでしょ。",v:"15_0214"},{w:"alek",t:"……すんません。エリー、いました。自分で残るって。",v:"15_0215"},{w:"alek",t:"村、チップの子に囲まれてます。気ぃつけて。",v:"15_0216"},{w:null,t:"声の波形が、しばらく平らなまま。"},{w:"ana",t:"……あの子が、自分で？",v:"15_0218"},{w:"ana",t:"……村は、ヤニスさんたちと見てるから。",v:"15_0220"},{w:"ana",t:"ヤマト、そこにいる？",v:"15_0221"},{w:"hero",f:"serious",t:"……いる。",v:"15_0222"},{w:"ana",t:"今から送るの、エリーに会えたら見せて。",v:"15_0223"},{w:null,t:"ヤマトの手首が、ぴこん、と鳴る。"},{w:null,t:"ヤマト、それを開かずに、画面を見ている。"},{w:"ana",t:"ヤニスさんが、一味の立ち話を聞いたの。",v:"15_0226"},{w:"ana",t:"エリーを、山の向こうへ移すって。",v:"15_0227"},{w:"ana",t:"あさって。",v:"15_0228"},{w:null,t:"ヤマト、顔を上げる。"},{w:"ana",t:"あんたたちは、エリーをお願い。",v:"15_0230"},{w:"hero",f:"serious",t:"……連れて帰る。",v:"15_0231"},{w:null,t:"声の波形が消える。"}];
GR_SC.g15_08=[{w:null,t:"アレク、立ち上がる。"},{w:null,t:"アレク、パーカーのポケットから、研究費のカードを出す。"},{w:"alek",t:"……これ、返しといてください。",v:"15_0237"},{w:"nomos",t:"……お預かりします。",v:"15_0238"},{w:null,t:"ノモス、カードを両手で受け取って、子どもの絵の写真立ての横に、まっすぐ置く。"},{w:null,t:"ヤマト、それを見ている。"},{w:null,t:"ヤマト、橋の下の、遠ざかる黒い荷の船を見る。"},{w:null,t:"ヤマト、手首の画面にふれる。"},{w:"hero",t:"アレク。谷だ。",v:"15_0243"},{w:"alek",t:"……あの船と、同じ所やん。",v:"15_0244"},{w:null,t:"アレク、手首の画面にふれる。"},{w:null,t:"アレク、だまって、空中の地図の谷の印を指でなぞる。"},{w:null,t:"アレク、先に乗る。"},{w:null,t:"二人のあいだに、空いた席が一つ。"}];
GR_SC.g15_09=[{w:null,t:"その夜。獅子門の丘の屋敷。",v:"15_0251"},{w:null,t:"屋敷の地下。"},{w:null,t:"エリーが、はだしで入ってくる。"},{w:null,t:"檻の中の小さな丸い子が、オレンジの目でエリーを見る。"},{w:"elly",t:"ピリポン、見て。この子、かわいくない？",v:"15_0255"},{w:null,t:"ピリポン、エリーの髪の中から顔を出す。"},{w:null,t:"エリー、檻の格子の前に、指を一本さし出す。"}];
GR_SC.g15_10=[{w:null,t:"山あいの暗い道。"},{w:null,t:"車の中。ヤマトとアレクが、両はしの窓にもたれて眠っている。"},{w:null,t:"前の空中の文字「大理石の谷まで　あと9時間」。"},{w:null,t:"エリー、手首の白い画面に、字を一つずつ写す。"},{w:null,t:"写した行を、画面の奥の、名前のない欄へ動かす。"},{w:null,t:"戸の外で足音。"},{w:null,t:"閉じる前の画面に、字が一行。"},{w:null,t:"廊下の先、エリーの部屋の戸の下から、細い明かり。"}];
GR_BT[15]={mid:[[{w:null,t:"ヤマトとアレク、目を合わせない。"},{w:null,t:"ヤマト、アレクを見ないで、手首の画面をかざす。"},{w:null,t:"ヤマト、しぶきのかかる運河のへりを見て、フォルコンの印に指をかける。"},{w:"hero",t:"フォルン、進化！",v:"15_0108"},{w:"alek",t:"（ヤマトの方は見ない）……クロッコ、進化。",v:"15_0109"},{w:null,t:"ヤマト、横のアレクをにらむ。"},{w:"hero",t:"フォルコン、撃て！",v:"15_0119"},{w:"hero",t:"アレク、合わせろ！",v:"15_0123"}],[{w:"hero",t:"融合！",v:"15_0126"},{w:null,t:"アレクの声は重ならない。"},{w:null,t:"アレク、手首を上げかけて、止める。"},{w:"hero",f:"angry",t:"……なんでだよ！",v:"15_0130"},{w:null,t:"アレク、手首を下ろしたまま、前だけ見る。"},{w:"alek",t:"木の中に入られたら、当たらへんで。",v:"15_0133"},{w:null,t:"ヤマト、指をそろえた右の手のひらを、まっすぐ立てる。"},{w:null,t:"ヤマトの目が、植えこみの前の小さな札に止まる。"},{w:"hero",t:"おい！　あの札、テリオンにも×ついてんぞ！",v:"15_0141"},{w:"nomos",t:"ホタルン、出なさい。決まりですから。",v:"15_0145"}],[{w:"hero",t:"フォルコン、フォックスファイヤー！",v:"15_0148"},{w:null,t:"ノモス、端末を持ったまま、背すじをのばして立っている。"},{w:null,t:"アレク、ノモスを見たまま、ひじでヤマトの腕を一回つつく。"},{w:"alek",t:"……テリオンも一人、やもんな。",v:"15_0154"},{w:"nomos",t:"（端末を見たまま）……数え方は、合っています。",v:"15_0155"},{w:null,t:"ヤマト、アレクを見る。"},{w:"hero",f:"serious",t:"……さっきの融合、わざとかよ。",v:"15_0158"},{w:"alek",t:"合わさんでも、勝てたやん。",v:"15_0159"},{w:null,t:"ヤマト、船のへりのケースへ走る。ふたに手をかける。"},{w:null,t:"ヤマト、ふたに手をかけたまま、動けない。"}]],post:[]};
GR_EP[15]={"t": "運河の町コリンタ", "sc": [["g15_01", "ロボタクシーの中〜運河の橋の前（朝）", 0], ["g15_02", "橋のたもと・ノモスの机", 0], ["g15_03", "橋のたもと（昼前）", 0], ["g15_04", "運河ぞいの広場・黒い荷の船", 0], ["g15_05", "勝負（2Dアニメ）", 1], ["g15_06", "運河ぞいの広場（ヴィクター）", 0], ["g15_07", "運河の岸・アナの電話（夕方）", 0], ["g15_08", "ノモスの机〜地図（夕方）", 0], ["g15_09", "屋敷・檻の部屋（夜）", 0], ["g15_10", "夜の道", 0]]};
GR_SC.g16_01=[{w:null,t:"獅子門の丘の屋敷。"},{w:null,t:"エリー、寝台のはしに座っている。"},{w:null,t:"戸が軽く二回鳴って、開く。"},{w:"kasia",t:"おはよう。あした、山の向こうへ移るわ。",v:"16_0029"},{w:"elly",f:"serious",t:"……山の向こう？　なんで？",v:"16_0030"},{w:"kasia",t:"ヴィクターさまの用が済むまで、向こうにいてもらう。",v:"16_0031"},{w:"elly",t:"お姉ちゃんの村から、遠くなる？",v:"16_0032"},{w:"kasia",t:"遠くはないわ。……眺めは、いいそうよ。",v:"16_0033"},{w:null,t:"カシア、戸を閉める。"},{w:null,t:"エリー、窓の外を見る。"},{w:null,t:"エリー、左の手首の画面にふれかけて、指を止める。"}];
GR_SC.g16_02=[{w:null,t:"大理石の谷。山がまるごと、白い石でできている。",v:"16_0039"},{w:null,t:"谷の入口の道。"},{w:null,t:"谷の両側の山はだが、白い。"},{w:null,t:"ヤマト、肩の白いカバンをかけ直して、谷の奥へ歩きだす。"},{w:null,t:"アレク、少しおくれて歩く。"},{w:"alek",t:"で、谷に来て、どうするんや。",v:"16_0044"},{w:"hero",t:"あいつらの荷が来てんだろ。何かあるに決まってる。",v:"16_0045"},{w:"alek",t:"何かって、何や。",v:"16_0046"},{w:"hero",t:"行きゃ分かる。",v:"16_0047"},{w:null,t:"ヤマト、足を止めない。"},{w:null,t:"第16話　大理石の谷",v:"16_0050"}];
GR_SC.g16_03=[{w:null,t:"日が上がる。"},{w:null,t:"粉が、ヤマトの黒い髪に積もる。"},{w:"hero",t:"（くしゃみ）……ここ、息するだけで白くなるな。",v:"16_0058"},{w:"alek",t:"石の粉や。口、閉じて歩け。",v:"16_0059"},{w:null,t:"谷のいちばん奥。"},{w:null,t:"入口の前の地面に、太いタイヤのあとが何本も。"},{w:null,t:"アレク、しゃがんでタイヤのあとを見る。"},{w:null,t:"ヤマト、柵の前に立つ。"},{w:"alek",t:"待て待て待て。開けといてくれるん、気味悪いて。",v:"16_0064"},{w:null,t:"ヤマト、聞かずに、もう中へ入っていく。"}];
GR_SC.g16_05=[{w:null,t:"グリフォ、起き上がる。"},{w:null,t:"ヤマト、グリフォの羽のつけ根の帯を見る。"},{w:null,t:"グリフォ、くちばしをかちっと鳴らす。"},{w:null,t:"ヤマトの手が、宙で止まる。"},{w:null,t:"ヤマト、自分の右手を見る。"},{w:null,t:"ヤマト、手を下ろす。"},{w:null,t:"ヤマト、うしろへ下がる。"},{w:null,t:"フォルンが、ヤマトのとなりに来て座る。しっぽを体に巻く。"},{w:"alek",t:"……なんで座りこむねん。",v:"16_0141"},{w:"hero",t:"いいから。",v:"16_0142"},{w:null,t:"アレク、ヤマトを見る。それから、何も言わずに、奥のケースの方へ歩いていく。"},{w:null,t:"入口から入る光が、床の上に長くのびている。"},{w:null,t:"奥で、アレクがケースのふたの空中の札を、指で一つずつ出している。"},{w:null,t:"ヤマトは、グリフォから目を離さない。"},{w:null,t:"光の筋が、白いカバンのところまで来る。"},{w:null,t:"グリフォ、首をのばす。"},{w:null,t:"グリフォ、一歩、出る。"},{w:null,t:"グリフォ、カバンの前まで来る。"},{w:null,t:"グリフォ、顔を上げる。"},{w:null,t:"ヤマト、動かない。"},{w:null,t:"グリフォ、カバンのひもをくわえる。"},{w:null,t:"グリフォ、ヤマトのひざの横にカバンを置く。"},{w:null,t:"ヤマトの左の手首の画面が、ぽうっと一度だけ光る。"},{w:null,t:"ヤマト、ゆっくり息をはく。"},{w:"alek",t:"（ケースの方を向いたまま）……そいつ、おれのカバンに頭のせさすなよ。",v:"16_0157"},{w:"hero",f:"angry",t:"……うっせ。",v:"16_0158"},{w:null,t:"グリフォ、カバンに頭をのせたまま、目だけでヤマトを見ている。"},{w:null,t:"左の羽は、体に寄せたまま。"},{w:null,t:"フォルン、ヤマトの肩に跳び上がり、そこから頭の上に乗る。グリフォを見下ろして、しっぽを立てる。"},{w:null,t:"グリフォ、すっと立つ。"},{w:null,t:"アレク、荷物を見る。"},{w:null,t:"グリフォ、頭を上げて出口へ。"},{w:null,t:"ヤマトを見る。"},{w:null,t:"ヤマト、カバンを拾って肩にかける。"}];
GR_SC.g16_06=[{w:null,t:"保管庫の前。ヤマト、谷の入口の道の方を指さす。"},{w:"hero",t:"ほら、こっちだ。車で行こうぜ。",v:"16_0170"},{w:null,t:"グリフォ、動かない。首を、谷の奥の山の方へ向けている。"},{w:null,t:"グリフォ、山の方へ歩きだす。"},{w:null,t:"ヤマト、グリフォの背中を見る。"},{w:"hero",t:"エリーも、山の向こうだ。ついてく。",v:"16_0174"},{w:null,t:"ヤマト、グリフォの方へ歩きだす。"},{w:null,t:"フォルンはヤマトの頭の上。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:"alek",t:"……山越えか。",v:"16_0179"},{w:null,t:"アレク、ゴーグルを上げる。"},{w:"alek",t:"（ヤマトの背中に）……まあ、一体増えたしな。元手ゼロで。",v:"16_0181"},{w:null,t:"ヤマト、ふり向かない。"}];
GR_SC.g16_07=[{w:null,t:"その夜。山の中腹の、岩かげ。",v:"16_0185"},{w:null,t:"大きな岩が屋根のように張り出した下。"},{w:null,t:"まん中に、手のひらほどの折りたたみの加熱板。"},{w:null,t:"アレクが鍋をかきまぜている。"},{w:null,t:"グリフォは、少しはなれた岩の上で、体を丸くしている。目はあいている。"},{w:null,t:"ヤマトは、岩のはしで光の地図を広げて、印のあたりを指で大きくしたり小さくしたりしている。"},{w:null,t:"アレク、鍋の火を止める。"},{w:"alek",t:"ヤマト、ほら、ご飯、先——",v:"16_0192"},{w:null,t:"アレク、口を閉じる。"},{w:null,t:"ヤマトも、地図を見たまま、指が止まっている。"},{w:null,t:"しばらく、加熱板の小さな音だけ。"},{w:null,t:"ヤマト、地図を閉じて、だまってアレクの前に座る。"},{w:"hero",f:"serious",t:"……しょっぱ。",v:"16_0197"},{w:null,t:"アレク、自分のカップを一口飲む。顔をしかめる。"},{w:"alek",t:"……しょっぱ。",v:"16_0199"},{w:null,t:"アレク、水の筒から、自分のカップに水を足す。"},{w:null,t:"ヤマト、アレクを見ずに、だまって自分のカップを差し出す。"},{w:null,t:"アレク、ヤマトを見ずに、そのカップにも水を足す。"},{w:null,t:"フォルン、ヤマトの頭の上から下りて、カップのにおいをかぐ。"},{w:null,t:"グリフォ、岩の上から、スープの湯気の方へ首をのばす。"},{w:null,t:"加熱板のそばのフォルンが起きる。"},{w:null,t:"文字盤のふちの小さな印が、五つ光っている。"}];
GR_SC.g16_08=[{w:null,t:"同じ夜。獅子門の丘の屋敷。",v:"16_0213"},{w:null,t:"屋敷の広い台所。"},{w:null,t:"はだしのエリーが、廊下から入ってくる。"},{w:null,t:"冷やす棚の明かりだけが、ついている。"},{w:null,t:"ヴィクターの手に、小さなプラスチックのカップ。"},{w:null,t:"カウンターの上に、角のすり切れた小さな単語帳が、開いたまま伏せてある。"},{w:null,t:"エリー、入口で止まる。ヴィクター、顔を上げない。"},{w:"victor",t:"眠れんのか。",v:"16_0220"},{w:"elly",f:"serious",t:"……のどが、かわいただけ。",v:"16_0221"},{w:null,t:"ヴィクター、冷やす棚から同じカップを一つ出して、エリーの方へすべらせる。"},{w:"victor",t:"……食わないのか。",v:"16_0223"},{w:"victor",t:"あした、扉の前に立ってもらう。",v:"16_0230"},{w:"elly",f:"serious",t:"……扉の向こうの記録、全部読めるんだよね。",v:"16_0231"},{w:"victor",t:"約束だ。",v:"16_0232"}];
GR_BT[16]={mid:[[{w:null,t:"ヤマト、口があいたまま、グリフォを見上げる。"},{w:null,t:"ヤマトの目が、その左の羽に止まる。"},{w:null,t:"アレク、ヤマトより先に、手首の画面をかざす。"},{w:null,t:"ヤマトの光は、線のすぐ上でふるえている。"},{w:"hero",t:"フォルン、進化！",v:"16_0082"},{w:"alek",t:"（ヤマトの方は見ない）……クロッコ、進化。",v:"16_0083"},{w:"alek",t:"柱のかげに隠れるんや。クロベク、目を離すな！",v:"16_0093"},{w:"hero",t:"フォルコン、まっすぐ撃て！",v:"16_0096"}],[{w:"alek",t:"クロベク、しっかりせえ！",v:"16_0102"},{w:null,t:"アレク、ゴーグルのレンズを見る。"},{w:"alek",t:"クロベク、二本目や！",v:"16_0105"},{w:null,t:"ヤマト、もう一度グリフォを見る。"},{w:"hero",t:"フォルコン、羽には撃つな。",v:"16_0111"},{w:null,t:"ヤマト、右手で、グリフォの右の、柱と柱のあいだを指す。"},{w:null,t:"ヤマト、指をそろえた右の手のひらを、まっすぐ立てる。"},{w:"hero",t:"フォルコン、フォックスファイヤー！",v:"16_0121"}]],post:[{w:null,t:"同じ時、柱に押しつけられていたボロウルも、クロベクの二発目の突きで目を回す。"},{w:null,t:"フォルコンの光が引いてフォルンに戻る。"},{w:null,t:"アレク、グリフォの寄せたままの左の羽を見る。"},{w:"alek",t:"……右にしか、跳べへんかったんか。",v:"16_0126"}]};
GR_EP[16]={"t": "大理石の谷", "sc": [["g16_01", "屋敷・エリーの部屋（夜明け）", 0], ["g16_02", "谷の入口（夜明け）", 0], ["g16_03", "谷の奥（朝）", 0], ["g16_04", "保管庫（2Dアニメ）", 1], ["g16_05", "保管庫（勝負のあと・待つ）", 0], ["g16_06", "保管庫の外（昼）", 0], ["g16_07", "山の中腹の岩かげ（夜）", 0], ["g16_08", "屋敷の台所（夜中）", 0]]};
GR_SC.g17_01=[{w:null,t:"山の向こう。古い迷宮の、いちばん奥。",v:"17_0028"},{w:null,t:"天井の高い、円い石の部屋。"},{w:null,t:"部屋の左右に、太い柱が一本ずつ。"},{w:null,t:"いちばん奥の壁いっぱいに、大きな石の扉。"},{w:null,t:"扉のすきまから、寝息のような低い音。"},{w:null,t:"扉の前の高い段に、ヴィクター、カシア、エリー。"},{w:null,t:"段の下に、オレンジの輪のしるしの機械が一台。"},{w:null,t:"ヴィクター、ふり返って、エリーを見る。"},{w:"victor",t:"エリー。扉の字は読めるか。",v:"17_0036"},{w:null,t:"エリー、扉の字を指でなぞって、小声で読んでいく。"},{w:null,t:"ヴィクターの手首の画面に、その声の波形が流れる。"},{w:"elly",t:"うん。寝てる子のことが書いてある。",v:"17_0039"},{w:"elly",t:"あと、いちばん下に「起こさないで」って。",v:"17_0040"},{w:"victor",t:"いちばん下は、聞かなかったことにする。",v:"17_0041"},{w:"elly",t:"待って！　その子、寝てるのに！",v:"17_0044"},{w:"elly",f:"serious",t:"……読むだけだって、言った。",v:"17_0050"},{w:"victor",t:"読ませてやっただろう。",v:"17_0051"},{w:null,t:"第17話　迷宮",v:"17_0056"}];
GR_SC.g17_02=[{w:null,t:"昼前。がけの下に、古い石の門が口をあけていた。",v:"17_0062"},{w:null,t:"がけをくりぬいた石の門。"},{w:null,t:"門の中は、まっ暗。フォルンのしっぽの火が、入口の壁を照らす。"},{w:null,t:"グリフォ、迷わず右の道の前へ行って、座る。"},{w:"alek",t:"……右の道、行くで。",v:"17_0066"},{w:"hero",t:"お前の言う道なんか、行かねえよ。",v:"17_0067"},{w:null,t:"アレク、肩をすくめる。"},{w:null,t:"ヤマト、アレクの方を見ないまま、グリフォの前を通りすぎて、左の道に入っていく。"},{w:null,t:"アレク、入口の壁にもたれて、腕を組む。"},{w:null,t:"左の道の奥で、フォルンの火が小さくなっていく。"},{w:null,t:"……しばらくして。"},{w:null,t:"グリフォは、右の道の前に座ったまま。"},{w:null,t:"ヤマト、コケの顔を見て、止まる。"},{w:null,t:"アレク、腕をほどく。"},{w:null,t:"フォルン、ヤマトの頭の上から、しっぽでヤマトのおでこを、ぺしっ。"},{w:null,t:"ヤマト、耳まで赤くなって、右の道へずんずん入っていく。"},{w:null,t:"アレク、横を向いて、ゴーグルを指で一回はじく。"}];
GR_SC.g17_03=[{w:null,t:"細い石の通路。フォルンのしっぽの火の明かり。"},{w:null,t:"床が細い石の橋になって、下は暗い穴。"},{w:null,t:"ヤマトの頭の上のフォルンと、前を行くグリフォが、にらみ合う。"},{w:null,t:"足もとの石が、がらっと崩れる。"},{w:null,t:"フォルンがヤマトの頭から跳ぶ。"},{w:null,t:"ヤマトとアレクも、一人ずつ跳んでわたる。"},{w:null,t:"その先で、道が五つに分かれている。"},{w:"alek",t:"クロッコ、まんなか行くで。",v:"17_0088"},{w:null,t:"アレク、まんなかの道へ入る。"},{w:null,t:"ヤマト、何か言いかけて、口を閉じる。"},{w:null,t:"まんなかの道の入口。"},{w:null,t:"ヤマト、足を止める。"},{w:null,t:"ヤマト、立ち上がって、アレクのあとを追う。"},{w:null,t:"ヤマト、指についた石の粉を見る。ふかずに、そのまま手をにぎる。"},{w:null,t:"通路の出口。"}];
GR_SC.g17_04=[{w:null,t:"台座の上で、ミノタスが半分目をあけている。"},{w:null,t:"台座の上で、ミノタスの前足が、ぴくりと床を打つ。"},{w:null,t:"赤い光が、床の上をひとすじ走る。"},{w:null,t:"かげの小石は動かない。"}];
GR_SC.g17_10=[{w:null,t:"長い通路をぬけると、日はもう傾きはじめていた。",v:"17_0253"},{w:null,t:"奥の通路をぬけると、山の反対側の斜面。"},{w:null,t:"ヤマトとアレク、出口に並んで立って、息を切らしている。"},{w:null,t:"その窓に、紺のドレスのそでが一瞬。"},{w:null,t:"分かれ道で、もう一台の黒い車が海の方へ曲がる。"},{w:null,t:"二台とも、すぐに木のかげに消える。"},{w:null,t:"二人の目が、消えた木のかげで止まる。"},{w:null,t:"ヤマト、山道の下へ、小石を一つけり落とす。"},{w:null,t:"ヤマト、手首の光の地図を開く。"},{w:null,t:"アレク、横からヤマトの手首をつかむ。"},{w:null,t:"光る印は、オリーヴァ村の外れの、古い競技場の真下。"},{w:null,t:"アレク、ゴーグルを額に上げて、前髪を指で一回なでつける。"},{w:"alek",t:"村の真下か。……アナさん、おるやん。",v:"17_0266"},{w:null,t:"ヤマト、手首をふりほどいて、アレクの肩を一回どつく。"},{w:null,t:"二人、山を下りる道を歩きだす。"},{w:"alek",t:"……ほな、下りは歩きやな。タダやし。",v:"17_0269"},{w:null,t:"坂の下の道に、白いロボタクシーがすっと止まる。"},{w:null,t:"ヤマトの手首が、ぶっと鳴る。"},{w:null,t:"アレク、長いため息。"},{w:null,t:"扉の字の写しと、エリーの声の波形。"},{w:null,t:"ヴィクターの指輪の指が、その行の上で止まる。"}];
GR_BT[17]={mid:[[{w:null,t:"ヴィクターの指輪の指が、段の手すりを、とん、とん。"},{w:null,t:"ヴィクター、回廊の階段を下りてくる二人に気づく。"},{w:"victor",t:"グリフォに案内させたか。",v:"17_0117"},{w:"hero",t:"エリー！",v:"17_0118"},{w:"elly",t:"来ちゃだめ！　その子、起こされたばっかりなの！",v:"17_0120"},{w:"hero",t:"だから来たんだろ！",v:"17_0121"},{w:null,t:"エリー、一歩、段のふちへ出かけて、止まる。"},{w:null,t:"エリーの横に、カシア。"},{w:"hero",t:"おい、ピアスのおばさん！　エリー返せ！",v:"17_0124"},{w:"kasia",t:"誰がおばさんよ。お姉さんと呼びなさい。",v:"17_0125"},{w:null,t:"カシア、エリーの横に立ったまま、まばたきもしない。"},{w:null,t:"ヤマト、カシアをにらむ。"}],[{w:"victor",t:"用が済んだら、返してやる。",v:"17_0128"},{w:null,t:"エリー、ミノタスの方を向く。"},{w:null,t:"ヴィクターの目が、ほんの一瞬、エリーの方へ動く。"},{w:null,t:"カシアがエリーの腕を取り、段の奥の通路の入口まで連れていく。"},{w:null,t:"アレク、段の方へ一歩出かけて、止まる。"},{w:null,t:"ヴィクター、手首の画面にふれる。"},{w:"kasia",t:"ヨルフク。ここで止めて。",v:"17_0135"},{w:null,t:"カシアの指が、画面を強く押す。"},{w:"alek",t:"……55。",v:"17_0144"},{w:"hero",t:"（つばをのんで）……でけえ。",v:"17_0145"},{w:"hero",t:"フォルン、進化！",v:"17_0148"},{w:"alek",t:"……クロッコ、進化。",v:"17_0150"}],[{w:"alek",t:"クロベク、あいつ続けて二回来るで。気を抜くな！",v:"17_0165"},{w:"hero",t:"フォルレオン、灼熱地獄！",v:"17_0168"},{w:null,t:"アレクの目が、焦げた根の先に止まる。"},{w:"alek",t:"クロベク、足止めせえ！",v:"17_0174"},{w:"alek",t:"でかいの来るで！",v:"17_0180"},{w:null,t:"ヤマトとアレク、赤いふちの外へ。"},{w:null,t:"ヤマトの目：左の柱。"},{w:null,t:"アレクの目：同じ左の柱。"},{w:"hero",t:"左の柱！",v:"17_0188"},{w:null,t:"ヤマトの右手が、左の柱を指す。"},{w:null,t:"ヤマトとアレク、同時に左の手首をかざす。"},{w:"x",n:"二人",t:"融合！",v:"17_0196"},{w:"hero",t:"グレンカイザー！！",v:"17_0202"},{w:"alek",t:"……でかなったな、お前ら。",v:"17_0203"}],[{w:"hero",f:"surprised",t:"グリフォ、あの黒い鳥、追っぱらえ！",v:"17_0214"},{w:null,t:"ヤマトの目と、アレクの目が、同時に同じ所で止まる。"},{w:null,t:"ヤマト、右手で、焦げた根の先を指さす。"},{w:"hero",t:"グレンカイザー、紅蓮竜顎（ぐれんアギト）！",v:"17_0219"},{w:null,t:"アレクの声が、同じ技の名前に重なる。"},{w:null,t:"アレク、床の焦げた根から、ヤマトへ目を移す。"},{w:"alek",t:"乾いた根っこやったら、火ぃ効くんやな。",v:"17_0226"},{w:null,t:"ヤマト、にっと笑いかけて、アレクと目が合う。"},{w:null,t:"カシア、通路の入口から指を一本。"},{w:null,t:"ヴィクター、手すりを、とん、とん。"},{w:"victor",t:"……立て。",v:"17_0234"},{w:null,t:"ヴィクター、笑顔のまま、命じるのをやめる。"},{w:"victor",t:"……もういい。見えた。",v:"17_0237"},{w:null,t:"ヴィクター、回廊の階段の下の二人を見る。"},{w:"victor",t:"おまえらの融合もな。今日はいい物を二つ見た。",v:"17_0239"},{w:"victor",t:"この子は置いていく。アトラードを起こせば足りる。",v:"17_0241"},{w:"victor",t:"カシア。港で待て。買い手を待たせるな。",v:"17_0244"},{w:"kasia",t:"ええ。お先に。",v:"17_0245"}]],post:[]};
GR_EP[17]={"t": "迷宮", "sc": [["g17_01", "迷宮のいちばん奥の広間（朝）", 0], ["g17_02", "迷宮の入口（昼前）", 0], ["g17_03", "迷宮の通路（昼前）", 0], ["g17_04", "広間を見下ろす回廊（昼前）", 0], ["g17_05", "迷宮の奥の広間・勝負の頭", 1], ["g17_06", "勝負・押される", 1], ["g17_07", "勝負・左の柱", 1], ["g17_08", "勝負・角の根", 1], ["g17_09", "止める", 1], ["g17_10", "迷宮の裏の出口（昼すぎ）", 0]]};
GR_SC.g18_01=[{w:null,t:"その夜。二人は、ロボタクシーで村の外れの競技場に来ていた。",v:"18_0026"},{w:null,t:"月の下の競技場。"},{w:null,t:"細長い広場。"},{w:null,t:"ヤマト、柵の前で手首の光の地図を開く。"},{w:null,t:"うしろからアレク。"},{w:null,t:"アレク、手首の画面にふれる。"},{w:null,t:"「ヤマトに貸し　タクシー代・豆のスープ　86ジェムコイン」。"},{w:null,t:"アレク、だまって、その数字をヤマトの顔の前に向ける。"},{w:null,t:"ヤマト、数字を見る。だまって、手で画面をよける。"},{w:null,t:"アレク、だまって、画面をまたヤマトの顔の前へ。"},{w:"hero",t:"タクシー、フォルンは膝の上だったぞ。",v:"18_0036"},{w:"alek",t:"膝の上も席や。",v:"18_0037"},{w:null,t:"フォルン、ヤマトの頭から、アレクの頭の上へ跳び移る。"},{w:null,t:"アレク、頭の上のフォルンを見上げる。だまって、画面を閉じる。"},{w:null,t:"ヤマト、地図を閉じたまま、足もとの地面を指さす。"},{w:"hero",t:"この真下だ。先に入って待とうぜ。",v:"18_0041"},{w:"alek",t:"お前にしたら、ちゃんと考えてるやん。",v:"18_0042"},{w:"ana",t:"ヤマト？　どうしたの、こんな時間に。",v:"18_0045"},{w:"hero",t:"アナさん。もうすぐ、エリーに会えるかもしれない。",v:"18_0046"},{w:"ana",t:"……ほんと？　どこで。",v:"18_0047"},{w:"hero",t:"言ったら来ちゃうだろ。あのスーツの男も、たぶん来る。",v:"18_0048"},{w:"ana",t:"……分かった。この前の動画、ちゃんと見せてね。",v:"18_0050"},{w:"hero",t:"うん。会ったら、すぐ見せる。",v:"18_0051"},{w:"alek",t:"（横から画面に顔を寄せて）アナさん、おれもおりますんで。",v:"18_0052"}];
GR_SC.g18_02=[{w:null,t:"競技場の、真下。",v:"18_0057"},{w:null,t:"ひんやりした石の通路。"},{w:null,t:"通路は、扉の横の広い広間に出る。"},{w:null,t:"フォルン、水路から一歩はなれる。"},{w:null,t:"広間のつきあたりに、大きな石の扉。"},{w:null,t:"広間の右手に、上へ続く石の階段。"},{w:null,t:"ヤマト、扉と反対側の壁のくぼみを指さす。"},{w:null,t:"ヤマト、エリーの白い肩かけカバンを肩から下ろして、ひざの上に抱える。"},{w:null,t:"第18話　競技場の下",v:"18_0069"}];
GR_SC.g18_03=[{w:null,t:"あくる朝。オリーヴァ村へ下りていく道。",v:"18_0075"},{w:null,t:"オリーブの丘のあいだの道。"},{w:null,t:"ロボタクシーの中。"},{w:null,t:"窓の外。坂の上のため池のまわりに、黒い車が三台。"},{w:null,t:"エリー、窓の外を見たまま。"},{w:"elly",t:"ヴィクターさん。扉の向こうにも、古い字はある？",v:"18_0080"},{w:null,t:"ヴィクター、画面から目を上げない。"},{w:"victor",t:"ある。寝てる子もな。",v:"18_0082"},{w:"victor",t:"起きたら、すぐチップを入れる。",v:"18_0083"},{w:null,t:"指輪の指が、ひじかけを、とん、とん。"},{w:"victor",t:"おまえは、字を読むだけでいい。",v:"18_0085"},{w:null,t:"エリーの笑顔が、少しだけ止まる。"},{w:null,t:"窓の外。池のまわりのチップの子たち。"},{w:null,t:"エリー、ホテルの白い屋根が、窓のはしから消えていくのを見ている。"},{w:null,t:"車が、村の外れの競技場の前に止まる。"}];
GR_SC.g18_04=[{w:null,t:"右手の階段の上で、板がはずされる。"},{w:null,t:"ヴィクター、ゼノ、エリーが下りてくる。"},{w:null,t:"ヴィクターとゼノは、階段の下の岸に残る。"},{w:null,t:"エリー、ふり返る。"},{w:null,t:"エリー、その目を見ている。"},{w:null,t:"くぼみの中。"},{w:null,t:"エリー、手首の画面を扉の字に当てる。"},{w:null,t:"字が一つ光るたびに、扉の向こうで、低い寝息が少しずつ大きくなる。"},{w:null,t:"くぼみから、ヤマトが飛び出す。"},{w:"hero",t:"エリー！",v:"18_0102"},{w:null,t:"エリー、ふり返る。目が大きくなる。"},{w:null,t:"ヤマト、水路のふちまで走る。右手が、エリーの腕の方へのびる。"},{w:"victor",t:"続けろ、エリー。",v:"18_0110"},{w:"ana",n:"アナ（動画の中）",t:"エリー。ご飯、作って待ってるからね。",v:"18_0113"},{w:"ana",n:"アナ（動画の中）",t:"村の子たちも、みんな待ってるよ。",v:"18_0114"},{w:"ana",n:"アナ（動画の中）",t:"早く帰っておいで。",v:"18_0115"},{w:"victor",t:"開けろ。",v:"18_0123"},{w:"victor",t:"おまえの読みたい記録は、その向こうだ。",v:"18_0124"},{w:"elly",f:"serious",t:"……助けて。",v:"18_0135"},{w:"hero",t:"おう。",v:"18_0136"},{w:"victor",t:"……そうか。",v:"18_0140"},{w:"victor",t:"ゼノ。片づけておけ。",v:"18_0143"}];
GR_SC.g18_10=[{w:null,t:"ゼノ、階段を下りてきて、黙って水路の底に入り、ラッコンを抱え上げる。首のタオルで、ラッコンの顔の水をふく。"},{w:null,t:"ゼノ、一度だけ、こちらを見る。"},{w:"hero",t:"おい、ヒゲのおっさん。そいつ、休ませてやれよ。",v:"18_0225"},{w:"zeno",t:"……誰がヒゲだ。",v:"18_0226"},{w:null,t:"ゼノ、ラッコンを抱えて、階段を上がっていく。"},{w:null,t:"グレンカイザーの光がほどけて、フォルンとクロッコに戻る。"},{w:null,t:"グリフォ、扉のくぼみから出てきて、エリーの足もとに座る。エリーが、その頭に手を置く。"},{w:null,t:"ヤマト、くぼみに置いてきた白い肩かけカバンを取ってきて、エリーの前に出す。"},{w:"hero",t:"これ。あの夜、階段に落ちてたやつ。",v:"18_0231"},{w:null,t:"フォルン、カバンの口から白いシフォンのリボンをくわえ出して、上に落とす。"},{w:"elly",t:"わたしのカバン……ずっと持っててくれたの？",v:"18_0233"},{w:"hero",t:"フォルンが毎晩この上で寝るから、置いてけなかったんだよ。",v:"18_0234"},{w:null,t:"フォルンが跳んで、エリーの抱えたカバンの上に乗る。"},{w:null,t:"カバンの口から、光るシール帳と、光るお菓子帳の角がのぞいている。"},{w:null,t:"ヤマト、カバンに鼻がつくほど、フォルンに顔を近づける。"},{w:"hero",t:"な、フォルン。カバン番、えらかったな。",v:"18_0238"},{w:null,t:"フォルン、そっぽを向く。しっぽの火だけ、ぼっと燃え上がる。"},{w:null,t:"近づけていた前髪の先に、火が届く。"},{w:"alek",t:"クロッコ、消してやれ。",v:"18_0241"},{w:"alek",t:"……お前迎えに来たタクシー代、ツケにしといたで。",v:"18_0247"},{w:"elly",t:"なにそれ。",v:"18_0248"},{w:"hero",t:"それ、おれにもつけてただろ。",v:"18_0249"},{w:"alek",t:"上はあいつらの道や。下から出るで。",v:"18_0253"},{w:"alek",t:"（エリーに）離れたらあかんで。",v:"18_0254"}];
GR_SC.g18_11=[{w:null,t:"その日の夕方。村のいちばん上の丘。",v:"18_0264"},{w:null,t:"夕日。丘の頂上の研究所あと。"},{w:null,t:"くぼみの中に、山のように大きな体が丸くなって眠っている。"},{w:null,t:"くぼみのふちに、ヴィクター。"},{w:null,t:"ゼノが、首にタオルをかけたまま、少しはなれて立っている。"},{w:null,t:"ヴィクター、手首の画面を空中に開く。"},{w:null,t:"画面から、エリーの声が小さく流れる。"},{w:null,t:"ヴィクター、その行を指でなぞりながら、くぼみのふちを下りる。"},{w:null,t:"指輪の指が、首すじのうろこを、とん、とん。"},{w:"victor",t:"（古代ギリシャ語・字幕）起きろ。",v:"18_0273"},{w:null,t:"眠る巨体の首のチップが、強く光る。"},{w:null,t:"大きなまぶたが、ゆっくり開く。"},{w:null,t:"アトラードの目に、夕日が映る。"},{w:null,t:"【プロフィール】アトラード／光・地／赤い●／光のもれる石うろこの巨体"}];
GR_BT[18]={mid:[[{w:null,t:"エリー、ヤマトの手を離して、水路から離れた古い石の台（大人の胸ほどの高さ）に上がる。"},{w:"x",n:"三人",t:"進化！",v:"18_0157"}],[{w:"alek",t:"クロベク、ふちから撃て！",v:"18_0163"},{w:null,t:"ゼノ、手首の画面にふれる。"}],[{w:null,t:"エリー、ピリムサを、水路から離れた岸の石の上へ呼びもどす。"},{w:null,t:"ヤマトとアレク、同時に手首の画面をかざす。"},{w:"x",n:"二人",t:"融合！",v:"18_0185"},{w:"hero",t:"まだだ。岸まで下がって待て。",v:"18_0191"}],[{w:null,t:"エリーの目：扉のまわりの、厚く深くくぼんだ石。"},{w:"elly",t:"グリフォ、扉のくぼみ！",v:"18_0201"},{w:"hero",t:"グレンカイザー、ピリムサの前だ！　撃ち終わるまで動くな！",v:"18_0203"},{w:null,t:"ヤマト、その手を下ろして、ラクドリスを指さす。"},{w:"hero",t:"グレンカイザー、紅蓮竜顎（ぐれんアギト）！",v:"18_0213"},{w:null,t:"アレクの声が、同じ技の名前に重なる。"}]],post:[{w:null,t:"湯気が晴れる。ラクドリス、底にあおむけになって、目を回している。"},{w:null,t:"アレク、からになった水路の底を、あごでさす。"},{w:"alek",t:"水がのうなったら、火ぃ細ならへんのか。",v:"18_0218"},{w:null,t:"ヤマト、上げっぱなしだった腕を、ぶらぶらふる。"},{w:"hero",f:"serious",t:"……腕、しびれた。",v:"18_0220"}]};
GR_EP[18]={"t": "競技場の下", "sc": [["g18_01", "夜の古代の競技場（夜）", 0], ["g18_02", "競技場の下・地下の通路（夜ふけ）", 0], ["g18_03", "村へ下りる道・ロボタクシーの中（朝）", 0], ["g18_04", "地下の扉の前（朝）", 0], ["g18_05", "勝負・頭", 1], ["g18_06", "勝負・チップの進化", 1], ["g18_07", "勝負・大波", 1], ["g18_08", "勝負・しのぐ", 1], ["g18_09", "勝負・決着", 1], ["g18_10", "勝負のあと・逃げる", 0], ["g18_11", "丘の上・研究所あと（夕方）", 0]]};
GR_SC.g19_01=[{w:null,t:"村はチップの子だらけ。三人は、日が暮れるまで地下で待った。",v:"19_0026"},{w:null,t:"その夜ふけ。裏の畑の道から、ホテルへ帰った。",v:"19_0027"},{w:null,t:"収穫のすんだ段々のぶどう畑。"},{w:null,t:"坂の上。ため池のまわりに、黒い車の小さな明かりが三つ。"},{w:null,t:"ホテルの白い壁。裏口の戸。"},{w:null,t:"アナ。2100年の作業着の上に、夜の見張りの上着。"},{w:null,t:"アナ、エリーを上から下まで、一回だけ見る。"},{w:null,t:"エリー、いつもの笑顔を作りかけて、やめる。"},{w:"elly",f:"serious",t:"……ただいま。",v:"19_0034"},{w:"ana",t:"おかえり。早く入って。",v:"19_0035"},{w:null,t:"第19話　空の寝床",v:"19_0037"}];
GR_SC.g19_02=[{w:null,t:"ホテルの台所。"},{w:null,t:"アナ、エリーをテーブルの前に座らせる。グリフォがエリーの足もとに横になって、すぐに目を閉じる。"},{w:"ana",t:"わたし、ヤニスさんと交代で池の見張りなの。",v:"19_0045"},{w:"ana",t:"スープ、鍋にあるから。温めてあげて。",v:"19_0046"},{w:"alek",t:"はい、やっときますわ。",v:"19_0047"},{w:null,t:"アナ、そう言ったまま、出ていかない。"},{w:null,t:"コンロの前。"},{w:null,t:"スープの皿が、エリーの前に置かれる。"},{w:null,t:"エリー、スプーンで一口。"},{w:null,t:"アナ、腕を組んだまま、それを見ている。"},{w:null,t:"エリー、スープを最後まで飲む。"},{w:null,t:"アレク、アナの方を一回だけ見る。"},{w:"alek",t:"（鍋をのぞいて）お代わり、まだあるで。",v:"19_0055"},{w:null,t:"エリー、首を小さく横にふる。"},{w:"alek",t:"（一段低い声で）……お茶。",v:"19_0058"},{w:"ana",t:"朝まで寝てて。今夜は、みんなとロビーね。",v:"19_0061"},{w:"elly",f:"serious",t:"……ここ、まだちょっと痛いんだけど。",v:"19_0068"},{w:"hero",f:"sad",t:"……悪かった。",v:"19_0069"},{w:"elly",t:"お姉ちゃんのジャムパン、一個で許してあげる。",v:"19_0070"},{w:"hero",f:"serious",t:"……二個やる。",v:"19_0071"}];
GR_SC.g19_03=[{w:null,t:"東の空が、うっすら白くなりはじめたころ。",v:"19_0074"},{w:null,t:"薄暗いロビー。"},{w:null,t:"もう一つのソファで、エリー。"},{w:null,t:"窓ガラスが、かたかたと小さく鳴る。"},{w:null,t:"エリーの手首の画面が鳴る。"},{w:"ana",t:"エリー、起きてる？　丘の上に、何か来た。",v:"19_0079"},{w:"ana",t:"あんたたちは、ホテルから出ないで。",v:"19_0080"},{w:null,t:"三人、窓にかけ寄る。"},{w:null,t:"坂の上。ため池の向こうの丘の頂上。"},{w:"elly",t:"お姉ちゃん、まだ池にいる！",v:"19_0084"},{w:"hero",t:"行くぞ！",v:"19_0085"},{w:"alek",t:"待て待て待て、出るな言われたやろ！",v:"19_0086"}];
GR_SC.g19_04=[{w:null,t:"三人が丘に駆け上がる。"},{w:null,t:"くぼみの前に、巨体が立っている。"},{w:null,t:"その足もとに、ヴィクター。"},{w:null,t:"アトラードが、低く長い一声をあげる。"},{w:null,t:"ヴィクター、ゆっくり歩いて、くぼみのうしろの崩れた壁の上に上がる。"},{w:null,t:"アトラード、池の方へ一歩出る。"},{w:"ana",t:"（土手から、声をはり上げて）エリー！　出るなって言ったでしょ！",v:"19_0102"},{w:"hero",f:"serious",t:"……うわ。",v:"19_0106"},{w:"x",n:"三人",t:"進化！",v:"19_0110"},{w:"alek",t:"レベル70、光と地や。冗談きついわ、ほんま。",v:"19_0118"},{w:"hero",t:"（小さく）……倍じゃねえか。",v:"19_0120"},{w:"victor",t:"ヴァンプロード。やれ。",v:"19_0124"}];
GR_SC.g19_08=[{w:null,t:"ヴィクター、崩れた壁の上で、手首の画面を空中に広げる。知らない国の人の顔が、いくつも並ぶ。"},{w:null,t:"倒れたピリポンを抱いたエリーが、流れる訳の字を見ている。"},{w:null,t:"エリー、腕の中のピリポンの頭に、ほおを寄せる。"},{w:null,t:"ヴィクター、画面の顔たちに向かって、また話しだす（外国の言葉・字幕なし）。"},{w:null,t:"その声が始まると、アトラードの大きな顔が、ゆっくりヴィクターの方へ戻る。"},{w:null,t:"ヴィクター、話を終えて画面を閉じる。"},{w:"elly",f:"serious",t:"……わたしを、連れていかないの？",v:"19_0200"},{w:"victor",t:"起こし方は、もう読んでもらった。",v:"19_0201"},{w:null,t:"ヴィクター、指輪の指で、自分の手首の画面のふちを、とん、とん。"},{w:"victor",t:"見に来い。おまえの読んだ字の、使い道だ。",v:"19_0203"},{w:null,t:"ヴィクターの手首の画面が、空中に字を一行だけ映す。"},{w:null,t:"ヴィクター、坂を下りていく。"},{w:null,t:"ヤマト、石の床に手をつく。"},{w:null,t:"ヤマト、ひざを立てる。"},{w:"hero",f:"serious",t:"……次は、勝つ。",v:"19_0208"},{w:null,t:"ヴィクター、足を止めない。"},{w:null,t:"ヤマト、倒れたフォルンの横に、またひざをつく。"},{w:null,t:"アトラード、くぼみの中に体を丸めて、横になる。長い寝息。"},{w:null,t:"池の向こうの土手から、アナが坂を駆け上がってくる。"},{w:null,t:"ヤマト、ひざをついたまま、倒れたフォルンを見ている。フォルンの左の前足が、小さくふるえている。"}];
GR_SC.g19_09=[{w:null,t:"その日、アトラードは丘の上で、一日じゅう眠っていた。",v:"19_0216"},{w:null,t:"ホテルのロビー。"},{w:null,t:"フォルンは窓のふちで、丘の上の巨体を見ている。"},{w:null,t:"アレク、窓のふちのフォルンの左の前足に、目をやる。"},{w:"alek",t:"……フォルンの足、医者に見せとこか。",v:"19_0220"},{w:null,t:"エリーが、ぬれたタオルを持ってくる。だまって、フォルンの左の前足に巻く。"},{w:null,t:"フォルン、よけない。"},{w:"alek",t:"……朝一で、おれが連れてくわ。",v:"19_0223"},{w:null,t:"ヤマト、何も言わない。"},{w:null,t:"アレク、それを見て、口に放りこむ。"}];
GR_SC.g19_10=[{w:null,t:"夜。ロビーの明かりは、すみの小さな灯りだけ。"},{w:null,t:"ヤマト、ソファのはしに座っている。"},{w:null,t:"ヤマト、フォルンを両腕ですくい上げる。"},{w:"hero",t:"お前は、もう出なくていい。",v:"19_0234"},{w:null,t:"ヤマトの腕に、力が入る。"},{w:null,t:"フォルン、身をよじる。"},{w:null,t:"フォルン、床に下りる。"},{w:null,t:"ヤマトに背中を向けて、丸くなる。目を閉じる。"},{w:null,t:"ヤマトの腕は、抱えた形のまま、空っぽ。"},{w:null,t:"ヤマト、その腕をゆっくり下ろす。"},{w:null,t:"ヤマト、窓の外を見る。"},{w:null,t:"ヤマト、画面を閉じる。"},{w:null,t:"ヤマト、立ち上がる。"},{w:null,t:"ロビーの戸を、音を立てずに開けて、出ていく。"}];
GR_BT[19]={mid:[[{w:"hero",t:"フォルレオン、一回当てたら、すぐ下がれ！",v:"19_0128"},{w:"alek",t:"クロベク、池のふちに立て！",v:"19_0134"}],[{w:null,t:"エリー、ピリムサの背中を見る。"},{w:null,t:"エリー、手首の白い画面をかざす。"},{w:"elly",t:"ピリムサ、進化！",v:"19_0146"},{w:"elly",t:"ナルカミ、カミナリオトシ！",v:"19_0152"},{w:null,t:"ヤマト、アレクを見る。アレク、うなずく。"},{w:null,t:"ヤマトとアレク、手首の画面をかざす。"},{w:"x",n:"二人",t:"融合！",v:"19_0156"},{w:"hero",t:"グレンカイザー、紅蓮竜顎（ぐれんアギト）！",v:"19_0158"}],[{w:"alek",t:"赤いとこから出ろ！",v:"19_0168"}]],post:[{w:null,t:"ナルカミだけ、走らない。"},{w:null,t:"聖地重圧。空をささえるような大きな力が、上から赤い床にのしかかる。"},{w:null,t:"重さが、すっと抜ける。"},{w:"alek",t:"……羽閉じられたら、何も通らへん。",v:"19_0186"}]};
GR_EP[19]={"t": "空の寝床", "sc": [["g19_01", "ホテルの裏口（夜ふけ）", 0], ["g19_02", "ホテルの台所（夜ふけ）", 0], ["g19_03", "ホテルのロビー（東が白むころ）", 0], ["g19_04", "丘の上・研究所あと（東が白むころ）", 0], ["g19_05", "勝負・全部出す", 1], ["g19_06", "勝負・ナルカミ", 1], ["g19_07", "勝負・つぶされる", 1], ["g19_08", "負けのあと（日の出前）", 0], ["g19_09", "オリーヴァ村（昼）", 0], ["g19_10", "ホテルのロビー（夜）", 0]]};
GR_SC.g20_01=[{w:null,t:"オリーヴァ村。負けた次の日の、夜明け前。",v:"20_0028"},{w:null,t:"堰のすぐ横に、アトラードが座っている。大きな右手が、要石の上にのっている。"},{w:null,t:"堰の下から坂が始まる。"},{w:null,t:"池のまわりを、チップの子たちがぐるりと囲んでいる。目の奥に、オレンジの光。"},{w:null,t:"池のそばの道に、黒い車が一台。"}];
GR_SC.g20_02=[{w:null,t:"村の坂道。家々は暗い。"},{w:null,t:"ヤマトが一人で、坂道を歩いてくる。"},{w:null,t:"ヤマト、丘のすその、畑のあいだの細い道を回っていく。"},{w:null,t:"丘の向こうの、小さな石の家（2話のおばあさんの家）。"},{w:null,t:"ヤマト、戸の前で止まる。手を上げる。"},{w:null,t:"もう一回上げて、戸をたたく。"},{w:null,t:"戸が開く。おばあさん。"},{w:"hero",t:"おばあさん、研究所で働いてたんだろ。",v:"20_0044"},{w:"hero",t:"あのでっかいやつのこと、教えてくれ。",v:"20_0045"},{w:"oba",t:"研究所の人が呼ぶと、そっちを向く。",v:"20_0049"},{w:"oba",t:"呼ぶのをやめるとね、こっちを向いた。",v:"20_0050"},{w:"hero",t:"おばあさんの方？",v:"20_0051"},{w:"oba",t:"掃除しながら歌ってた声の方。",v:"20_0052"},{w:null,t:"第20話　オリーヴァのため池",v:"20_0058"}];
GR_SC.g20_03=[{w:null,t:"食堂。エリーが、テーブルでパンをちぎっている。"},{w:null,t:"となりの席に、手つかずのパンの皿が一つ。"},{w:null,t:"アレクは窓ぎわで、古い望遠鏡のレンズを布でふいている。"},{w:null,t:"窓ぎわの日だまりで、フォルンが丸くなっている。"},{w:null,t:"アナが、焼きたてのパンのかごを運んでくる。"},{w:null,t:"窓ぎわのアレク、望遠鏡をふく手が止まる。"},{w:"alek",t:"（一段低い声で）実は僕、ぶどう畑を三つ持ってまして。",v:"20_0070"},{w:"alek",t:"（一段低い声で）お姉さん、僕とお茶しません？",v:"20_0071"},{w:null,t:"アナ、パンのかごをテーブルに置く。"},{w:"ana",t:"……どこの畑？",v:"20_0073"},{w:null,t:"アレク、前髪をなでつけた手のまま、止まる。"},{w:null,t:"足もとのクロッコは、あくびをして目を閉じる。"},{w:null,t:"アナ、エプロンのポケットから画面を出して、テーブルの上に表を広げる。"},{w:"ana",t:"見張りの順番、決めたから。アレクは、今夜のホテルの番ね。",v:"20_0077"},{w:"alek",t:"（声がもとに戻って）夜通しっすか。",v:"20_0078"},{w:"ana",t:"（表を見たまま）畑、三つあるんでしょ。一晩くらい、見張れるよね。",v:"20_0079"},{w:"alek",t:"……ホテルの番で、お願いします。",v:"20_0080"},{w:null,t:"アナ、もう次の表を開いている。"},{w:null,t:"食堂の入口に、ヤマトが立っている。口を手でおさえている。"},{w:"alek",t:"朝飯、残しといたで。冷めてもうたけど。",v:"20_0084"},{w:"elly",t:"ヤマト、朝早くから、どこ行ってたの？",v:"20_0088"},{w:"hero",t:"おばあさんち。",v:"20_0089"},{w:"elly",t:"おばあちゃんち？　なんで？",v:"20_0090"},{w:"hero",f:"serious",t:"……あとで言う。",v:"20_0091"}];
GR_SC.g20_04=[{w:null,t:"坂の途中のテラス。"},{w:null,t:"フォルンは、テラスのはしの植木鉢の横。"},{w:null,t:"アナが、空中の画面をいくつも開いたまま、テラスに出てくる。"},{w:null,t:"アナ、ヤマトの見ている先に、目をやる。"},{w:"ana",t:"要石。あれが落ちたら、坂の下が水につかるの。",v:"20_0098"},{w:null,t:"ヤマト、坂の下の村の屋根を見る。"},{w:null,t:"アナ、画面の表を一つ閉じる。"}];
GR_SC.g20_05=[{w:null,t:"ホテルの裏。"},{w:null,t:"フォルンは、ヤマトから二歩はなれた石の上。"},{w:null,t:"ヤマト、土に棒で描く。口を開けた顔と、大きな頭。"},{w:null,t:"口を、×で消す。"},{w:"elly",t:"で、おばあちゃん、なんて？",v:"20_0107"},{w:null,t:"ヤマト、答えないで、棒の先で小さい顔をつつく。それから、エリーを指さす。"},{w:null,t:"エリー、小さな顔を見て、自分を指さす。"},{w:null,t:"アレク、絵を見て、少し考えて、うなずく。"},{w:"alek",t:"で、あのコウモリ、だれが押さえんねん。おれは嫌やで。",v:"20_0111"},{w:null,t:"ヤマトの目が、二歩先のフォルンの背中に行く。"},{w:"hero",t:"融合で行く。おれとお前だ。",v:"20_0114"},{w:"elly",t:"じゃあ、わたしは、あの子のそばまで行く。",v:"20_0117"},{w:"alek",t:"やばなったら、すぐ戻りや。",v:"20_0119"},{w:"elly",t:"うん。",v:"20_0120"},{w:"ana",t:"エリー、池に来て。チップの子たちが、みんなを追い出してる。",v:"20_0123"},{w:"elly",t:"グリフォは、ここにいて。ホテルをお願い。",v:"20_0125"}];
GR_SC.g20_06=[{w:null,t:"夜のため池。"},{w:null,t:"池の左の土手。"},{w:null,t:"坂の上の黒い車。"},{w:null,t:"チップの子たちのあいだから、雷の子が一体、前に出る。"},{w:null,t:"【プロフィール】トールジン／雷／●●○／火花をまとう雷の子"},{w:null,t:"トールジン、水ぎわの石に前足をのせる。"},{w:null,t:"池のまん中に浮いた水鳥の子は、顔も上げない。"},{w:null,t:"三人が、土手のはしに駆けつける。"},{w:null,t:"アレク、頭のゴーグルを下ろしてかける。"},{w:null,t:"ヤマトは、村の人たちの前に立つ。"},{w:null,t:"クロッコだけが、池に入る。"},{w:null,t:"エリーとアレク、手首の画面をかざす。"},{w:"x",n:"二人",t:"進化！",v:"20_0150"},{w:null,t:"その場で約3秒。"},{w:null,t:"光っている間は、二体とも動かない。"}];
GR_SC.g20_10=[{w:null,t:"クロコディロス、へりの水に首を下ろす。"},{w:null,t:"ナルカミも光が引いて、ピリポンに戻る。"},{w:null,t:"ヤニスが、熱を通さない銀色のシートを、アレクの肩にかける。"},{w:null,t:"エリーが駆けよって、アレクの顔をのぞきこむ。"},{w:"elly",t:"アレク、だいじょうぶ？",v:"20_0238"},{w:null,t:"アレク、歯をがちがち鳴らしながら、片手を上げる。"},{w:"alek",t:"……このパーカー、一枚しかないねんぞ。",v:"20_0240"},{w:null,t:"エリー、ほっとして笑う。"},{w:null,t:"アナが、クロッコの頭を両手でわしわしなでる。クロッコ、目を細める。"},{w:null,t:"土手のはしの、暗いオリーブの木の下。"},{w:null,t:"ヤマト、フォルンの背中を見る。"}];
GR_SC.g20_11=[{w:null,t:"東の空の下のふちが、ほんの少しだけ白みはじめる。"},{w:null,t:"坂の下の家々は、明かりが一つもない。"},{w:null,t:"空のあちこちに、小さな明かりが一つ、また一つ。"},{w:null,t:"堰のそば。アトラードの大きな目が、ゆっくり開く。"},{w:null,t:"ホテルの裏口の前で、グリフォが顔を上げる。"}];
GR_BT[20]={mid:[[{w:"alek",t:"クロベク！",v:"20_0165"}],[{w:null,t:"アレク、土手の奥から駆けだす。"},{w:null,t:"アレク、へりのふちで、一回だけ暗い水を見る。それから、ふり返る。"},{w:null,t:"アレク、前を向く。"},{w:"elly",t:"アレク！",v:"20_0180"},{w:"elly",t:"ナルカミ、あの子を止めて！",v:"20_0181"},{w:"alek",t:"クロベク、進化！",v:"20_0196"}],[{w:null,t:"アレク、クロコディロスの頭の上で、水ぎわと池のまん中を見くらべる。"},{w:null,t:"アレク、ずぶぬれのまま、水ぎわのトールガを見る。"},{w:"alek",t:"クロコディロス、押し返せ！",v:"20_0215"},{w:null,t:"アレク、頭の上から、池のまん中をふり返る。"},{w:null,t:"アレク、へりのヤマトを見る。"},{w:"alek",t:"（ヤマトに）……まん中まで来たら、雷、散ってまうんや。",v:"20_0223"},{w:"elly",t:"（ロープをたぐりながら）しゃべってないで、つかまって！",v:"20_0225"},{w:"alek",t:"……お前、手ぇ真っ赤やん。",v:"20_0230"}]],post:[]};
GR_EP[20]={"t": "オリーヴァのため池", "sc": [["g20_01", "オリーヴァ村の引き（夜明け前）", 0], ["g20_02", "村の坂道〜おばあさんの家（夜明け前）", 0], ["g20_03", "ホテルの食堂（朝）", 0], ["g20_04", "アナのホテルのテラス（朝）", 0], ["g20_05", "ホテルの裏のぶどう畑（夜）", 0], ["g20_06", "ため池の土手（夜）・頭", 0], ["g20_07", "土手の上の勝負・押される", 1], ["g20_08", "池の中・初めてかむ", 1], ["g20_09", "その場で押し返す・決着", 1], ["g20_10", "勝負のあと（夜ふけ）", 0], ["g20_11", "ため池の上の丘（夜明け前）", 0]]};
GR_SC.g21_01=[{w:null,t:"夜明けまで、あと少し。",v:"21_0028"},{w:null,t:"東の空のふちが、白みはじめている。"},{w:null,t:"アレクが戸口で、パーカーのフードをかぶりながら、ヤマトの腕を引っぱっている。"},{w:"alek",t:"急げや！　もう見物のドローンが来てるで！",v:"21_0031"},{w:null,t:"ヤマトは、寝ていない顔。"},{w:null,t:"エリーが、裏口へ走りながら、ジャムをぬったパンをヤマトの手に押しこむ。"},{w:"elly",t:"ほら、ご飯、先。走りながらでいいから。",v:"21_0034"},{w:"hero",f:"serious",t:"……今？",v:"21_0035"},{w:"elly",t:"今。",v:"21_0036"},{w:null,t:"ヤマト、走りながら、パンを二口で食べる。口のはしに、ぶどうのジャム。"},{w:"alek",t:"待て待て、それ、おれの分のジャムやろ！",v:"21_0038"},{w:null,t:"ヤマト、もう飲みこんでいる。"}];
GR_SC.g21_02=[{w:null,t:"ため池より高いオリーブ畑の段。"},{w:null,t:"坂の下の家々は、明かりが一つもない。"},{w:null,t:"三人が、段の下の道を、堰の方へ上がっていく。"},{w:"alek",t:"（エリーに）お前、上着は。夜明けは冷えるで。",v:"21_0048"},{w:null,t:"エリー、アレクのパーカーのそでを、指でつまむ。"},{w:"elly",t:"アレクこそ。それ、まだ乾いてないでしょ。",v:"21_0050"},{w:null,t:"アレク、そでを引っこめる。"},{w:"elly",t:"お姉ちゃん、下のみんなは？",v:"21_0052"},{w:"ana",t:"夜のうちに、みんな上に来た。",v:"21_0053"},{w:null,t:"アナの手首の画面。送り主の丸い写真に、エリーとおばあさんが並んで笑っている。"},{w:"elly",f:"serious",t:"……行ってくるね。",v:"21_0059"},{w:"ana",t:"うん。",v:"21_0060"}];
GR_SC.g21_03=[{w:null,t:"堰の頭の要石。"},{w:null,t:"堰の手前の、古い石だたみの広場。"},{w:null,t:"石段の下に、ヴァンプロード。"},{w:null,t:"石段のはしに、カシア。"},{w:null,t:"カシアの手首の画面から、空中に買い手の顔の画面をいくつも開いている。"},{w:null,t:"堰のはしに、ゼノ。"},{w:null,t:"まわりに、チップの子たち。"},{w:null,t:"三人が、広場の入口に立つ。"},{w:"hero",t:"（石段のはしを見て）ピアスのおばさんも、いんのかよ。",v:"21_0073"},{w:"kasia",t:"（画面から目を上げずに）誰がおばさんよ。何回言わせるの。",v:"21_0074"},{w:null,t:"アレクの足もとから、クロッコが池へすべりこむ。"},{w:"victor",t:"遅かったな。",v:"21_0076"},{w:null,t:"ヴィクター、空のドローンへ向かって、買い手の言葉で話す（字幕）。"},{w:"victor",t:"（買い手の言葉・字幕）あの石を、持ち上げてご覧に入れます。",v:"21_0078"},{w:null,t:"第21話　夜明けの決戦",v:"21_0080"}];
GR_SC.g21_04=[{w:null,t:"ヴィクター、指輪の指で、石段の手すりを、とん、とん。"},{w:null,t:"ヴィクターが古代ギリシャ語で一言。"},{w:null,t:"アトラード、要石に両手をかけ、ゆっくり持ち上げる。"},{w:null,t:"ヴィクター、見上げたまま、とん、とん。"},{w:null,t:"少しして、また。"},{w:null,t:"エリー、一歩前に出る。"},{w:"elly",t:"わたし、あの子のそばに行く。",v:"21_0094"},{w:null,t:"ヴィクター、エリーを見る。笑顔。"},{w:"victor",t:"好きにしろ。",v:"21_0096"},{w:"victor",t:"こいつに、おまえの声は届かん。",v:"21_0097"},{w:null,t:"ヴィクター、ヴァンプロードに目だけやる。自分の耳を、指輪の指で、とん、とん。"},{w:"victor",t:"聞け。",v:"21_0099"},{w:null,t:"ヴァンプロードの頭の、大きな二つの耳が、ゆっくりヤマトの方を向く。"},{w:null,t:"ヴィクターは、もうアトラードを見上げている。"},{w:null,t:"ヴァンプロード、石だたみの広場のまん中まで歩いて、止まる。"},{w:null,t:"東の空が白くなる。ヴァンプロード、目を細めて、顔をそむける。"},{w:null,t:"頭の上の二つの耳だけが、大きく開く。"},{w:null,t:"チップの子たちが、エリーとアトラードのあいだに並んで、道をふさぐ。"}];
GR_SC.g21_12=[{w:null,t:"日が昇る。座りこんだアトラードの足もとで、エリーがグリフォの頭に手を置いている。"},{w:null,t:"堰の上のヤマト、手すりから身を乗り出す。"},{w:"hero",t:"エリー、さっきの。",v:"21_0260"},{w:"elly",t:"（見上げて）なに？",v:"21_0261"},{w:null,t:"ヤマト、口をあけたまま止まる。"},{w:"hero",f:"serious",t:"……なんでもねえ。",v:"21_0263"},{w:null,t:"エリー、首をかしげる。"},{w:"elly",t:"（下から手をふって）ヤマトー！　口、ジャムついてるー！",v:"21_0265"},{w:null,t:"堰の上のヤマト、手の甲で口をこする。"},{w:null,t:"となりのアレク、ふきだしかけて、顔をそむける。"},{w:null,t:"石段の上で、ヴィクター。もう笑顔に戻っている。"},{w:null,t:"ヴィクターのまわりに浮かぶ買い手の画面の一つから、声（字幕）。"},{w:"x",n:"買い手の声",t:"（字幕）……言葉一つで、じゃなかったのか。",v:"21_0271"},{w:null,t:"買い手の画面が、一つ、また一つと暗くなって消えていく。"},{w:null,t:"石だたみ。ヤマト、ヴァンプロードのそばにしゃがむ。"},{w:null,t:"フォルレオンが、遠くへ飛んだかけらを一つくわえてくる。"},{w:null,t:"ヤマト、かけらを全部、上着の胸ポケットに入れる。"},{w:null,t:"坂を上がってくるエリーのおばあさん。年寄りの手を引いて、小さく片手を上げる。"},{w:null,t:"坂の下の、だれもいない村の屋根に、朝日が当たる。"},{w:null,t:"画面の前に、レン。足もとで、バジリクが目を開けている。"},{w:null,t:"空の見物のドローンが、一機、また一機と、向きを変えて離れていく。"},{w:null,t:"最後に、朝日の中のヴィクターの笑顔だけ。"}];
GR_BT[21]={mid:[[{w:null,t:"ヤマト、手首の画面を上げる。"},{w:null,t:"ヤマト、フォルンの背中を見る。それから、手首の画面をかざす。"},{w:"x",n:"三人",t:"進化！",v:"21_0113"},{w:null,t:"ヤマト、フォルレオンの背中へ、指をそろえた右の手のひらを立てる。"},{w:null,t:"ヤマト、手を下ろす。"},{w:"hero",t:"アレク、エリー。行くぞ。",v:"21_0121"},{w:"alek",t:"言われんでも行くわ。早よ終わらそ。",v:"21_0122"},{w:"elly",t:"ナルカミ、道をあけて！",v:"21_0123"},{w:null,t:"アレク、だまって堰のはしまで出る。"},{w:"alek",t:"（ゴーグルごしに、石段のはしのカシアへ）あん時の輪っか、利子つけて返したるで。",v:"21_0132"}],[{w:null,t:"ヤマトとアレク、堰の上のはしに立つ。"},{w:"hero",t:"フォルレオン、右から回れ！",v:"21_0138"},{w:"hero",t:"跳べ！　上からだ！",v:"21_0142"},{w:"hero",t:"フォルレオン、灼熱地獄！",v:"21_0145"},{w:null,t:"ヤマト、ヴィクターの口を見る。"},{w:"alek",t:"クロコディロス、かめ！",v:"21_0157"},{w:null,t:"カシア、ヨルフクを片手で拾い上げる。"},{w:null,t:"カシアのまわりの、買い手の顔の画面。"},{w:null,t:"カシア、自分の手首の画面を閉じる。"},{w:"kasia",t:"ヴィクターさま。買い手には、わたしから謝っておきます。",v:"21_0164"}],[{w:null,t:"ヤマト、肩で息をしている。"},{w:null,t:"ヤマト、口をあける。"},{w:"hero",t:"フォル——",v:"21_0178"},{w:null,t:"ヤマト、口を閉じる。"},{w:"hero",t:"アレク！",v:"21_0183"},{w:"hero",f:"serious",t:"……行け、フォルン。",v:"21_0199"}],[{w:"victor",t:"右だ！",v:"21_0211"},{w:"victor",t:"下がれ！　羽を閉じろ！",v:"21_0213"},{w:null,t:"ヴィクターの口が、勝負の方を向いている。"},{w:"elly",t:"（古代ギリシャ語・字幕）お願い。そっと、もどして。",v:"21_0221"},{w:null,t:"ヴィクター、ふり返る。"},{w:null,t:"ヴィクターの顔から、笑顔が消える。"},{w:"victor",t:"（古代ギリシャ語・字幕）持ち上げろ！",v:"21_0229"},{w:"victor",t:"ゼノ！　狐を止めろ！",v:"21_0235"},{w:null,t:"ヤマト、口を閉じたまま。"},{w:null,t:"ヤマト、空のフォルレオンを見ない。ヴァンプロードの耳だけを見て、息を吸う。"},{w:"hero",t:"灼熱地獄！！",v:"21_0241"}]],post:[{w:null,t:"ヴァンプロード、石だたみの上にどさりと倒れる。目を回している。"},{w:null,t:"首のうしろのチップに、ぴしっとひびが走る。"},{w:null,t:"フォルレオン、倒れたヴァンプロードの前で、肩で大きく息をしている。"},{w:"hero",f:"smile",t:"……へへっ。やったな、フォルン。",v:"21_0249"},{w:"alek",t:"（ヤマトの肩を小突いて）……耳、お前の声の方しか向いてへんかった。",v:"21_0251"}]};
GR_EP[21]={"t": "夜明けの決戦", "sc": [["g21_01", "アナのホテルの台所から裏口へ（夜明け前）", 0], ["g21_02", "坂の上のオリーブ畑（夜明け前）", 0], ["g21_03", "堰の前（夜明け前）", 0], ["g21_04", "持っていろ", 0], ["g21_05", "勝負・頭", 1], ["g21_06", "勝負・読まれる", 1], ["g21_07", "アレクとカシア", 1], ["g21_08", "手を開く", 1], ["g21_09", "読めない", 1], ["g21_10", "お願い", 1], ["g21_11", "決着", 1], ["g21_12", "日が昇る", 0]]};
GR_SC.g22_01=[{w:null,t:"決戦の日の夕方。運河の町、コリンタ。",v:"22_0026"},{w:null,t:"ヤマトの上着とズボンが、けさの勝負の土ぼこりで、まだ白い。"},{w:null,t:"橋のたもとの机。"},{w:null,t:"白いロボタクシーが止まる。"},{w:"alek",t:"ここ、ヴィクターんとこの机やん。",v:"22_0031"},{w:"hero",t:"名札のおっさん、決まりは守るだろ。",v:"22_0032"},{w:null,t:"ヤマト、机の前に立つ。"},{w:null,t:"かけらを、机の上に、ばらばらと置く。"},{w:null,t:"ノモス、端末から目を上げない。"},{w:"nomos",t:"机に物を置くのは、禁止です。",v:"22_0036"},{w:null,t:"ヤマト、かけらを一つつまんで、端末の画面の上に置く。"},{w:null,t:"ノモスの指が止まる。"},{w:"nomos",t:"……決まりですから。",v:"22_0041"},{w:null,t:"ノモス、端末に打ちはじめる。"},{w:null,t:"ヤマト、もう背を向けている。"},{w:null,t:"ヤマトの肩のフォルン、ふり向きざまに、机の名札をしっぽでぺしっ。"}];
GR_SC.g22_02=[{w:null,t:"次の朝。オリーヴァ村。",v:"22_0047"},{w:null,t:"窓ぎわに、洗ったヤマトの上着が干してある。"},{w:null,t:"ロビーの空中の画面に、ニュース。"},{w:null,t:"画面の前で、アナが腕を組んで見ている。"},{w:null,t:"窓の外。丘の上の研究所あとで、アトラードが自分の寝床に丸くなって眠っている。"},{w:null,t:"第22話　オリーブの坂",v:"22_0054"}];
GR_SC.g22_03=[{w:null,t:"丘の上。寝床で眠るアトラードの足もとに、白いテーブルと椅子が一つ。"},{w:null,t:"少しうしろに、ゼノ。"},{w:null,t:"ヴィクターのまわりに、空中の画面が一つも浮いていない。"},{w:null,t:"三人が丘を上がってくる。"},{w:null,t:"ヴィクター、カップを置かない。三人を見て、笑顔。"},{w:null,t:"ゼノが、手首の画面を開く。"},{w:null,t:"ゼノ、ヴィクターの方は見ない。"},{w:null,t:"チップの子たちが、まばたきをする。"},{w:null,t:"池のそば。伏せていたヴァンプロードが、ゆっくり首を上げる。"},{w:null,t:"ヴィクター、紅茶を一口飲む。"},{w:null,t:"ゼノ、胸のオレンジの輪の胸章に指をかけて、外す。"},{w:"zeno",t:"仕事は、ここまでだ。",v:"22_0072"},{w:null,t:"ヴィクター、胸章を見て、それからゼノの顔を見る。"},{w:null,t:"うしろの手下たちが、顔を見合わせる。"},{w:null,t:"手下たち、ばらばらの方へ坂を下りていく。"},{w:null,t:"ヴィクター、立ち上がる。"}];
GR_SC.g22_04=[{w:null,t:"ヴィクター、歩きだす。"},{w:null,t:"ヴィクター、エリーを見る。客に向けた笑顔ではない。"},{w:"victor",t:"才能があるな。",v:"22_0081"},{w:null,t:"エリーは、何も言わない。笑わない。"},{w:null,t:"ヴィクター、歩きだす。"},{w:null,t:"ヤマトの肩のフォルンが、濃い灰色のスーツをにらんで、のどの奥で低くうなる。"},{w:null,t:"ヴィクター、フォルンを一度だけ見る。"},{w:null,t:"池のそば。ヴァンプロードが目をあけて、坂を下りていく濃い灰色のスーツを見る。"},{w:null,t:"丘の上の寝床。アトラードが、ゆっくり目をあける。"},{w:null,t:"丘の上のテーブル。"}];
GR_SC.g22_05=[{w:null,t:"坂の曲がり角。"},{w:null,t:"ヴィクター、その前で止まる。"},{w:"victor",t:"（古代ギリシャ語・字幕）どけ。",v:"22_0095"},{w:null,t:"アトラード、片目だけあける。"},{w:null,t:"……目を閉じる。"},{w:null,t:"ヴィクター、その前で、立ちつくす。"},{w:null,t:"ヴィクターの指輪の指が、そばの石を、とん、と一回。"},{w:null,t:"ヴィクター、その手を見る。"},{w:null,t:"ヴィクター、指輪を外す。"},{w:null,t:"ヴィクターの手が、胸ポケットへ行きかけて、止まる。"},{w:null,t:"エリーは、目をそらさずに見ている。"},{w:null,t:"画面の字「届け出：決まりに反する荷」。"},{w:null,t:"坂の下から、黒い車が一台、静かに上がってきて止まる。"},{w:null,t:"車から、紺の制服の人が三人降りる。"},{w:null,t:"一人が、ヴィクターの前に立つ。"},{w:null,t:"その横に、割れたチップのかけらの写真。"},{w:null,t:"その下に、届け出の名前の欄。"},{w:null,t:"ヴィクター、画面を見る。笑顔のまま、自分から両手を前に出す。"},{w:null,t:"その手首に、光る輪がかかる。"},{w:null,t:"ヴィクター、制服の人にはさまれて、黒い車に乗る。"},{w:null,t:"黒い車が、坂を下りていく。"}];
GR_SC.g22_06=[{w:null,t:"アナのホテル。"},{w:null,t:"ヤニスの畑。"},{w:"x",n:"村の男の子",t:"……どけ。",v:"22_0125"},{w:"x",n:"村の女の子",t:"やだ。",v:"22_0126"},{w:null,t:"二人、笑って、畑の中へ走って逃げていく。"},{w:null,t:"6話の森の村。"},{w:null,t:"赤紫の長い髪の女。"},{w:null,t:"ニーナとマルコ。だまって、苗を土に置いている。"},{w:null,t:"丘の上の寝床。"},{w:null,t:"眠るアトラードの大きな顔が、歌の聞こえる方へ、少しだけ向いている。"}];
GR_SC.g22_07=[{w:null,t:"白い都の相棒の登録の窓口。"},{w:null,t:"アナ、エリー、グリフォ。"},{w:"x",n:"係の人",t:"相棒の登録ですね。お名前を、どうぞ。",v:"22_0141"},{w:"ana",t:"アナです。世話も旅も、この子です。",v:"22_0142"},{w:null,t:"アナ、エリーの手首を、板の横に並べさせる。"},{w:"x",n:"係の人",t:"では、どうぞ。",v:"22_0144"},{w:null,t:"グリフォ、エリーを見る。"},{w:null,t:"板が光る。「登録完了」。"},{w:"elly",t:"ねえ、いま、わたし見て決めたよね？",v:"22_0147"},{w:"ana",t:"早っ。フォルンなんて、わたしの板、しっぽではらったのにね。",v:"22_0148"},{w:null,t:"ヤマト、光る板の付き添いの欄に、指で名前を書いている。"},{w:"hero",t:"（書きながら）フォルンは、じっくり選んだからな。",v:"22_0150"},{w:null,t:"頭の上のフォルン、ぷいとそっぽを向く。しっぽの火だけ、ぼっと大きくなる。"},{w:null,t:"かがんだヤマトの前髪が、ちりちり焦げる。"},{w:"alek",t:"（長いすから）クロッコ、消してやれ。",v:"22_0153"},{w:"ana",t:"エリー、ごはんの量、ここに書いといて。",v:"22_0157"}];
GR_SC.g22_09=[{w:null,t:"空港の待合。"},{w:null,t:"アレク、ヤマトの横に並ぶ。"},{w:"alek",t:"……最初から、目ぇつぶらせてたんか。",v:"22_0215"},{w:null,t:"ヤマト、前を向いたまま、手のひらを一回だけ見せる。"},{w:null,t:"アレク、ヤマトの頭を一回はたいて、エリーたちの方へ下がる。"},{w:null,t:"案内の声。「中国行き、ご搭乗を開始します」。"},{w:null,t:"バジリクが、レンのうしろをのそのそついていく。"},{w:null,t:"搭乗口の手前。"},{w:null,t:"レン、顔だけ半分ふり向く。"},{w:null,t:"レンとバジリク、そのまま搭乗口へ入っていく。"},{w:null,t:"少しはなれた所。"},{w:"ana",t:"どうせ行くんでしょ。ご飯、ちゃんと食べるんだよ。",v:"22_0225"},{w:"elly",t:"お姉ちゃんもね。",v:"22_0226"},{w:"alek",t:"（横から）アナさん、僕の分は？",v:"22_0227"},{w:null,t:"アナ、アレクの方は見ない。"}];
GR_SC.g22_10=[{w:null,t:"空港の屋上。"},{w:null,t:"手すりの前に、ヤマト。"},{w:null,t:"見送りの場所の係の女の人が、手すりの前を回ってくる。"},{w:"alek",t:"（一段低い声で）実は僕、白い都に家が三軒ありまして。",v:"22_0237"},{w:"alek",t:"（一段低い声で）お姉さん、案内しましょか？",v:"22_0238"},{w:null,t:"エリーの髪の中から、ピリポンが顔を出す。"},{w:null,t:"アレクの青い髪が、ふわっと逆立つ。"},{w:null,t:"ヤマト、手首の画面を開く。"},{w:null,t:"ヤマト、打つ。"},{w:null,t:"ヤマト、画面を見たまま、鼻の頭をかく。"},{w:null,t:"三本の柱を丸い輪でかこんだ形。"},{w:null,t:"印の下に、「白い都の大会より　世界大会　出場決定」。"},{w:null,t:"ヤマト、印を二度見する。目が、まん丸になる。"},{w:"hero",f:"serious",t:"……世界大会。",v:"22_0249"},{w:null,t:"ヤマト、手すりをつかんで、その場で一回、高く跳ぶ。"},{w:null,t:"肩のフォルン、ヤマトの頭にしがみつく。しっぽの火が、ぼっ。"},{w:null,t:"エリー、あわてて、ヤマトの上着のすそをつかむ。"},{w:"elly",t:"ヤマト、手すり！　そこ、屋上だよ！",v:"22_0253"},{w:"alek",t:"（うしろから）……世界て。どこでやんねん。",v:"22_0254"},{w:"hero",t:"（手すりから一歩下がりながら）知らねえ。",v:"22_0255"},{w:null,t:"エリー、すそをまだ離さない。"},{w:null,t:"頭の上のフォルン、ヤマトのほっぺに、自分から鼻先をくっつける。"},{w:null,t:"文字盤のふちの小さな印が、六つ光っている。"},{w:"hero",f:"smile",t:"……すっげー。エリー、これ見ろ！",v:"22_0263"},{w:"elly",t:"ねえ、竜の横に、字がある。",v:"22_0265"},{w:"hero",t:"マジか！　読めんのか？",v:"22_0266"},{w:"elly",f:"serious",t:"……まだ。",v:"22_0267"},{w:"hero",t:"次は、中国だ。",v:"22_0269"},{w:"hero",t:"アレク。金、数えといて。",v:"22_0270"},{w:"alek",t:"なんでおれやねん……",v:"22_0271"},{w:"alek",t:"三人と四体で、なんぼやねん、これ……。",v:"22_0273"},{w:"alek",t:"……行きの分は、あるわ。",v:"22_0275"},{w:"elly",t:"中国のラッキースポット、古い石の文字だって！",v:"22_0279"},{w:"elly",f:"serious",t:"……もう。いいもん。",v:"22_0281"}];
GR_BT[22]={mid:[[{w:null,t:"ヤマトが歩いてくる。"},{w:"dimi",t:"一回だけ。",v:"22_0167"},{w:"hero",t:"おう。",v:"22_0168"},{w:null,t:"ヤマト、手首の画面をかざす。"},{w:"hero",t:"フォルン、進化！",v:"22_0172"},{w:null,t:"レンの足もとの土が割れて、バジリクが地面から出る。"},{w:"dimi",f:"serious",t:"……それ、効かない。",v:"22_0176"},{w:null,t:"ヤマト、何も言わない。"},{w:"alek",t:"（となりのエリーに、小さく）……あいつ、半分、闇やん。",v:"22_0181"},{w:null,t:"エリー、だまって、アレクの袖をつかむ。"}]],post:[{w:null,t:"ヤマトの手のひらは、立てたまま。"},{w:null,t:"ほこりの壁を割って、バジリクが顔を出す。"},{w:null,t:"芝のふるえが止まる。"},{w:"dimi",f:"serious",t:"……次も、やる。",v:"22_0203"},{w:"hero",t:"次も、勝つ。",v:"22_0204"}]};
GR_EP[22]={"t": "オリーブの坂", "sc": [["g22_01", "運河の町の橋のたもと（決戦の日の夕方）", 0], ["g22_02", "ホテルのロビー（次の朝）", 0], ["g22_03", "丘の上・研究所あとの前（朝）", 0], ["g22_04", "才能があるな", 0], ["g22_05", "坂の曲がり角", 0], ["g22_06", "村（数日）", 0], ["g22_07", "白い都の相棒の登録の窓口（数日あと）", 0], ["g22_08", "空港の前の芝生（昼）", 1], ["g22_09", "空港の待合（昼）", 0], ["g22_10", "空港の屋上の見送りの場所（夕方）", 0]]};
